local config = {
  ui_story_5033_50330101_X1_dialog_content = "H-Help me...",
  ui_story_5033_50330101_X2_dialog_content = "Help... Urgh...",
  ui_story_5033_50330101_1_dialog_content = "<color=#e8d9bb>Thump!</color>",
  ui_story_5033_50330101_2_dialog_content = "Look, Mom! That person over there fell over while walking!",
  ui_story_5033_50330101_3_dialog_content = "Wait here. Let me go take a look.",
  ui_story_5033_50330101_4_dialog_content = "W-What's this...?",
  ui_story_5033_50330101_5_dialog_content = "<size=45>Aaaaagh!</size>",
  ui_story_5033_50330101_6_dialog_content = "<color=#e8d9bb>An unknown street in Umbraton</color>",
  ui_story_5033_50330101_7_dialog_content = "(I'm too late...)",
  ui_story_5033_50330101_8_dialog_content = "Are you sure you didn't see anyone else around?",
  ui_story_5033_50330101_9_dialog_content = "No... And my son only saw the victim fall.",
  ui_story_5033_50330101_10_dialog_content = "He wobbled a bit before collapsing.",
  ui_story_5033_50330101_11_dialog_content = "By the time I reached him, he was already...",
  ui_story_5033_50330101_12_dialog_content = "All right, got it.",
  ui_story_5033_50330101_13_dialog_content = "I'll handle this. You may leave now.",
  ui_story_5033_50330101_14_dialog_content = "It's not really safe in Umbraton lately, so try not to take secluded paths.",
  ui_story_5033_50330101_15_dialog_content = "Ah...",
  ui_story_5033_50330101_16_dialog_content = "Okay, thank you...",
  ui_story_5033_50330101_17_dialog_content = "Let's go, son. And stop peeking.",
  ui_story_5033_50330101_18_dialog_content = "*Sighs*",
  ui_story_5033_50330101_19_dialog_content = "(Another dead end. Still can't catch up to the perp.)",
  ui_story_5033_50330101_20_dialog_content = "(The only sure thing is this guy died in the same way as the <color=#FFB400>previous victims</color>.)",
  ui_story_5033_50330101_21_dialog_content = "Wait a second!",
  ui_story_5033_50330101_22_dialog_content = "(There are still faint breaths coming from him, could he...)",
  ui_story_5033_50330101_23_dialog_content = "<color=#e8d9bb>Buzz—</color>",
  ui_story_5033_50330101_24_dialog_content = "Sorry, Shadowlord, all that was left was the victim. The witnesses didn't see anyone else.",
  ui_story_5033_50330101_25_dialog_content = "Who was the unlucky sap?",
  ui_story_5033_50330101_26_dialog_content = "The out-of-towner who made his fortune from horse betting. He fell right outside his house. Seemed like he was on his way somewhere. But...",
  ui_story_5033_50330101_27_dialog_content = "Based on my preliminary inspection, I think he can still be saved.",
  ui_story_5033_50330101_28_dialog_content = "We should take this chance.",
  ui_story_5033_50330101_29_dialog_content = "I'll send someone to resuscitate him right now. You stay on the case.",
  ui_story_5033_50330101_30_dialog_content = "Anything on the perpetrator this time?",
  ui_story_5033_50330101_31_dialog_content = "If we connect this crime to past cases, the wounds on the victim are identical to the <color=#FFB400>nun's murder</color> several years ago.",
  ui_story_5033_50330101_32_dialog_content = "A crucial detail was overlooked in all the previous investigations.",
  ui_story_5033_50330101_33_dialog_content = "All the victims suffered a small cut on their bodies before collapsing suddenly for a reason that's yet to be determined.",
  ui_story_5033_50330101_34_dialog_content = "The cuts are always almost too small for the naked eye to see and never seem lethal.",
  ui_story_5033_50330101_35_dialog_content = "But upon closer inspection of our most recent victim, I'm pretty confident it's a knife wound.",
  ui_story_5033_50330101_36_dialog_content = "The culprit is very skilled. The knife enters swiftly and precisely, striking just the right spot.",
  ui_story_5033_50330101_37_dialog_content = "Corax, I put you on the case to bring the perpetrator in alive.",
  ui_story_5033_50330101_38_dialog_content = "You're a doctor. You should know what to do.",
  ui_story_5033_50330101_39_dialog_content = "... Please give me more time, sir.",
  ui_story_5033_50330101_40_dialog_content = "What are your plans?",
  ui_story_5033_50330101_41_dialog_content = "I'll stick to the original plan and keep my eyes out.",
  ui_story_5033_50330101_42_dialog_content = "Act swiftly and with caution.",
  ui_story_5033_50330101_43_dialog_content = "I shall.",
  ui_story_5033_50330101_44_dialog_content = "<color=#e8d9bb>A month later, at the Home Goods Convention in Umbraton</color>",
  ui_story_5033_50330101_45_dialog_content = "<size=45>Extra, extra!</size>",
  ui_story_5033_50330101_46_dialog_content = "Umbraton news fresh out of the oven! Get your delicious press now!",
  ui_story_5033_50330101_47_dialog_content = "(Who describes a newspaper like that?!)",
  ui_story_5033_50330101_48_dialog_content = "Hey!",
  ui_story_5033_50330101_49_dialog_content = "PlayerName! What a rare sight! Are you alone in Umbraton?",
  ui_story_5033_50330101_50_dialog_content = "(Oh no, I got caught!)",
  ui_story_5033_50330101_51_dialog_content = "So, how about picking up a copy? You don't wanna miss this just in!",
  ui_story_5033_50330101_52_dialog_content = "\"Umbraton has been plagued by <color=#FFB400>mystery serial killings</color> in recent weeks\"...",
  ui_story_5033_50330101_53_dialog_content = "\"Several people with ties to the <color=#FFB400>black market</color> have been found dead in their homes\"...",
  ui_story_5033_50330101_54_dialog_content = "\"Victims showed <color=#FFB400>peculiar signs of struggle</color>, and the murderer is still at large\"...",
  ui_story_5033_50330101_55_dialog_content = "How's that? Are you getting the urge to snatch the paper right up now?",
  ui_story_5033_50330101_56_dialog_content = "No, I'm good! I'm not here to buy a paper today.",
  ui_story_5033_50330101_57_dialog_content = "Come on, PlayerName, you're already here. You've gotta buy something!",
  ui_story_5033_50330101_58_dialog_content = "Actually...",
  ui_story_5033_50330101_59_dialog_content = "<color=#e8d9bb>Several days ago in Cloud Gardens</color>",
  ui_story_5033_50330101_60_dialog_content = "(Phew, finally, Cloud Gardens is more presentable now.)",
  ui_story_5033_50330101_61_dialog_content = "(I've been working on the project for so long, I deserve a break.)",
  ui_story_5033_50330101_62_dialog_content = "But this is not good enough yet.",
  ui_story_5033_50330101_63_dialog_content = "What?! How did you know what I was—",
  ui_story_5033_50330101_64_dialog_content = "Your face told me you were about to give up, PlayerName.",
  ui_story_5033_50330101_65_dialog_content = "We got the basic furnishings in place, but it's still too empty and plain.",
  ui_story_5033_50330101_66_dialog_content = "Here!",
  ui_story_5033_50330101_67_dialog_content = "Whoa, what's this stack?",
  ui_story_5033_50330101_68_dialog_content = "Exhibitor catalogs for the annual Umbraton Home Goods Convention!",
  ui_story_5033_50330101_69_dialog_content = "You don't want to know how many connections I had to go through to collect them all!",
  ui_story_5033_50330101_70_dialog_content = "... You've been planning this forever, haven't you.",
  ui_story_5033_50330101_71_dialog_content = "Let's not dwell on the small details!",
  ui_story_5033_50330101_72_dialog_content = "Anyway, renovation is no trivial matter. This is your home, after all.",
  ui_story_5033_50330101_73_dialog_content = "Now imagine finally getting to go home and relax after a long trip. What do you see?",
  ui_story_5033_50330101_74_dialog_content = "Oh, I'd want to curl up on a recliner.",
  ui_story_5033_50330101_75_dialog_content = "How does the recliner feel to you, is it made of soft satin or cool leather?",
  ui_story_5033_50330101_76_dialog_content = "Leather for a recliner, of course! And it'd look cooler.",
  ui_story_5033_50330101_77_dialog_content = "See? Furnishings and decor don't just help with contentment, but are also a good way to show off your style!",
  ui_story_5033_50330101_78_dialog_content = "All things that go into your home should be chosen carefully.",
  ui_story_5033_50330101_79_dialog_content = "W-W-Wait a minute!",
  ui_story_5033_50330101_80_dialog_content = "You're not trying to get me to read all these brochures, are you?",
  ui_story_5033_50330101_81_dialog_content = "It's not like you've got anything to do in the next few days!",
  ui_story_5033_50330101_82_dialog_content = "And you have to handle every step of the renovation personally, anyway.",
  ui_story_5033_50330101_83_dialog_content = "Alrighty now, there's no time for chitchat.",
  ui_story_5033_50330101_84_dialog_content = "We've gotta get ready. Shopping is war, you know!",
  ui_story_5033_50330101_85_dialog_content = "Remember the material, finish, and style for every item.",
  ui_story_5033_50330101_86_dialog_content = "Peruse and evaluate everything thoroughly before making the final list, so you'll be armed for the convention!",
  ui_story_5033_50330101_87_dialog_content = "Yes, Officer Vice!",
  ui_story_5033_50330101_88_dialog_content = "Just like that, we browsed the brochures for four whole days with very little sleep.",
  ui_story_5033_50330101_89_dialog_content = "Wow, impressive!",
  ui_story_5033_50330101_90_dialog_content = "Yeah. Vice was so laser-focused that she could burn right through them with her eyes.",
  ui_story_5033_50330101_91_dialog_content = "I thought all I had to do was follow Vice around the convention.",
  ui_story_5033_50330101_92_dialog_content = "However...",
  ui_story_5033_50330101_93_dialog_content = "<color=#e8d9bb>Just before departure</color>",
  ui_story_5033_50330101_94_dialog_content = "Oh gosh, I'm so sorry, PlayerName!!!",
  ui_story_5033_50330101_95_dialog_content = "I just got an urgent task from Commander Hiiro...",
  ui_story_5033_50330101_96_dialog_content = "So, I ended up coming by myself without any clue or budget in mind.",
  ui_story_5033_50330101_97_dialog_content = "What a pity though, PlayerName. The convention was <color=#FFB400>canceled</color> last minute.",
  ui_story_5033_50330101_98_dialog_content = "What?!",
  ui_story_5033_50330101_99_dialog_content = "It's due to the serial killings that got everyone all jumpy.",
  ui_story_5033_50330101_100_dialog_content = "Because of safety concerns, Umbraton called off all large gatherings for the time being.",
  ui_story_5033_50330101_101_dialog_content = "R-Really?!",
  ui_story_5033_50330101_102_dialog_content = "What rotten luck...",
  ui_story_5033_50330101_103_dialog_content = "Don't be all depressed. Umbraton has loads of things for sale.",
  ui_story_5033_50330101_104_dialog_content = "Look around and you just might find something cool!",
  ui_story_5033_50330101_105_dialog_content = "Well, gotta run now!",
  ui_story_5033_50330101_106_dialog_content = "Thanks, Wendy!",
  ui_story_5033_50330101_107_dialog_content = "Where should I go, then?",
  ui_story_5033_50330101_108_dialog_content = "Hmm? Is this a stall specializing in... postcards?",
  ui_story_5033_50330101_109_dialog_content = "This color is very pretty.",
  ui_story_5033_50330101_110_dialog_content = "Postcards can be home decor too, you know.",
  ui_story_5033_50330101_111_dialog_content = "Feel free to look through them. They highlight different towns and locations around Umbraton.",
  ui_story_5033_50330101_112_dialog_content = "(Well, I do at least have enough to buy a postcard...)",
  ui_story_5033_50330101_113_dialog_content = "I guess I'll take the one I'm holding then.",
  ui_story_5033_50330101_114_dialog_content = "Thank you, and please come again!",
  ui_story_5033_50330101_115_dialog_content = "(The town on this postcard is called... <color=#FFB400>Euphoria</color>?)",
  ui_story_5033_50330101_116_dialog_content = "(And the writing on the back—\"Welcome to <color=#FFB400>Wonderland</color>\"...)",
  ui_story_5033_50330101_117_dialog_content = "(Never been there. It'd be nice to check it out sometime.)",
  ui_story_5033_50330101_118_dialog_content = "(Moderate retail therapy does improve one's mood after all.)",
  ui_story_5033_50330101_119_dialog_content = "<color=#e8d9bb>Whoosh!</color>",
  ui_story_5033_50330101_120_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5033_50330101_121_dialog_content = "My postcard!!!",
  ui_story_5033_50330101_122_dialog_content = "Geez... Where did it go?",
  ui_story_5033_50330101_123_dialog_content = "Stop right there, you two!",
  ui_story_5033_50330101_124_dialog_content = "*Panting*",
  ui_story_5033_50330101_125_dialog_content = "...",
  ui_story_5033_50330101_126_dialog_content = "(What a weird-looking man. Is this kind of look the latest fad in Umbraton?)",
  ui_story_5033_50330101_127_dialog_content = "(Hold it, why does he look familiar?)",
  ui_story_5033_50330101_128_dialog_content = "I have no idea why you stopped us...",
  ui_story_5033_50330101_129_dialog_content = "But thanks nevertheless, PlayerName.",
  ui_story_5033_50330101_130_dialog_content = "Well, since the man's caught...",
  ui_story_5033_50330101_131_dialog_content = "I can take it from here.",
  ui_story_5033_50330101_132_dialog_content = "Corax?! Why are you dressed up like this?",
  ui_story_5033_50330101_133_dialog_content = "Please, sir, I'm begging you, I don't have anything to do with it!",
  ui_story_5033_50330101_134_dialog_content = "Unless you give me something worthwhile...",
  ui_story_5033_50330101_135_dialog_content = "I'll take you straight to the Shadowlord.",
  ui_story_5033_50330101_136_dialog_content = "But I-I don't know anything!",
  ui_story_5033_50330101_137_dialog_content = "Is that so?",
  ui_story_5033_50330101_138_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5033_50330101_139_dialog_content = "No, don't! Okay, I'll talk, just put that away!",
  ui_story_5033_50330101_140_dialog_content = "I did business with them sure, but I didn't kill anyone!",
  ui_story_5033_50330101_141_dialog_content = "They all got their start doing shady business and used their money to exploit the criminal underbelly of Umbraton!",
  ui_story_5033_50330101_142_dialog_content = "That's all old news. Anything else?",
  ui_story_5033_50330101_143_dialog_content = "A-And...",
  ui_story_5033_50330101_144_dialog_content = "Before they died, they all visited <color=#FFB400>Euphoria</color>!",
  ui_story_5033_50330101_145_dialog_content = "Supposedly, the <color=#FFB400>Grim Reaper</color> shows up there!",
  ui_story_5033_50330101_146_dialog_content = "Grim Reaper?",
  ui_story_5033_50330101_147_dialog_content = "T-That's right... Anyone who doesn't obey the Grim Reaper...",
  ui_story_5033_50330101_148_dialog_content = "It snatches their life a few days later!",
  ui_story_5033_50330101_149_dialog_content = "They must've died because of the Grim Reaper, who shall not be spoken of!",
  ui_story_5033_50330101_150_dialog_content = "But isn't Euphoria already...",
  ui_story_5033_50330101_151_dialog_content = "You'd better be telling the truth.",
  ui_story_5033_50330101_152_dialog_content = "I am, I swear!",
  ui_story_5033_50330101_153_dialog_content = "...",
  ui_story_5033_50330101_154_option_content = "Force Boost!",
  ui_story_5033_50330101_155_dialog_content = "Uh, he's telling the truth, Corax.",
  ui_story_5033_50330101_156_dialog_content = "I don't sense anything other than stress and fear.",
  ui_story_5033_50330101_157_dialog_content = "Thanks for the big help, PlayerName.",
  ui_story_5033_50330101_158_dialog_content = "W-What are you doing now?!",
  ui_story_5033_50330101_159_dialog_content = "I'd like you to go to Euphoria with me.",
  ui_story_5033_50330101_160_dialog_content = "Right now?!",
  ui_story_5033_50330101_161_dialog_content = "I'm under the Shadowlord's order to go there and investigate the serial killings in Umbraton.",
  ui_story_5033_50330101_162_dialog_content = "I'll explain the rest on the way.",
  ui_story_5033_50330101_163_dialog_content = "To avoid your Colossus drawing unnecessary attention, we'll be taking an airship.",
  ui_story_5033_50330101_164_dialog_content = "I'll see you at the Shuttle Hub tomorrow morning.",
  ui_story_5033_50330101_165_dialog_content = "I mean sure, I did want to check out Euphoria, but...",
  ui_story_5033_50330101_166_dialog_content = "Well then, see you tomorrow.",
  ui_story_5033_50330101_167_dialog_content = "Wait, let me finish!",
  ui_story_5033_50330101_168_dialog_content = "You could at least let me think about it...",
  ui_story_5033_50330201_1_dialog_content = "<color=#e8d9bb>Shuttle Hub</color>",
  ui_story_5033_50330201_2_dialog_content = "(Well, here I am. I even got here earlier than promised...)",
  ui_story_5033_50330201_3_dialog_content = "(I rarely come here since I travel around on Soroz.)",
  ui_story_5033_50330201_4_dialog_content = "(I wish I could send a postcard back to Eraveil... If only I hadn't lost the one I had yesterday.)",
  ui_story_5033_50330201_5_dialog_content = "My postcard... Ugh...",
  ui_story_5033_50330201_6_dialog_content = "Pardon me for overhearing your lament.",
  ui_story_5033_50330201_7_dialog_content = "If it's a postcard you're upset about,",
  ui_story_5033_50330201_8_dialog_content = "I happen to have one on me. Here, take it.",
  ui_story_5033_50330201_9_dialog_content = "Whoa, no way! It's the same picture, even!",
  ui_story_5033_50330201_10_dialog_content = "I can't take this. I don't even know you...",
  ui_story_5033_50330201_11_dialog_content = "It suits you more. Take it, and I can call it my good deed for the day.",
  ui_story_5033_50330201_12_dialog_content = "Really, keep it. I don't need it anymore.",
  ui_story_5033_50330201_13_dialog_content = "You don't?",
  ui_story_5033_50330201_14_dialog_content = "Yes, because I'm going back.",
  ui_story_5033_50330201_15_dialog_content = "It's been fourteen years since I was in Euphoria last.",
  ui_story_5033_50330201_16_dialog_content = "Sorry for rambling.",
  ui_story_5033_50330201_17_dialog_content = "It's cool, I'm still waiting for someone to show up. So, what should I call you?",
  ui_story_5033_50330201_18_dialog_content = "...",
  ui_story_5033_50330201_19_dialog_content = "Anne is fine.",
  ui_story_5033_50330201_20_dialog_content = "I'm PlayerName. This would be my first time in Euphoria.",
  ui_story_5033_50330201_21_dialog_content = "You sound like you know it well. Mind telling me a little about it?",
  ui_story_5033_50330201_22_dialog_content = "I noticed the postcard dubbed it \"<color=#FFB400>Wonderland</color>.\"",
  ui_story_5033_50330201_23_dialog_content = "That's correct. To outsiders back then, it could certainly be considered a sort of wonderland.",
  ui_story_5033_50330201_24_dialog_content = "They came in pursuit of happiness they couldn't find anywhere else.",
  ui_story_5033_50330201_25_dialog_content = "However, what was most alluring wasn't the cozy atmosphere or landscape",
  ui_story_5033_50330201_26_dialog_content = "but rather, the thriving <color=#FFB400>black market</color> within the shadows of its unique buildings.",
  ui_story_5033_50330201_27_dialog_content = "Black market?!",
  ui_story_5033_50330201_28_dialog_content = "Doesn't Umbraton have one too? Why go to Euphoria?",
  ui_story_5033_50330201_29_dialog_content = "It did start off pretty similar to Umbraton, but Euphoria was legally private property.",
  ui_story_5033_50330201_30_dialog_content = "As you can probably guess, crossing the boundaries for personal gain and desire was common there.",
  ui_story_5033_50330201_31_dialog_content = "Large casinos, private arms manufacturers... Anything you could imagine was there.",
  ui_story_5033_50330201_32_dialog_content = "That sounds even more liberal than Umbraton.",
  ui_story_5033_50330201_33_dialog_content = "Thanks for the primer. I'm looking forward to the visit.",
  ui_story_5033_50330201_34_dialog_content = "But I'm afraid you'll only be disappointed if you go to Euphoria with any preconceived notions.",
  ui_story_5033_50330201_35_dialog_content = "What do you mean?",
  ui_story_5033_50330201_36_dialog_content = "Sometime after I left, Euphoria suddenly vanished.",
  ui_story_5033_50330201_37_dialog_content = "I've never even heard anyone mention the name since then.",
  ui_story_5033_50330201_38_dialog_content = "As if the town was purposely forgotten.",
  ui_story_5033_50330201_39_dialog_content = "A forgotten town, huh...",
  ui_story_5033_50330201_40_dialog_content = "PlayerName!",
  ui_story_5033_50330201_41_dialog_content = "Sorry for the wait.",
  ui_story_5033_50330201_42_dialog_content = "It's okay. I've been talking to this nun here who's also going to Euphoria.",
  ui_story_5033_50330201_43_dialog_content = "Anne, this is Corax. He's traveling with me.",
  ui_story_5033_50330201_44_dialog_content = "The airship is about to take off. We should board now.",
  ui_story_5033_50330201_45_dialog_content = "It's rare to find a flight to Euphoria, so let's not miss it.",
  ui_story_5033_50330201_46_dialog_content = "O-Okay...",
  ui_story_5033_50330201_47_dialog_content = "<color=#e8d9bb>On the airship</color>",
  ui_story_5033_50330201_48_dialog_content = "Anyway, I officially took the case from the Shadowlord a month ago.",
  ui_story_5033_50330201_49_dialog_content = "Umbraton has seen violent crimes lately targeting several venues for underground trade, as well as those involved in the trade.",
  ui_story_5033_50330201_50_dialog_content = "The events are hurting the economy.",
  ui_story_5033_50330201_51_dialog_content = "It has to be a covert investigation for a number of reasons.",
  ui_story_5033_50330201_52_dialog_content = "From the testimony of that man yesterday, I just have to go there.",
  ui_story_5033_50330201_53_dialog_content = "So you're saying every lead is pointing to Euphoria?",
  ui_story_5033_50330201_54_dialog_content = "Oh, speaking of the <color=#FFB400>murder of the nun</color> that started it all, we have someone before us who might be able to help.",
  ui_story_5033_50330201_55_dialog_content = "...",
  ui_story_5033_50330201_56_dialog_content = "No problem, I can cooperate.",
  ui_story_5033_50330201_57_dialog_content = "Relax, I just want to ask a few simple questions.",
  ui_story_5033_50330201_58_dialog_content = "Are you familiar with a nun named <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330201_59_dialog_content = "I do know of her, yes.",
  ui_story_5033_50330201_60_dialog_content = "But all I know is she was transferred from Euphoria to Umbraton. Did she...?",
  ui_story_5033_50330201_61_dialog_content = "She was one of the first victims.",
  ui_story_5033_50330201_62_dialog_content = "... May she rest in peace.",
  ui_story_5033_50330201_63_dialog_content = "Perhaps that's the fate of us nuns.",
  ui_story_5033_50330201_64_dialog_content = "Couldn't escape it even by leaving Euphoria, I suppose.",
  ui_story_5033_50330201_65_dialog_content = "Not trying to be rude, but you don't seem particularly surprised.",
  ui_story_5033_50330201_66_dialog_content = "Nuns have no place in Euphoria anymore.",
  ui_story_5033_50330201_67_dialog_content = "If you're caught alone on the streets and don't have enough money,",
  ui_story_5033_50330201_68_dialog_content = "even how you die is up to fate to decide.",
  ui_story_5033_50330201_69_dialog_content = "Sounds like a \"peaceful\" place...",
  ui_story_5033_50330201_70_dialog_content = "Yet you're riding an airship to Euphoria like us.",
  ui_story_5033_50330201_71_dialog_content = "I sought to get away from it all by leaving.",
  ui_story_5033_50330201_72_dialog_content = "But there's something calling me back now.",
  ui_story_5033_50330201_73_dialog_content = "... You know what, I've got nothing to hide. I'm going back to <color=#FFB400>see a friend</color>.",
  ui_story_5033_50330201_74_dialog_content = "I guess we won't be going the same way.",
  ui_story_5033_50330201_75_dialog_content = "I think we're almost there, judging from the landscape below.",
  ui_story_5033_50330201_76_dialog_content = "<color=#e8d9bb>A street in Euphoria</color>",
  ui_story_5033_50330201_77_dialog_content = "I guess this is where we say goodbye.",
  ui_story_5033_50330201_78_dialog_content = "Good luck with your case.",
  ui_story_5033_50330201_79_dialog_content = "Thank you. You take care, too.",
  ui_story_5033_50330201_80_dialog_content = "(She left in a hurry. She didn't seem all that concerned about her safety, either...)",
  ui_story_5033_50330201_81_dialog_content = "<color=#e8d9bb>Caw, caw—</color>",
  ui_story_5033_50330201_82_dialog_content = "It's desolate here, just like Anne said.",
  ui_story_5033_50330201_83_dialog_content = "The buildings are either in disrepair or vandalized, and there's not a person in sight...",
  ui_story_5033_50330201_84_dialog_content = "I guess this so-called Wonderland's nothing but an abandoned village after all.",
  ui_story_5033_50330201_85_dialog_content = "So you've heard of Euphoria's nickname too, huh?",
  ui_story_5033_50330201_86_dialog_content = "Don't be disappointed. I got some useful info from Taki before I left.",
  ui_story_5033_50330201_87_dialog_content = "Well then, let's get this show on the road...",
  ui_story_5033_50330201_88_dialog_content = "Hmm?",
  ui_story_5033_50330201_89_dialog_content = "What's the matter?",
  ui_story_5033_50330201_90_dialog_content = "I sense something weird in the air...",
  ui_story_5033_50330201_91_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330201_92_dialog_content = "<size=45>Grah!!!</size>",
  ui_story_5033_50330201_93_dialog_content = "Just like the report said, the area's perpetual overcast skies and dense fog make for a natural playground for the Eclipsites...",
  ui_story_5033_50330201_94_dialog_content = "Whatever type of Eclipsites they are, we'll just have to fight them!",
  ui_story_5033_50330201_95_dialog_content = "Ice blade!",
  ui_story_5033_50330202_1_dialog_content = "<size=45>Ice blade!!</size>",
  ui_story_5033_50330202_2_dialog_content = "Get away from there, PlayerName!",
  ui_story_5033_50330202_3_dialog_content = "<size=45>Graaah!</size>",
  ui_story_5033_50330202_4_dialog_content = "(I've been through this same exact scenario a million times by now!)",
  ui_story_5033_50330202_5_dialog_content = "(There's a giant Eclipsite claw above my head.)",
  ui_story_5033_50330202_6_dialog_content = "(If I don't duck, my head will be split open in a second.)",
  ui_story_5033_50330202_7_dialog_content = "Stay away!!",
  ui_story_5033_50330202_8_dialog_content = "<color=#e8d9bb>Swish!</color>",
  ui_story_5033_50330202_9_dialog_content = "...",
  ui_story_5033_50330202_10_dialog_content = "Is that an axe? Are they really fighting Eclipsites with axes?",
  ui_story_5033_50330202_11_dialog_content = "<color=#e8d9bb>*Axe chopping*</color>",
  ui_story_5033_50330202_12_dialog_content = "<color=#e8d9bb>*Axe swinging and chopping*</color>",
  ui_story_5033_50330202_13_dialog_content = "They look like haphazard swings, yet they struck the vitals all the same.",
  ui_story_5033_50330202_14_dialog_content = "Obviously, these guys know how to deal with Eclipsites.",
  ui_story_5033_50330202_15_dialog_content = "Are you all right, PlayerName? You don't look hurt.",
  ui_story_5033_50330202_16_dialog_content = "I'm okay, just a bit scared out of my wits.",
  ui_story_5033_50330202_17_dialog_content = "Are they local Euphorians?",
  ui_story_5033_50330202_18_dialog_content = "Be careful how you skin them. The chest hide has to be in one piece.",
  ui_story_5033_50330202_19_dialog_content = "Pull the fingernails, hack off the horns. Oh, and the eyes too...",
  ui_story_5033_50330202_20_dialog_content = "Ouch!",
  ui_story_5033_50330202_21_dialog_content = "I told you to be careful, you bastard! Give me that knife!",
  ui_story_5033_50330202_22_dialog_content = "The eye is ruined. Put it in the junk pile and burn it.",
  ui_story_5033_50330202_23_dialog_content = "Are they dissecting the Eclipsite? What do they want with all that?",
  ui_story_5033_50330202_24_dialog_content = "...",
  ui_story_5033_50330202_25_dialog_content = "Time to go, PlayerName.",
  ui_story_5033_50330202_26_dialog_content = "Now? But they saved me, shouldn't I thank them?",
  ui_story_5033_50330202_27_dialog_content = "Listen carefully.",
  ui_story_5033_50330202_28_dialog_content = "Look closely at what they're doing.",
  ui_story_5033_50330202_29_dialog_content = "They weren't trying to save you. Their focus wasn't on you to begin with.",
  ui_story_5033_50330202_30_dialog_content = "The Eclipsite hide and organs, that's what they're after. Probably to sell at dirt cheap prices—one for 200, two for 300.",
  ui_story_5033_50330202_31_dialog_content = "They've probably been following the Eclipsites for a while now. We were just collateral passerby.",
  ui_story_5033_50330202_32_dialog_content = "Euphoria, forgotten town as it is, clearly runs on an entirely different set of rules.",
  ui_story_5033_50330202_33_dialog_content = "<size=33>If we don't go now, this place is going to suck us in and swallow us whole.</size>",
  ui_story_5033_50330202_34_dialog_content = "Okay. Then let's—",
  ui_story_5033_50330202_35_dialog_content = "Hold up, you outsiders.",
  ui_story_5033_50330202_36_dialog_content = "You can't just come and go as you like here.",
  ui_story_5033_50330202_37_dialog_content = "<size=45>We don't recall giving you permission to leave!</size>",
  ui_story_5033_50330202_38_dialog_content = "<color=#e8d9bb>Clank!</color>",
  ui_story_5033_50330202_39_dialog_content = "Don't tell me you don't know the rules of Euphoria.",
  ui_story_5033_50330202_40_dialog_content = "He just split a hole in the ground...",
  ui_story_5033_50330202_41_dialog_content = "<size=33>I guess it's too late now.</size>",
  ui_story_5033_50330202_42_dialog_content = "Word is that Euphoria's a hospitable place that makes everyone feel welcome.",
  ui_story_5033_50330202_43_dialog_content = "Of course, this hospitality should be reciprocated.",
  ui_story_5033_50330202_44_dialog_content = "Here you go. Do your counting.",
  ui_story_5033_50330202_45_dialog_content = "You, come here.",
  ui_story_5033_50330202_46_dialog_content = "Who, me?",
  ui_story_5033_50330202_47_dialog_content = "Who else? <size=33>Count this back there.</size>",
  ui_story_5033_50330202_48_dialog_content = "As for you... Speak, where did you come from?",
  ui_story_5033_50330202_49_dialog_content = "We are...",
  ui_story_5033_50330202_50_dialog_content = "(Why did Corax just glance at me? Now is probably not the time to be truthful.)",
  ui_story_5033_50330202_51_dialog_content = "(But this is a township of Umbraton, so we might be able to get them to back off if they learn we're from there.)",
  ui_story_5033_50330202_52_dialog_content = "We're from Eraveil, north of Lumopolis. It's a small town isolated from the rest of the world.",
  ui_story_5033_50330202_53_dialog_content = "Huh?",
  ui_story_5033_50330202_54_dialog_content = "Eraveil...",
  ui_story_5033_50330202_55_dialog_content = "Who the hell are you tryin' to fool?",
  ui_story_5033_50330202_56_dialog_content = "It's true.",
  ui_story_5033_50330202_57_dialog_content = "(He sure is selling it with a straight face.)",
  ui_story_5033_50330202_58_dialog_content = "(He's probably also trying to imply that they're super uncultured...)",
  ui_story_5033_50330202_59_dialog_content = "Uh, boss, I think Eraveil is a real place.",
  ui_story_5033_50330202_60_dialog_content = "Fine. Next question: what do you do, and why are you here?",
  ui_story_5033_50330202_61_dialog_content = "We're here for business, selling junk, you know how it goes. Just trying to scrape by.",
  ui_story_5033_50330202_62_dialog_content = "Then why don't you have anything on you?",
  ui_story_5033_50330202_63_dialog_content = "We're just scoping the place out. And we did bring offerings, didn't we?",
  ui_story_5033_50330202_64_dialog_content = "As for who we are, he's my driver. And me, I'm—",
  ui_story_5033_50330202_65_dialog_content = "<size=45>I'm done counting!</size>",
  ui_story_5033_50330202_66_dialog_content = "I got 1,235 total! <size=33>That's a lot of money, boss. These two are rich.</size>",
  ui_story_5033_50330202_67_dialog_content = "All right.",
  ui_story_5033_50330202_68_dialog_content = "Seeing as we've given our offering, I think we can call off this little welcome ceremony.",
  ui_story_5033_50330202_69_dialog_content = "We'll be on our way now. There's no need to accompany us.",
  ui_story_5033_50330202_70_dialog_content = "You did cough up the money, but not enough.",
  ui_story_5033_50330202_71_dialog_content = "What do you mean?",
  ui_story_5033_50330202_72_dialog_content = "The price just went up.",
  ui_story_5033_50330202_73_dialog_content = "How much?",
  ui_story_5033_50330202_74_dialog_content = "20,000.",
  ui_story_5033_50330202_75_dialog_content = "And that will do?",
  ui_story_5033_50330202_76_dialog_content = "Let's see it first.",
  ui_story_5033_50330202_77_dialog_content = "They're robbing us, Corax! They won't let us go even if we give them all our money.",
  ui_story_5033_50330202_78_dialog_content = "Relax.",
  ui_story_5033_50330202_79_dialog_content = "I got 20,000 on me. You can even ask for more, but you'll have to come to get it yourself.",
  ui_story_5033_50330202_80_dialog_content = "There are only two of us and a dozen of you. No reason for you to be afraid.",
  ui_story_5033_50330202_81_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5033_50330202_82_dialog_content = "<size=45>Oof!</size>",
  ui_story_5033_50330202_83_dialog_content = "Boss!!!!",
  ui_story_5033_50330202_84_dialog_content = "Do you have a friggin' death wish?!",
  ui_story_5033_50330202_85_dialog_content = "(But his arm was broken!)",
  ui_story_5033_50330202_86_dialog_content = "(It was dangling like a wet noodle.)",
  ui_story_5033_50330202_87_dialog_content = "(Yet it regenerated in a second.)",
  ui_story_5033_50330202_88_dialog_content = "Stop screaming so loud. Your arm is fine.",
  ui_story_5033_50330202_89_dialog_content = "See for yourself.",
  ui_story_5033_50330202_90_dialog_content = "But it was broken, and I felt it!",
  ui_story_5033_50330202_91_dialog_content = "Y-y-you—",
  ui_story_5033_50330202_92_dialog_content = "Keep the money. It's exactly 20,000. Didn't you want to know what I do for a living?",
  ui_story_5033_50330202_93_dialog_content = "I'm a doctor.",
  ui_story_5033_50330202_94_dialog_content = "I can heal you, and I can shatter every bone in your body as well.",
  ui_story_5033_50330202_95_dialog_content = "Not just you, but everyone behind you too.",
  ui_story_5033_50330202_96_dialog_content = "...",
  ui_story_5033_50330202_97_dialog_content = "So, are we free to leave now?",
  ui_story_5033_50330202_98_dialog_content = "Y-You just wait! You'll regret this!",
  ui_story_5033_50330301_1_dialog_content = "(We finally got rid of them...)",
  ui_story_5033_50330301_2_dialog_content = "Why did you waste so much time with them, Corax?",
  ui_story_5033_50330301_3_dialog_content = "You could've just dropped Istvan's name.",
  ui_story_5033_50330301_4_dialog_content = "They might look mean, but they're just a crew of street ruffians.",
  ui_story_5033_50330301_5_dialog_content = "No way they'd defy the Shadowlord of Umbraton.",
  ui_story_5033_50330301_6_dialog_content = "That would've been the easy way out, but there'd have been repercussions.",
  ui_story_5033_50330301_7_dialog_content = "Umbraton is powerful, but the Shadowlord prefers keeping things low-key.",
  ui_story_5033_50330301_8_dialog_content = "Bringing him up would've been seen as a provocation.",
  ui_story_5033_50330301_9_dialog_content = "Is that why you were signalling me earlier?",
  ui_story_5033_50330301_10_dialog_content = "Yeah. But it's for our own safety as well as the Shadowlord's privacy.",
  ui_story_5033_50330301_11_dialog_content = "... Is it really that serious?",
  ui_story_5033_50330301_12_dialog_content = "Many Euphorians hate Umbraton. \"Many\" is an understatement, really.",
  ui_story_5033_50330301_13_dialog_content = "The two haven't conducted any proper business with each other for years.",
  ui_story_5033_50330301_14_dialog_content = "<color=#FFB400>Twelve years ago</color>, the Darkover swept through Umbraton and all surrounding regions.",
  ui_story_5033_50330301_15_dialog_content = "Towns of every size fell, forcing Umbraton to undergo a restructuring.",
  ui_story_5033_50330301_16_dialog_content = "There was chaos everywhere, and Euphoria was one of the towns hit the hardest.",
  ui_story_5033_50330301_17_dialog_content = "The Eclipsites that Umbraton beat all swarmed their way into Euphoria.",
  ui_story_5033_50330301_18_dialog_content = "But the Shadowlord didn't have any forces back then, so he couldn't help anyone.",
  ui_story_5033_50330301_19_dialog_content = "After the war died down, the \"Umbraton used Darkover to ruin Euphoria\" conspiracy theory began circulating around.",
  ui_story_5033_50330301_20_dialog_content = "But I thought Anne said that Euphoria was privately owned?",
  ui_story_5033_50330301_21_dialog_content = "Did the owner just abandon it?",
  ui_story_5033_50330301_22_dialog_content = "That was true, but it became no-man's land after the Eclipsite invasion.",
  ui_story_5033_50330301_23_dialog_content = "The survivors banded together and formed many <color=#FFB400>small co-ops</color>.",
  ui_story_5033_50330301_24_dialog_content = "Some of the supply facilities were able to be recovered after basic repairs.",
  ui_story_5033_50330301_25_dialog_content = "Once the surrounding population starting growing, certain venues returned to operation.",
  ui_story_5033_50330301_26_dialog_content = "The co-ops also gradually devolved into <color=#FFB400>gangs</color>.",
  ui_story_5033_50330301_27_dialog_content = "Euphoria sure went through drastic changes...",
  ui_story_5033_50330301_28_dialog_content = "So this landscape before us is a result of a town stuck in stasis in the aftermath of a war.",
  ui_story_5033_50330301_29_dialog_content = "The streets might be empty now, but there are definitely eyes in the shadows watching us.",
  ui_story_5033_50330301_30_dialog_content = "All right, we need to move and try to be inconspicuous.",
  ui_story_5033_50330301_31_dialog_content = "Before I left, Taki gave me two choices and contacted his contacts for both.",
  ui_story_5033_50330301_32_dialog_content = "Option A is to pay <color=#FFB400>Gustav</color> a visit at Euphoria's Odd Jobs.",
  ui_story_5033_50330301_33_dialog_content = "Option B is to find <color=#FFB400>Nekoyashiki</color>, a roaming Odd Jobs.",
  ui_story_5033_50330301_34_dialog_content = "That sounds like a choice between something \"official\" and something \"informal.\"",
  ui_story_5033_50330301_35_dialog_content = "What do you think, PlayerName?",
  ui_story_5033_50330301_36_option_content = "Gustav of Odd Jobs in Euphoria.",
  ui_story_5033_50330301_37_dialog_content = "A reputable local Odd Jobs, like Taki, would have more reliable info.",
  ui_story_5033_50330301_38_dialog_content = "Also, an official Odd Jobs would have more connections, thus more leads.",
  ui_story_5033_50330301_39_dialog_content = "That makes sense, but...",
  ui_story_5033_50330301_40_dialog_content = "We'll be exposed once we go there.",
  ui_story_5033_50330301_41_dialog_content = "All other gangs with connections there will catch wind of us.",
  ui_story_5033_50330301_42_dialog_content = "That does sound rather dangerous...",
  ui_story_5033_50330301_43_option_content = "Nekoyashiki, the roaming Odd Jobs.",
  ui_story_5033_50330301_44_dialog_content = "He sounds enigmatic, and no one will notice if we try to find him.",
  ui_story_5033_50330301_45_dialog_content = "And a roaming Odd Jobs might have privy info.",
  ui_story_5033_50330301_46_dialog_content = "You're right.",
  ui_story_5033_50330301_47_dialog_content = "Contacts like that are actually safer.",
  ui_story_5033_50330301_48_dialog_content = "Let's go find this Nekoyashiki, then.",
  ui_story_5033_50330301_49_dialog_content = "Is he reliable though?",
  ui_story_5033_50330301_50_dialog_content = "It's not an issue of reliability, but trustworthiness, with Odd Jobs.",
  ui_story_5033_50330301_51_dialog_content = "Because only we can determine what's trustworthy?",
  ui_story_5033_50330301_52_dialog_content = "Very smart.",
  ui_story_5033_50330301_53_dialog_content = "To Gustav, Nekoyashiki is just small fry.",
  ui_story_5033_50330301_54_dialog_content = "If you end up going with him, it'll be hard to track him down.",
  ui_story_5033_50330301_55_dialog_content = "His whereabouts are unpredictable, but he does leave symbols, usually somewhere in a building he's in...",
  ui_story_5033_50330301_56_dialog_content = "That's what Taki told me. As for the symbol...",
  ui_story_5033_50330301_57_dialog_content = "Does it happen to be a <color=#FFB400>scar-shaped graffiti</color>?",
  ui_story_5033_50330301_58_dialog_content = "How do you know, PlayerName?",
  ui_story_5033_50330301_59_dialog_content = "I just saw one. See, it's on the sign of that restaurant.",
  ui_story_5033_50330301_60_dialog_content = "As if it's beckoning for us to come.",
  ui_story_5033_50330301_61_dialog_content = "I knew nothing slipped by these intel peddlers.",
  ui_story_5033_50330301_62_dialog_content = "<color=#e8d9bb>Creak...</color>",
  ui_story_5033_50330301_63_dialog_content = "Anybody in?",
  ui_story_5033_50330301_64_dialog_content = "It's so quiet in here. Is this restaurant abandoned?",
  ui_story_5033_50330301_65_dialog_content = "... Oh no!",
  ui_story_5033_50330301_66_dialog_content = "Get down, Corax!",
  ui_story_5033_50330301_67_dialog_content = "<color=#e8d9bb>Whoosh... Bang!</color>",
  ui_story_5033_50330301_68_dialog_content = "Damn, missed 'em.",
  ui_story_5033_50330301_69_dialog_content = "Out of the way. My turn!",
  ui_story_5033_50330301_70_dialog_content = "<color=#e8d9bb>Whoosh... Bang!</color>",
  ui_story_5033_50330301_71_dialog_content = "You again?! We come in peace!",
  ui_story_5033_50330301_72_dialog_content = "We were slow on the draw last time.",
  ui_story_5033_50330301_73_dialog_content = "You pissed off the wrong people when you broke the boss's arm.",
  ui_story_5033_50330301_74_dialog_content = "<size=33>Are we not at the right place?</size>",
  ui_story_5033_50330301_75_dialog_content = "<size=33>No way, Taki's information is never wrong.</size>",
  ui_story_5033_50330301_76_dialog_content = "<size=33>There's probably more to this situation than we think.</size>",
  ui_story_5033_50330301_77_dialog_content = "Never mind. Come on, we need to defend ourselves.",
  ui_story_5033_50330301_78_dialog_content = "Huh?",
  ui_story_5033_50330301_79_dialog_content = "<color=#e8d9bb>Clang!</color>",
  ui_story_5033_50330301_80_dialog_content = "You dare fight back?",
  ui_story_5033_50330301_81_dialog_content = "Graah...",
  ui_story_5033_50330301_82_dialog_content = "Eclipsites, on top of the gang? What a mess.",
  ui_story_5033_50330301_83_dialog_content = "We should get rid of the Eclipsites first!",
  ui_story_5033_50330302_1_dialog_content = "Graah...",
  ui_story_5033_50330302_2_dialog_content = "There's too many of them. We've gotta make a break for it, PlayerName!",
  ui_story_5033_50330302_3_dialog_content = "To where?!",
  ui_story_5033_50330302_4_dialog_content = "Let's just get out of here first!",
  ui_story_5033_50330302_5_dialog_content = "They're getting away, boss!",
  ui_story_5033_50330302_6_dialog_content = "Get them!",
  ui_story_5033_50330302_7_dialog_content = "<color=#e8d9bb>An alley in Euphoria</color>",
  ui_story_5033_50330302_8_dialog_content = "Huff, puff...",
  ui_story_5033_50330302_9_dialog_content = "(I have no idea where I am right now...)",
  ui_story_5033_50330302_10_dialog_content = "Grah!!!",
  ui_story_5033_50330302_11_dialog_content = "(And I've got Eclipsites on my tail!)",
  ui_story_5033_50330302_12_dialog_content = "<color=#e8d9bb>Whoosh...</color>",
  ui_story_5033_50330302_13_dialog_content = "Ugh...",
  ui_story_5033_50330302_14_dialog_content = "Curses... Fall back!",
  ui_story_5033_50330302_15_dialog_content = "Hey, how come the Eclipsites went after them?",
  ui_story_5033_50330302_16_dialog_content = "<size=45><color=#e8d9bb>Shriek!</color></size>",
  ui_story_5033_50330302_17_dialog_content = "Who's there?!",
  ui_story_5033_50330302_18_dialog_content = "(That was a weird sound...)",
  ui_story_5033_50330302_19_dialog_content = "Grah...",
  ui_story_5033_50330302_20_dialog_content = "(The Eclipsites are gone too!)",
  ui_story_5033_50330302_21_dialog_content = "I just left for a while, yet the thugs took over my base...",
  ui_story_5033_50330302_22_dialog_content = "Go on and thank me. I count the rescue as your first request.",
  ui_story_5033_50330302_23_dialog_content = "Mr. <color=#FFB400>Nekoyashiki</color>, I presume?",
  ui_story_5033_50330302_24_dialog_content = "If it wasn't because of Taki, I wouldn't be dealing with you lot and your posh formalities.",
  ui_story_5033_50330302_25_dialog_content = "Just call me Nekoyashiki.",
  ui_story_5033_50330302_26_dialog_content = "What happened there? What was that shriek?",
  ui_story_5033_50330302_27_dialog_content = "For survival. I don't know why, but screaming in just the right manner drives them away.",
  ui_story_5033_50330302_28_dialog_content = "I'm not good with weapons, but I can at least defend myself with a few shrieks against the Eclipsites.",
  ui_story_5033_50330302_29_dialog_content = "In a pinch, I can even use them in the way I just did.",
  ui_story_5033_50330302_30_dialog_content = "So, do you trust me now, friends of Taki?",
  ui_story_5033_50330302_31_dialog_content = "That was impressive. I guess that's something privy only to you.",
  ui_story_5033_50330302_32_dialog_content = "Par for the course. Now tell me what you want to know.",
  ui_story_5033_50330302_33_dialog_content = "I'm Corax, and this is PlayerName. We're here to investigate a recent chain of serial killings in Umbraton.",
  ui_story_5033_50330302_34_dialog_content = "I know very little about the killer right now, except for certain modus operandi.",
  ui_story_5033_50330302_35_dialog_content = "Mind giving more details?",
  ui_story_5033_50330302_36_dialog_content = "Specifically, every victim died from an odd laceration.",
  ui_story_5033_50330302_37_dialog_content = "A small cut that shouldn't be fatal. The victims would stumble around like a zombie before suddenly dying.",
  ui_story_5033_50330302_38_dialog_content = "(They found that out, exactly as <color=#FFB400>she</color> predicted.)",
  ui_story_5033_50330302_39_dialog_content = "Hmm, that's a rough way to go.",
  ui_story_5033_50330302_40_dialog_content = "Looks like you're not one to be underestimated, if you were able to trace your way here from just that.",
  ui_story_5033_50330302_41_dialog_content = "Only <color=#FFB400>she</color> would know the history associated with that technique in all of Euphoria.",
  ui_story_5033_50330302_42_dialog_content = "?!",
  ui_story_5033_50330302_43_dialog_content = "Please elaborate.",
  ui_story_5033_50330302_44_dialog_content = "I'll take you to see <color=#FFB400>Raven's Blood</color>. They know more than I do.",
  ui_story_5033_50330302_45_dialog_content = "<color=#e8d9bb>Caw, caw...</color>",
  ui_story_5033_50330302_46_dialog_content = "I see the crows are already here.",
  ui_story_5033_50330302_47_dialog_content = "That means they welcome you two, visitors from Umbraton.",
  ui_story_5033_50330302_48_dialog_content = "<color=#e8d9bb>In another alley not too long ago</color>",
  ui_story_5033_50330302_49_dialog_content = "(Oh no, a dead end!)",
  ui_story_5033_50330302_50_dialog_content = "<color=#e8d9bb>Plop, plop, plop...</color>",
  ui_story_5033_50330302_51_dialog_content = "(Did Pollux and Casta follow me?!)",
  ui_story_5033_50330302_52_dialog_content = "(I don't want to die here!)",
  ui_story_5033_50330302_53_dialog_content = "You insist on looking for trouble, so now trouble has come to find you.",
  ui_story_5033_50330302_54_dialog_content = "B-But I've done nothing other than begging money off the two visitors...",
  ui_story_5033_50330302_55_dialog_content = "What business does Raven's Blood have with them?",
  ui_story_5033_50330302_56_dialog_content = "Don't think you lot can crawl your way to the top just 'cause the shady dealers have been dropping off like flies!",
  ui_story_5033_50330302_57_dialog_content = "Euphoria will never submit to you two mad women!",
  ui_story_5033_50330302_58_dialog_content = "Is that what you think?",
  ui_story_5033_50330302_59_dialog_content = "Don't come any closer! I-I've got a knife!",
  ui_story_5033_50330302_60_dialog_content = "I said don't come any closer!!",
  ui_story_5033_50330302_61_dialog_content = "Nngh, my knife! W-What do you think you're doing?!",
  ui_story_5033_50330302_62_dialog_content = "A dagger isn't sufficient for protecting oneself. It's more dangerous than you'll ever be.",
  ui_story_5033_50330302_63_dialog_content = "Try a weapon better suited for yourself next time.",
  ui_story_5033_50330302_64_dialog_content = "I-I don't understand what you mean at all.",
  ui_story_5033_50330302_65_dialog_content = "I just saved you from all those Eclipsites. Do you still not understand the situation you're in?",
  ui_story_5033_50330302_66_dialog_content = "Are you too dense to figure it out?",
  ui_story_5033_50330302_67_dialog_content = "Ingrates don't live long in Euphoria.",
  ui_story_5033_50330302_68_dialog_content = "Ugh! Keep that knife away from me! Okay, I'll talk, I'll tell you everything I know!",
  ui_story_5033_50330302_69_dialog_content = "You got tricked into coming here without even knowing how to hold a dagger.",
  ui_story_5033_50330302_70_dialog_content = "I'll give you a little inkling of just how little your employer cares for your life.",
  ui_story_5033_50330302_71_dialog_content = "Whether I use your neck as a prop depends on how cooperative you are.",
  ui_story_5033_50330302_72_dialog_content = "I said I'll talk!",
  ui_story_5033_50330302_73_dialog_content = "A lot of locals like me were assembled to lay in ambush in town.",
  ui_story_5033_50330302_74_dialog_content = "Lay in ambush?",
  ui_story_5033_50330302_75_dialog_content = "Yeah, the chief didn't think it was time to make a move yet.",
  ui_story_5033_50330302_76_dialog_content = "He wanted us to infiltrate the gang and mingle with them over the bars and gambling tables.",
  ui_story_5033_50330302_77_dialog_content = "Is that it?",
  ui_story_5033_50330302_78_dialog_content = "You never wondered what they wanted you to do next?",
  ui_story_5033_50330302_79_dialog_content = "M-Move the blade away!",
  ui_story_5033_50330302_80_dialog_content = "Okay, so I heard something going around the gang a couple of days back.",
  ui_story_5033_50330302_81_dialog_content = "Whoever hired us wanted us to spread some <color=#FFB400>rumors</color> around town.",
  ui_story_5033_50330302_82_dialog_content = "That's all I know, I swear! I don't even know what kind of rumors!",
  ui_story_5033_50330302_83_dialog_content = "I see.",
  ui_story_5033_50330302_84_dialog_content = "Aren't you going to let me go? I told you everything I know!",
  ui_story_5033_50330302_85_dialog_content = "Let me offer you another lesson on the house about surviving in Euphoria...",
  ui_story_5033_50330302_86_dialog_content = "Don't trust anybody here.",
  ui_story_5033_50330302_87_dialog_content = "Ah!",
  ui_story_5033_50330302_88_dialog_content = "Every single time, you just knock 'em out and dump 'em in the garbage.",
  ui_story_5033_50330302_89_dialog_content = "If people found out the esteemed Pollux was actually so merciful...",
  ui_story_5033_50330302_90_dialog_content = "How could they still believe the reputation associated with the name?",
  ui_story_5033_50330302_91_dialog_content = "They shouldn't. It's best not to trust anybody in Euphoria. Especially me.",
  ui_story_5033_50330302_92_dialog_content = "<color=#e8d9bb>Caw, caw...</color>",
  ui_story_5033_50330302_93_dialog_content = "Hmm, something's happening over on Nekoyashiki's end.",
  ui_story_5033_50330302_94_dialog_content = "Yeah, they tracked down Nekoyashiki like I anticipated.",
  ui_story_5033_50330302_95_dialog_content = "Though sooner than I thought.",
  ui_story_5033_50330302_96_dialog_content = "Let's get to <color=#FFB400>the usual place</color> and wait for Nekoyashiki and the two guests from Umbraton like we talked about.",
  ui_story_5033_50330302_97_dialog_content = "This isn't like you at all, Pollux. Again, why are we meeting them?",
  ui_story_5033_50330302_98_dialog_content = "I have an ulterior motive. I know the Shadowlord sent them.",
  ui_story_5033_50330302_99_dialog_content = "Is this about the <color=#FFB400>children</color>?",
  ui_story_5033_50330302_100_dialog_content = "The children, and Euphoria too, of course.",
  ui_story_5033_50330302_101_dialog_content = "I'm waiting for a storm to come and wash the filth away.",
  ui_story_5033_50330302_102_dialog_content = "Casta—",
  ui_story_5033_50330302_103_dialog_content = "Yeah?",
  ui_story_5033_50330302_104_dialog_content = "When did Euphoria's sky turn become a perpetual muddy gray?",
  ui_story_5033_50330302_105_dialog_content = "Mm...",
  ui_story_5033_50330302_106_dialog_content = "When did it start, I wonder?",
  ui_story_5033_50330401_1_dialog_content = "The Raven's Blood you mentioned... Is it one of Euphoria's many gangs?",
  ui_story_5033_50330401_2_dialog_content = "Actually, you made the right decision to seek my help.",
  ui_story_5033_50330401_3_dialog_content = "If you'd gone to anyone else, you'd have had to jump through hoops to find Raven's Blood.",
  ui_story_5033_50330401_4_dialog_content = "The gang is comprised of only two women: <color=#FFB400>Pollux</color> and <color=#FFB400>Casta</color>, but they're still a match for the major gangs.",
  ui_story_5033_50330401_5_dialog_content = "Pollux isn't one for power struggles between gangs. There are only a handful of people even capable of finding them.",
  ui_story_5033_50330401_6_dialog_content = "Is Pollux the \"she\" you mentioned?",
  ui_story_5033_50330401_7_dialog_content = "Yes.",
  ui_story_5033_50330401_8_dialog_content = "She knew of your arrival in Euphoria and was waiting for you to come to me.",
  ui_story_5033_50330401_9_dialog_content = "More ears to the ground is essential to survival here, right?",
  ui_story_5033_50330401_10_dialog_content = "Ha, you're not gonna catch me arguing against that, especially with visitors of such prestige.",
  ui_story_5033_50330401_11_dialog_content = "Anyways, she told me to bring you guys to her myself. To the \"usual spot,\" as she put it.",
  ui_story_5033_50330401_12_dialog_content = "Hopefully, she will be helpful in my investigation.",
  ui_story_5033_50330401_13_dialog_content = "Are you suspecting her?",
  ui_story_5033_50330401_14_dialog_content = "Relax, I'm not going to arrest anyone without a cause.",
  ui_story_5033_50330401_15_dialog_content = "Even if I have a suspect in mind, I'd still want concrete evidence before taking anyone in.",
  ui_story_5033_50330401_16_dialog_content = "Why? What are you waiting for, another victim to get cut?",
  ui_story_5033_50330401_17_dialog_content = "I would never wish for more innocent people to fall victim.",
  ui_story_5033_50330401_18_dialog_content = "This is a very serious matter, Mr. Nekoyashiki. I hope you can treat it with some respect.",
  ui_story_5033_50330401_19_dialog_content = "My, my, you've got a stick up your ass, haven't you? I just find your suspicion preposterous.",
  ui_story_5033_50330401_20_dialog_content = "That doesn't sound very convincing coming from me since I'm a friend of theirs, huh?",
  ui_story_5033_50330401_21_dialog_content = "Anyway, I'll take you to where they're waiting first.",
  ui_story_5033_50330401_22_dialog_content = "Then you can decide for yourself.",
  ui_story_5033_50330401_23_dialog_content = "(He sounds very sure of their innocence...)",
  ui_story_5033_50330401_24_dialog_content = "So, where is this place you've been talking about?",
  ui_story_5033_50330401_25_dialog_content = "Oh, we're almost there.",
  ui_story_5033_50330401_26_dialog_content = "We're going to an <color=#FFB400>old church</color>. It used to be a sight to behold, before it was abandoned.",
  ui_story_5033_50330401_27_dialog_content = "(A church?)",
  ui_story_5033_50330401_28_dialog_content = "Nuns have no place in Euphoria anymore.",
  ui_story_5033_50330401_29_dialog_content = "(The nuns are all gone, but the church is still here, huh?)",
  ui_story_5033_50330401_30_dialog_content = "<color=#e8d9bb>Euphoria: The Old Church</color>",
  ui_story_5033_50330401_31_dialog_content = "It's just as rundown all the other buildings.",
  ui_story_5033_50330401_32_dialog_content = "And like all the other buildings, it's only good for shelter.",
  ui_story_5033_50330401_33_dialog_content = "Euphoria's never had a savior, and no one here prays to the god of light anymore.",
  ui_story_5033_50330401_34_dialog_content = "The town has been purged clean of nuns over the last few years. This church no longer belongs to any denomination.",
  ui_story_5033_50330401_35_dialog_content = "The nuns were purged? By whom?",
  ui_story_5033_50330401_36_dialog_content = "If I knew, I wouldn't have lived long enough to be here today.",
  ui_story_5033_50330401_37_dialog_content = "Maybe it was just their fate. You don't negotiate with Death.",
  ui_story_5033_50330401_38_dialog_content = "The ubiquitous Grim Reaper snatches their life a few days later!",
  ui_story_5033_50330401_39_dialog_content = "They must've died because of the Grim Reaper, who shall not be spoken of!",
  ui_story_5033_50330401_40_dialog_content = "(This sounds just like what that man said...)",
  ui_story_5033_50330401_41_dialog_content = "(The serial murders, the slaughtered nuns... Could it all be the work of the Grim Reaper?)",
  ui_story_5033_50330401_42_dialog_content = "Speaking of which, we met a nun on our way here.",
  ui_story_5033_50330401_43_dialog_content = "We parted ways after arriving. I wonder how she's doing now.",
  ui_story_5033_50330401_44_dialog_content = "What? Is that true?!",
  ui_story_5033_50330401_45_dialog_content = "Yeah, she came with us from Umbraton. She was very obviously a nun.",
  ui_story_5033_50330401_46_dialog_content = "(A nun from Umbraton?)",
  ui_story_5033_50330401_47_dialog_content = "You should let Raven's Blood know when you meet them. I'm sure they'll be happy to hear it.",
  ui_story_5033_50330401_48_dialog_content = "<color=#e8d9bb>Meanwhile, in another alley</color>",
  ui_story_5033_50330401_49_dialog_content = "...?",
  ui_story_5033_50330401_50_dialog_content = "What's wrong, Pollux?",
  ui_story_5033_50330401_51_dialog_content = "Don't tell me those punks are still around.",
  ui_story_5033_50330401_52_dialog_content = "No, it's not them.",
  ui_story_5033_50330401_53_dialog_content = "But that's the only thing I'm sure about. The trace comes and goes, which is beyond them.",
  ui_story_5033_50330401_54_dialog_content = "Nobody in Euphoria can do that.",
  ui_story_5033_50330401_55_dialog_content = "Relax. Could be just a cat.",
  ui_story_5033_50330401_56_dialog_content = "Come on, let's go. The children are waiting, and Nekoyashiki should be showing up soon.",
  ui_story_5033_50330401_57_dialog_content = "You go ahead. I want to double back to that shopping district.",
  ui_story_5033_50330401_58_dialog_content = "I don't really think those punks worth your time.",
  ui_story_5033_50330401_59_dialog_content = "Who cares about them?",
  ui_story_5033_50330401_60_dialog_content = "I just want to get some surprises for the kids.",
  ui_story_5033_50330401_61_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330401_62_dialog_content = "...",
  ui_story_5033_50330401_63_dialog_content = "(Did she... sense my presence?)",
  ui_story_5033_50330401_64_dialog_content = "<color=#e8d9bb>Meow...</color>",
  ui_story_5033_50330401_65_dialog_content = "Meow!",
  ui_story_5033_50330401_66_dialog_content = "Kill Pollux.",
  ui_story_5033_50330401_67_dialog_content = "...",
  ui_story_5033_50330401_68_dialog_content = "(... Patience is a forgotten virtue, it seems.)",
  ui_story_5033_50330401_69_dialog_content = "<color=#e8d9bb>*Rips paper*</color>",
  ui_story_5033_50330401_70_dialog_content = "Eh?",
  ui_story_5033_50330401_71_dialog_content = "<size=45>Grah!</size>",
  ui_story_5033_50330401_72_dialog_content = "(Perfect timing.)",
  ui_story_5033_50330401_73_dialog_content = "(I'll destroy you along with this piece of trash.)",
  ui_story_5033_50330502_1_dialog_content = "<color=#e8d9bb>Istvan Gang in Umbraton</color>",
  ui_story_5033_50330502_2_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5033_50330502_3_dialog_content = "Looks like a storm is coming.",
  ui_story_5033_50330502_4_dialog_content = "A bunch of clouds, meaning shadow will spread throughout Umbraton.",
  ui_story_5033_50330502_5_dialog_content = "Only a matter of time before it hits Euphoria too.",
  ui_story_5033_50330502_6_dialog_content = "Are you concerned about Corax's investigation?",
  ui_story_5033_50330502_7_dialog_content = "No.",
  ui_story_5033_50330502_8_dialog_content = "I'm just waiting for the weather to turn.",
  ui_story_5033_50330502_9_dialog_content = "Over the past few days, I've gained a new perspective regarding Corax's case.",
  ui_story_5033_50330502_10_dialog_content = "But I've got no definitive proof yet, so it's just personal speculation.",
  ui_story_5033_50330502_11_dialog_content = "No problem. Let's hear it.",
  ui_story_5033_50330502_12_dialog_content = "I only realized it while scanning old newspapers.",
  ui_story_5033_50330502_13_dialog_content = "Fourteen years ago, something happened in Euphoria that caused quite a stir in Umbraton.",
  ui_story_5033_50330502_14_dialog_content = "At the time, the place was better known as \"Wonderland.\"",
  ui_story_5033_50330502_15_dialog_content = "You probably know about the incident better than I do.",
  ui_story_5033_50330502_16_dialog_content = "Hmm, I do recall the <color=#FFB400>Gemini Incident</color>...",
  ui_story_5033_50330502_17_dialog_content = "Yes. That was when underground fighting was the fad in Euphoria and made a lot of people rich.",
  ui_story_5033_50330502_18_dialog_content = "Even the captain of the mercenaries in Euphoria stopped relying on commissions for money.",
  ui_story_5033_50330502_19_dialog_content = "That's nothing unusual. The only commissions left for them were probably fighting in those underground arenas, anyway.",
  ui_story_5033_50330502_20_dialog_content = "What irony.",
  ui_story_5033_50330502_21_dialog_content = "Anyway, someone was pulling the strings behind the scenes, and under their orders, the captain trained two up-and-coming stars.",
  ui_story_5033_50330502_22_dialog_content = "They were two very young girls trained under two entirely different regimens by the captain...",
  ui_story_5033_50330502_23_dialog_content = "One underwent internal mercenary training and specialized in their fighting style.",
  ui_story_5033_50330502_24_dialog_content = "The other joined other mercs out in the field in actual combat, training her adaptability for all situations.",
  ui_story_5033_50330502_25_dialog_content = "Euphoria called them the mercenary group's Gemini twins.",
  ui_story_5033_50330502_26_dialog_content = "Yet the first official gig they got...",
  ui_story_5033_50330502_27_dialog_content = "Was a <color=#FFB400>fight to the death</color> against each other in an arena.",
  ui_story_5033_50330502_28_dialog_content = "Let me guess. There was no show of emotional hysterics whatsoever and one killed the other point blank, right?",
  ui_story_5033_50330502_29_dialog_content = "Yes.",
  ui_story_5033_50330502_30_dialog_content = "There are no reports on how the fight went down, but according to gossip from eyewitnesses...",
  ui_story_5033_50330502_31_dialog_content = "The child who'd survived was seriously injured with small lacerations all over her body. She was practically dead.",
  ui_story_5033_50330502_32_dialog_content = "After that incident, she vanished altogether, never to be seen again.",
  ui_story_5033_50330502_33_dialog_content = "The public lost interest in her in the chaos that struck Umbraton a few years later, anyway.",
  ui_story_5033_50330502_34_dialog_content = "You think the girl who died actually <color=#FFB400>still lives</color>.",
  ui_story_5033_50330502_35_dialog_content = "Yes.",
  ui_story_5033_50330502_36_dialog_content = "That's too simple, isn't it? I'm not doubting she couldn't have survived, just that...",
  ui_story_5033_50330502_37_dialog_content = "We can't be sure she's the only one who knows that technique.",
  ui_story_5033_50330502_38_dialog_content = "After all, Euphoria is no longer the place it used to be.",
  ui_story_5033_50330502_39_dialog_content = "Prior to the Darkover Crisis, that mercenary company boasted a few members who could wield those skills, and they taught others...",
  ui_story_5033_50330502_40_dialog_content = "That's a lot of potential suspects.",
  ui_story_5033_50330502_41_dialog_content = "You're correct, which is why this is just speculation.",
  ui_story_5033_50330502_42_dialog_content = "However, say there was a survivor of that ill-fated death match, and they've lived anonymously up til now.",
  ui_story_5033_50330502_43_dialog_content = "It wouldn't be a good thing for either Umbraton or Euphoria.",
  ui_story_5033_50330502_44_dialog_content = "Do you know what the hardest thing is for a regular participant in underground fighting?",
  ui_story_5033_50330502_45_dialog_content = "It's not survival, is it? Since life and death is just par for the course there.",
  ui_story_5033_50330502_46_dialog_content = "It's promptly cutting the rotten tissues off your body.",
  ui_story_5033_50330502_47_dialog_content = "Something so simple?",
  ui_story_5033_50330502_48_dialog_content = "Because old tissue prevents healthy tissue from forming.",
  ui_story_5033_50330502_49_dialog_content = "Given time, it ruins your physique and robs you of the privilege to compete.",
  ui_story_5033_50330502_50_dialog_content = "That'd be a job for a doctor, right?",
  ui_story_5033_50330502_51_dialog_content = "I'd have the doctor I trusted the most handle it.",
  ui_story_5033_50330502_52_dialog_content = "But then again, didn't the other girl supposedly also survive?",
  ui_story_5033_50330502_53_dialog_content = "At the very least, this proves that not everyone who is subjected to that blade technique dies.",
  ui_story_5033_50330502_54_dialog_content = "<color=#e8d9bb>Knock, knock, knock—</color>",
  ui_story_5033_50330502_55_dialog_content = "Uncle Istvan? The victim that Corax found... He's awake now.",
  ui_story_5033_50330502_56_dialog_content = "Ah, speak of the devil.",
  ui_story_5033_50330601_1_dialog_content = "Go ahead.",
  ui_story_5033_50330601_2_dialog_content = "<color=#e8d9bb>Creak...</color>",
  ui_story_5033_50330601_3_dialog_content = "Look, everyone! Nekoyashiki's back!",
  ui_story_5033_50330601_4_dialog_content = "Hush. Not so loud, Latan. I'm looking for Casta, have you seen her?",
  ui_story_5033_50330601_5_dialog_content = "Casta went out to get the bread. You want me to go get her?",
  ui_story_5033_50330601_6_dialog_content = "Go tell her we have guests from Umbraton.",
  ui_story_5033_50330601_7_dialog_content = "Okay! You can play with the others while I go get her!",
  ui_story_5033_50330601_8_dialog_content = "Did you bring us any treats, Nekoyashiki?",
  ui_story_5033_50330601_9_dialog_content = "Of course.",
  ui_story_5033_50330601_10_dialog_content = "Come over here, Nekoyashiki! Bend down, I found something nice for you!",
  ui_story_5033_50330601_11_dialog_content = "H-Hey, don't yank me around like that, kid...",
  ui_story_5033_50330601_12_dialog_content = "Wow... Why are there so many children here?",
  ui_story_5033_50330601_13_dialog_content = "These kids were all taken in by Raven's Blood, and... Ow! Hey, what are you pulling my hair for?!",
  ui_story_5033_50330601_14_dialog_content = "Heehee! Look, I found this cockroach the other day! It wasn't easy to catch... Do you like it?",
  ui_story_5033_50330601_15_dialog_content = "You little rascal, get over here!",
  ui_story_5033_50330601_16_dialog_content = "Oh no, Nekoyashiki's mad! Run away!!",
  ui_story_5033_50330601_17_dialog_content = "Looks like he doesn't have the time to explain things to me right now.",
  ui_story_5033_50330601_18_dialog_content = "There isn't much to explain.",
  ui_story_5033_50330601_19_dialog_content = "Most of these children ended up here after being abandoned in the streets.",
  ui_story_5033_50330601_20_dialog_content = "Some were orphaned after their parents were killed by gang violence, and others were rescued from the criminal underground.",
  ui_story_5033_50330601_21_dialog_content = "Until a safe and suitable home is found for them, these kids are under the protection of Raven's Blood. That's us.",
  ui_story_5033_50330601_22_dialog_content = "You must be the Casta that Nekoyashiki mentioned.",
  ui_story_5033_50330601_23_dialog_content = "We're—",
  ui_story_5033_50330601_24_dialog_content = "No need for introductions; we know exactly why you're here and what you're investigating. Let's wait for Pollux to return before we talking.",
  ui_story_5033_50330601_25_dialog_content = "I still need to feed these rascals.",
  ui_story_5033_50330601_26_dialog_content = "That's fine. We don't mind waiting.",
  ui_story_5033_50330601_27_dialog_content = "Alright, everyone! It's almost naptime, so finish eating your bread and go straight to bed!",
  ui_story_5033_50330601_28_dialog_content = "Okay!",
  ui_story_5033_50330601_29_dialog_content = "*Wincing* They finally let go of my hair... These kids are something else.",
  ui_story_5033_50330601_30_dialog_content = "If you're finished, let's continue our conversation.",
  ui_story_5033_50330601_31_dialog_content = "Since I'm the Odd Jobs member, I'll catch everyone up on the situation.",
  ui_story_5033_50330601_32_dialog_content = "Regarding our two guests here, I understand that Taki pointed you in my direction.",
  ui_story_5033_50330601_33_dialog_content = "However, Raven's Blood is much more knowledgeable about Euphoria, and can help you out a lot more than I can.",
  ui_story_5033_50330601_34_dialog_content = "As for you Raven's Blood ladies, I've brought you the folks you asked for, so now I'll leave the rest to you.",
  ui_story_5033_50330601_35_dialog_content = "I'll be leaving now, as I still have other business to attend to.",
  ui_story_5033_50330601_36_dialog_content = "Just go, don't come bothering us with your annoying presence. We'll call for you if we need you.",
  ui_story_5033_50330601_37_dialog_content = "Ouch, that hurts. Tossing me aside once you're done using me?",
  ui_story_5033_50330601_38_dialog_content = "You're the one who said you were leaving, so leave already. I still have bread to serve.",
  ui_story_5033_50330601_39_dialog_content = "Let me help you, Casta!",
  ui_story_5033_50330601_40_dialog_content = "I can help too! I can help too!",
  ui_story_5033_50330601_41_dialog_content = "Alright, then. Latan, you can split this bread up amongst the younger kids. Schewe, you can hand out the butter, and make sure the little ones get extra.",
  ui_story_5033_50330601_42_dialog_content = "Got it!",
  ui_story_5033_50330601_43_dialog_content = "Sure, I know where the butter is. I'll go get it!",
  ui_story_5033_50330601_44_dialog_content = "Sorry, but I have to ask... How did the kids sustain those injuries?",
  ui_story_5033_50330601_45_dialog_content = "Did you think homeless orphans would have it easy on the streets of Euphoria?",
  ui_story_5033_50330601_46_dialog_content = "They were hurt by other people, so we bandaged up their wounds... Simple as that.",
  ui_story_5033_50330601_47_dialog_content = "Would you mind if I took a look at their injuries? I was a doctor once upon a time.",
  ui_story_5033_50330601_48_dialog_content = "A doctor, huh?",
  ui_story_5033_50330601_49_dialog_content = "I can see that their wounds have been wrapped very carefully, and the bandages are quite clean.",
  ui_story_5033_50330601_50_dialog_content = "But a few of the kids look a little worse for wear. They'll require some extra attention.",
  ui_story_5033_50330601_51_dialog_content = "Heh, it must be our lucky day. You'll have to wait until they finish eating, though.",
  ui_story_5033_50330601_52_dialog_content = "(Hmm? Is someone tugging on my hand?)",
  ui_story_5033_50330601_53_dialog_content = "Yes? Is something wrong, little girl?",
  ui_story_5033_50330601_54_dialog_content = "Um... N-Nekoyashiki said that he left some candy in your pocket...",
  ui_story_5033_50330601_55_dialog_content = "A-And that I should ask you if I want some.",
  ui_story_5033_50330601_56_dialog_content = "When did Nekoyashiki put candy in my pocket? Why was I unaware of this...",
  ui_story_5033_50330601_57_dialog_content = "Huh? Look at that. There really is candy in my pocket!",
  ui_story_5033_50330601_58_dialog_content = "Th-Then... Can I have some?",
  ui_story_5033_50330601_59_dialog_content = "Of course you can! Here you go. Sorry to keep you waiting.",
  ui_story_5033_50330601_60_dialog_content = "Thank you!",
  ui_story_5033_50330601_61_dialog_content = "Hey! Don't eat so many sweets right before a meal!",
  ui_story_5033_50330601_62_dialog_content = "Oh... Okay.",
  ui_story_5033_50330601_63_dialog_content = "<color=#e8d9bb>Growl...</color>",
  ui_story_5033_50330601_64_dialog_content = "Hungry?",
  ui_story_5033_50330601_65_dialog_content = "S-Sorry. All that running around worked up an appetite. I can't do anything about my stomach growling, unfortunately.",
  ui_story_5033_50330601_66_dialog_content = "I promise I'm not here to steal bread from children though.",
  ui_story_5033_50330601_67_dialog_content = "Hah, you two are quite the interesting duo. A doctor-turned-assassin, and a child in a teenager's body.",
  ui_story_5033_50330601_68_dialog_content = "Maybe Pollux was right to invite you here, after all.",
  ui_story_5033_50330601_69_dialog_content = "Granted, it's always smarter to work with Umbraton folks rather than against them.",
  ui_story_5033_50330601_70_dialog_content = "That smell—it's croissants!",
  ui_story_5033_50330601_71_dialog_content = "That's right, and I brought plenty for everyone, so all of you can eat your fill today.",
  ui_story_5033_50330601_72_dialog_content = "Go greet our guests, Pollux. I can hand these out myself. Alright, whoever wants a croissant, come with me!",
  ui_story_5033_50330601_73_dialog_content = "Okay!",
  ui_story_5033_50330601_74_dialog_content = "You two are more than welcome to have some as well.",
  ui_story_5033_50330601_75_dialog_content = "Thank you, we'll help ourselves then.",
  ui_story_5033_50330601_76_dialog_content = "Here, PlayerName.",
  ui_story_5033_50330601_77_dialog_content = "Th-Thank you...",
  ui_story_5033_50330601_78_dialog_content = "Sorry, I'm supposed to help, but all I did was make things more difficult.",
  ui_story_5033_50330601_79_dialog_content = "Don't be so hard on yourself.",
  ui_story_5033_50330601_80_dialog_content = "After all, we've found someone we can work with here whom we can trust. That's far better than what I was expecting.",
  ui_story_5033_50330601_81_dialog_content = "Mm. Someone who would run a shelter in Euphoria just for children...",
  ui_story_5033_50330601_82_dialog_content = "I bet they're not just super strong. They must also be really kind.",
  ui_story_5033_50330601_83_dialog_content = "You flatter us. But truly, taking care of all these children is no easy task.",
  ui_story_5033_50330601_84_dialog_content = "You haven't considered sending them to a better place?",
  ui_story_5033_50330601_85_dialog_content = "Umbraton has plenty of orphanages with all the amenities they could ever need.",
  ui_story_5033_50330601_86_dialog_content = "Of course we've thought about it. It's the reason we've decided to work with you.",
  ui_story_5033_50330601_87_dialog_content = "But not everyone is capable of seeing Euphoria's orphans as any other children. I need to find a place willing to accept them.",
  ui_story_5033_50330601_88_dialog_content = "I see.",
  ui_story_5033_50330601_89_dialog_content = "Not all the children are willing to leave this place either. On top of that, Euphoria and Umbraton haven't been on the best of terms lately...",
  ui_story_5033_50330601_90_dialog_content = "I would like to wait until things settle down before coming up with more long-term solutions.",
  ui_story_5033_50330601_91_dialog_content = "I understand. As far as the children are concerned, I can guarantee that Umbraton will welcome them with open arms.",
  ui_story_5033_50330601_92_dialog_content = "And since we'll be investigating things for a while, maybe we can lend a hand around here too?",
  ui_story_5033_50330601_93_dialog_content = "Oh, right! When the nun gets here, maybe she can help with the kids.",
  ui_story_5033_50330601_94_dialog_content = "Nun? Are you saying that the church dispatched a nun to our church?",
  ui_story_5033_50330601_95_dialog_content = "I think so. While we were on the airship to Euphoria, we ran into a nun who said she was coming here.",
  ui_story_5033_50330601_96_dialog_content = "Honestly, I thought she would be here by now...",
  ui_story_5033_50330601_97_dialog_content = "Euphoria hasn't seen a nun in a long time. Perhaps they simply don't wish to come.",
  ui_story_5033_50330601_98_dialog_content = "But this church still stands. Even if it's somewhat decrepit, I don't think that would stop them from wanting to come here.",
  ui_story_5033_50330601_99_dialog_content = "You know, it was a nun that gave me my name when she found me wandering the streets of Euphoria a long time ago.",
  ui_story_5033_50330601_100_dialog_content = "But after I left the church, I lost contact with her.",
  ui_story_5033_50330601_101_dialog_content = "Then, about eight or nine years ago, I heard that she rescued a bunch of children from the chaos. She'd gone to Umbraton hoping to save more, only to die in an accident on the way.",
  ui_story_5033_50330601_102_dialog_content = "As a result, this church fell into disrepair and even vandalism.",
  ui_story_5033_50330601_103_dialog_content = "And that's when you two...",
  ui_story_5033_50330601_104_dialog_content = "Correct. That's when Casta and I established Raven's Blood and decided to fix this place up so it could take in wandering children once again.",
  ui_story_5033_50330601_105_dialog_content = "But if the church has sent a new nun to come take over, then maybe it's all the better.",
  ui_story_5033_50330601_106_dialog_content = "\"All the better\"? You can't seriously mean that, right, Pollux?",
  ui_story_5033_50330601_107_dialog_content = "I thought... I thought you'd say that for us, no one would ever take <color=#FFB400>Sister Matilda's</color> place.",
  ui_story_5033_50330601_108_dialog_content = "No one is replacing her, Casta.",
  ui_story_5033_50330601_109_dialog_content = "It sounds like you two have a very strong emotional bond with this Sister Matilda.",
  ui_story_5033_50330601_110_dialog_content = "I'm an Euphorian orphan myself. Sister Matilda was the one who took me in.",
  ui_story_5033_50330601_111_dialog_content = "If it wasn't for her, there's no telling what the gangs here would've done to me. As for Pollux...",
  ui_story_5033_50330601_112_dialog_content = "That's enough reminiscing for one day, Casta. It's our turn to listen to Mr. Corax and learn about his investigation.",
  ui_story_5033_50330601_113_dialog_content = "I already know the gist of what's going on, thanks to Nekoyashiki.",
  ui_story_5033_50330601_114_dialog_content = "A series of mysterious assassinations have taken place in Umbraton, and you suspect that the killer is somehow connected to Euphoria.",
  ui_story_5033_50330601_115_dialog_content = "I think you two will be more than willing to assist me once you hear more details about my investigation.",
  ui_story_5033_50330601_116_dialog_content = "Why is that?",
  ui_story_5033_50330601_117_dialog_content = "It pains me to tell you... But Sister Matilda didn't die in an accident.",
  ui_story_5033_50330601_118_dialog_content = "We learned from the local church that the mysterious wounds on her body were exactly the same as those of the other victims in the case.",
  ui_story_5033_50330601_119_dialog_content = "What?!",
  ui_story_5033_50330601_120_dialog_content = "<color=#e8d9bb>*Shatter*</color>",
  ui_story_5033_50330601_121_dialog_content = "<size=45>What did you say just now?! Say it again!</size>",
  ui_story_5033_50330601_122_dialog_content = "Please calm down, you're scaring the children.",
  ui_story_5033_50330601_123_dialog_content = "...",
  ui_story_5033_50330601_124_dialog_content = "I-It's okay everyone, don't be afraid... Casta just got a little worked up, that's all.",
  ui_story_5033_50330601_125_dialog_content = "Apologies, children. We've just received some very shocking news.",
  ui_story_5033_50330601_126_dialog_content = "Us grown-ups are going outside to continue our conversation. Come find us if you need anything, and make sure to eat all your food, okay?",
  ui_story_5033_50330601_127_dialog_content = "Okay...",
  ui_story_5033_50330601_128_dialog_content = "The kids still look a little shaken. I'll stay and keep them company.",
  ui_story_5033_50330601_129_dialog_content = "Thank you, PlayerName.",
  ui_story_5033_50330601_130_dialog_content = "Let's go. We still have <size=45>a lot to discuss</size>.",
  ui_story_5033_50330701_1_dialog_content = "Munch, munch, munch...",
  ui_story_5033_50330701_2_dialog_content = "...",
  ui_story_5033_50330701_3_dialog_content = "Why aren't you eating, Latan?",
  ui_story_5033_50330701_4_dialog_content = "You keep staring outside. Are you worried about them?",
  ui_story_5033_50330701_5_dialog_content = "Yeah... We almost never see Casta get that angry.",
  ui_story_5033_50330701_6_dialog_content = "Or Pollux... Even though she looked a lot calmer than Casta, I could tell she was furious.",
  ui_story_5033_50330701_7_dialog_content = "Something really, really bad must have happened.",
  ui_story_5033_50330701_8_dialog_content = "You figured all of that out for yourself, huh?",
  ui_story_5033_50330701_9_dialog_content = "(What a perceptive little kid she is.)",
  ui_story_5033_50330701_10_dialog_content = "Yeah, I did.",
  ui_story_5033_50330701_11_dialog_content = "Usually, no matter what happens or what kinds of news Nekoyashiki brings them,",
  ui_story_5033_50330701_12_dialog_content = "they never show any signs of being upset. Not in front of us, at least.",
  ui_story_5033_50330701_13_dialog_content = "That was the first time we've ever seen them so angry, or heard them yell like that.",
  ui_story_5033_50330701_14_dialog_content = "Don't worry too much about it, okay? Once we figure everything out, I'm sure they won't be angry anymore.",
  ui_story_5033_50330701_15_dialog_content = "Does it... Have something to do with Sister <color=#FFB400>Matilda</color>?",
  ui_story_5033_50330701_16_dialog_content = "You heard that too?",
  ui_story_5033_50330701_17_dialog_content = "Uh-huh, I was listening to you guys all along.",
  ui_story_5033_50330701_18_dialog_content = "Well, I can tell you that yes, it has something to do with Sister Matilda.",
  ui_story_5033_50330701_19_dialog_content = "As for the rest of the details, we still have a lot of investigating to do.",
  ui_story_5033_50330701_20_dialog_content = "But once we finish our work, I'm sure Pollux and Casta will share the rest of it with you.",
  ui_story_5033_50330701_21_dialog_content = "Oh... Okay.",
  ui_story_5033_50330701_22_dialog_content = "Hmm?",
  ui_story_5033_50330701_23_dialog_content = "Is something the matter?",
  ui_story_5033_50330701_24_dialog_content = "I thought I saw someone outside just now... Behind you, over there.",
  ui_story_5033_50330701_25_dialog_content = "<color=#e8d9bb>Creak...</color>",
  ui_story_5033_50330701_26_dialog_content = "I don't see anyone.",
  ui_story_5033_50330701_27_dialog_content = "Weird... maybe I imagined it? I could've sworn I saw someone pass by...",
  ui_story_5033_50330701_28_dialog_content = "Maybe they're hiding? I'll try sensing their presence...",
  ui_story_5033_50330701_29_dialog_content = "What do you mean by that?",
  ui_story_5033_50330701_30_dialog_content = "Er... Simply put, I have a special power that lets me find people without seeing them. It's kind of my thing.",
  ui_story_5033_50330701_31_dialog_content = "I'm really sensitive to Lumina, as well as Darkflow.",
  ui_story_5033_50330701_32_dialog_content = "That sounds so cool!",
  ui_story_5033_50330701_33_dialog_content = "<color=#e8d9bb>...</color>",
  ui_story_5033_50330701_34_dialog_content = "I can sense three very powerful people in that corridor outside. That ought to be Corax, Casta, and Pollux.",
  ui_story_5033_50330701_35_dialog_content = "There are also a few Eclipsites roaming the area, but they're still pretty far from the church.",
  ui_story_5033_50330701_36_dialog_content = "And beyond that... all I sense are ordinary people.",
  ui_story_5033_50330701_37_dialog_content = "Oh... Maybe I was just seeing things, after all.",
  ui_story_5033_50330701_38_dialog_content = "No, I think you're just a little anxious. Let's go back inside the church and wait for Pollux and the others, okay?",
  ui_story_5033_50330701_39_dialog_content = "We don't want those Eclipsites to catch sight of us out here.",
  ui_story_5033_50330701_40_dialog_content = "Okay.",
  ui_story_5033_50330701_41_dialog_content = "Good girl, go on and finish eating.",
  ui_story_5033_50330701_42_dialog_content = "I hope everything's going well on Corax's end...",
  ui_story_5033_50330701_43_dialog_content = "I was assigned to this case roughly one month ago.",
  ui_story_5033_50330701_44_dialog_content = "The Shadowlord needed someone to examine the corpses, and that was precisely when I discovered signs of the murderer's preferred method of killing.",
  ui_story_5033_50330701_45_dialog_content = "<color=#e8d9bb>One month ago...</color>",
  ui_story_5033_50330701_46_dialog_content = "So you're saying you saw these kinds of wounds on a patient who died a few days ago?",
  ui_story_5033_50330701_47_dialog_content = "Indeed, and a bizarre patient, at that. His condition was far from critical, yet he died all the same.",
  ui_story_5033_50330701_48_dialog_content = "I'm beginning to think he didn't die from his illness...",
  ui_story_5033_50330701_49_dialog_content = "I believe a serial murderer is behind these deaths.",
  ui_story_5033_50330701_50_dialog_content = "Have there been any recent reports of strange deaths such as this?",
  ui_story_5033_50330701_51_dialog_content = "Yes, but their bodies have already been laid to rest... Unless you need me to excavate them?",
  ui_story_5033_50330701_52_dialog_content = "I do. We need to re-evaluate their causes of death.",
  ui_story_5033_50330701_53_dialog_content = "All of our findings must be reported to the Shadowlord as well.",
  ui_story_5033_50330701_54_dialog_content = "Fine, but I don't like this...",
  ui_story_5033_50330701_55_dialog_content = "And what about this guy? Do I bury him?",
  ui_story_5033_50330701_56_dialog_content = "D-Don't be so hasty. He's still breathing... I might be able to save him.",
  ui_story_5033_50330701_57_dialog_content = "Ah, suit yourself.",
  ui_story_5033_50330701_58_dialog_content = "There are strange scars on the bodies of the victims.",
  ui_story_5033_50330701_59_dialog_content = "What's more, the culprit has repeated their crime multiple times.",
  ui_story_5033_50330701_60_dialog_content = "If it wasn't for the recent increase in these near-identical murders, we might never have discovered that this was the work of a serial killer.",
  ui_story_5033_50330701_61_dialog_content = "Although we've ascertained an M.O., we have yet to find any other useful clues.",
  ui_story_5033_50330701_62_dialog_content = "During my investigation, I discovered that the body of a person who died years ago in an alleged accident bore the same scars as those of the serial killer's victims.",
  ui_story_5033_50330701_63_dialog_content = "One of the tips we received was from a local church. They gave us Sister Matilda's accident file.",
  ui_story_5033_50330701_64_dialog_content = "How did you link the killer to Euphoria? Where's the bastard?!",
  ui_story_5033_50330701_65_dialog_content = "We still don't know the killer's identity. As for how they are connected to Euphoria... It's only speculation on our end.",
  ui_story_5033_50330701_66_dialog_content = "Rumors say that Euphoria's haunted by a Grim Reaper.",
  ui_story_5033_50330701_67_dialog_content = "A Grim Reaper that supposedly only appears before those who dare disrupt the peace in Euphoria or break its rules.",
  ui_story_5033_50330701_68_dialog_content = "He appears without a sound, takes the lives of his victims without leaving so much as a trace of his presence.",
  ui_story_5033_50330701_69_dialog_content = "What exactly are you going on about?",
  ui_story_5033_50330701_70_dialog_content = "The killer uses a high-level assassination art.",
  ui_story_5033_50330701_71_dialog_content = "One that is rumored to leave no traces behind, not even a single drop of blood.",
  ui_story_5033_50330701_72_dialog_content = "No. It definitely leaves something behind.",
  ui_story_5033_50330701_73_dialog_content = "Scars. Granted, they only look like ordinary scratch marks.",
  ui_story_5033_50330701_74_dialog_content = "Pollux, you know of this technique?",
  ui_story_5033_50330701_75_dialog_content = "Of course I do... because <color=#FFB400>I can use it as well</color>.",
  ui_story_5033_50330701_76_dialog_content = "What?!",
  ui_story_5033_50330702_1_dialog_content = "We finished our bread a long time ago... Why hasn't Casta come back to tell us to go to bed?",
  ui_story_5033_50330702_2_dialog_content = "I heard Casta say that she needs to see the doctor after she finishes eating.",
  ui_story_5033_50330702_3_dialog_content = "So that guy's a doctor?",
  ui_story_5033_50330702_4_dialog_content = "Yup, the tan one is a doctor.",
  ui_story_5033_50330702_5_dialog_content = "So when will they be back?",
  ui_story_5033_50330702_6_dialog_content = "Let's just go to sleep for now.",
  ui_story_5033_50330702_7_dialog_content = "I'm sure they'll be back after we wake up.",
  ui_story_5033_50330702_8_dialog_content = "Latan's right, everyone. It's nap time, so get some rest and everything will be taken care of by the time you wake up.",
  ui_story_5033_50330702_9_dialog_content = "Hmph... Sounds like you're just saying that.",
  ui_story_5033_50330702_10_dialog_content = "You think we're a bunch of three-year-olds?",
  ui_story_5033_50330702_11_dialog_content = "Ahh! Y-You're the kid from before! The one who tried to give that roach to Nekoyashiki...",
  ui_story_5033_50330702_12_dialog_content = "Hehe, that's right.",
  ui_story_5033_50330702_13_dialog_content = "You're just trying to trick us into taking our naps, aren't you? Well, we're not buying it!",
  ui_story_5033_50330702_14_dialog_content = "Tell us what you guys are doing here, and don't you dare lie!",
  ui_story_5033_50330702_15_dialog_content = "(Jeez... Taking care of kids can be a real pain!)",
  ui_story_5033_50330702_16_dialog_content = "We came looking for Raven's Blood... Well, rather, it was them who reached out to us.",
  ui_story_5033_50330702_17_dialog_content = "We're investigating a very serious crime together.",
  ui_story_5033_50330702_18_dialog_content = "What kind of crime?",
  ui_story_5033_50330702_19_dialog_content = "Uh...",
  ui_story_5033_50330702_20_dialog_content = "(I have to think of a way to scare them, so they don't keep asking about it!)",
  ui_story_5033_50330702_21_dialog_content = "<anim type=Shake><size=45>A very scary murder case!!!</size></anim>",
  ui_story_5033_50330702_22_dialog_content = "...",
  ui_story_5033_50330702_23_dialog_content = "D-Doesn't that sound scary to you guys?",
  ui_story_5033_50330702_24_dialog_content = "We're from Euphoria... You really think that scares us?",
  ui_story_5033_50330702_25_dialog_content = "What? I mean, it should... Sorry, for a second I forgot.",
  ui_story_5033_50330702_26_dialog_content = "Hahaha! This guy thinks we're just a bunch of normal boys and girls! What a weirdo!",
  ui_story_5033_50330702_27_dialog_content = "Yeah! B-Besides... Everyone hates Euphoria's little kids.",
  ui_story_5033_50330702_28_dialog_content = "There's nothing weird about it!",
  ui_story_5033_50330702_29_dialog_content = "I don't care who you are or where you came from. In my eyes, you ARE just a bunch of normal kids.",
  ui_story_5033_50330702_30_dialog_content = "All you guys should think about is eating, and sleeping, and having fun! Don't worry about any of this scary or dangerous stuff.",
  ui_story_5033_50330702_31_dialog_content = "Pollux and the others will resolve them.",
  ui_story_5033_50330702_32_dialog_content = "PlayerName has a point... plus Pollux and Casta told us the same thing too.",
  ui_story_5033_50330702_33_dialog_content = "Okay, fine...",
  ui_story_5033_50330702_34_dialog_content = "Huh... Guess you're really a nice guy, after all.",
  ui_story_5033_50330702_35_dialog_content = "We won't ask any more questions. Nap with us!",
  ui_story_5033_50330702_36_dialog_content = "Yeah! Come nap with us, Mr. Navigator!",
  ui_story_5033_50330702_37_dialog_content = "Mr. Navigator, I want more candy!",
  ui_story_5033_50330702_38_dialog_content = "H-Hey, not all at once, guys! I'm about to fall over!",
  ui_story_5033_50330702_39_dialog_content = "You have candy? We want some too...",
  ui_story_5033_50330702_40_dialog_content = "I do, I do, it's right here. Nekoyashiki stuffed a bunch into my pocket.",
  ui_story_5033_50330702_41_dialog_content = "One at a time, guys. No need to hurry.",
  ui_story_5033_50330702_42_dialog_content = "Nekoyashiki that bastard, sure knows what's up.",
  ui_story_5033_50330702_43_dialog_content = "I-I don't think a little kid should talk about grown-ups like that...",
  ui_story_5033_50330702_44_dialog_content = "Nekoyashiki is your senior, after all. You should show him a little more respect.",
  ui_story_5033_50330702_45_dialog_content = "Hey, what gives?! Quit your preaching and gimme my candy!",
  ui_story_5033_50330702_46_dialog_content = "Nekoyashiki left this candy with me, you know? If you don't respect him, why should I share some with you?",
  ui_story_5033_50330702_47_dialog_content = "What are you talking about? I get along great with Nekoyashiki, and he would never tell me to \"respect\" him!",
  ui_story_5033_50330702_48_dialog_content = "Wanna know something? When Nekoyashiki first came to Euphoria, he had a really rotten attitude.",
  ui_story_5033_50330702_49_dialog_content = "But then a bunch of gangsters beat the living crap out of him!",
  ui_story_5033_50330702_50_dialog_content = "He showed up here, all bloody and bruised up. It was only thanks to Pollux and Casta that he survived.",
  ui_story_5033_50330702_51_dialog_content = "Why are you telling this story as though you saw it for yourself? Were you there when it happened?",
  ui_story_5033_50330702_52_dialog_content = "Wait... don't tell me you're actually older than him?!",
  ui_story_5033_50330702_53_dialog_content = "Are you nuts? Yeah, I was there, but I was only five years old.",
  ui_story_5033_50330702_54_dialog_content = "So what was the point of telling that story?",
  ui_story_5033_50330702_55_dialog_content = "To show you how close me and Nekoyashiki are! Duh!",
  ui_story_5033_50330702_56_dialog_content = "We're bros to the bitter end! Why would we need to be all stuffy and formal with each other?",
  ui_story_5033_50330702_57_dialog_content = "S-Sure... I had no idea Nekoyashiki went through something like that. I guess that explains why he seems to be on such good terms with Raven's Blood.",
  ui_story_5033_50330702_58_dialog_content = "In a way, Nekoyashiki's a lot like you guys: another child taken in and protected by Raven's Blood.",
  ui_story_5033_50330702_59_dialog_content = "Heehee... exactly. I heard Nekoyashiki was just a little boy himself when he first came to the church.",
  ui_story_5033_50330702_60_dialog_content = "Pollux said that even though his face was all swollen and bloody at the time, his eyes were full of pride.",
  ui_story_5033_50330702_61_dialog_content = "Once Nekoyashiki's wounds were all better, he left without another word.",
  ui_story_5033_50330702_62_dialog_content = "Now, whenever he comes by, he always brings us lots of food and other essentials.",
  ui_story_5033_50330702_63_dialog_content = "Heh, and he's our dependable candy dealer!",
  ui_story_5033_50330702_64_dialog_content = "No matter what happens, he always makes sure to bring us lots of candy!",
  ui_story_5033_50330702_65_dialog_content = "Alright kid, I get it... You just want your candy, don't you? Here, take it.",
  ui_story_5033_50330702_66_dialog_content = "Sweet!",
  ui_story_5033_50330702_67_dialog_content = "Hey hold up... You can have your candy, but you've gotta tell me more about Casta and Pollux?",
  ui_story_5033_50330702_68_dialog_content = "Since we'll be working together, I'd like to know a little more about them.",
  ui_story_5033_50330702_69_dialog_content = "Sure, no problem! Latan can tell you anything you want to know!",
  ui_story_5033_50330702_70_dialog_content = "Hmm, I guess I'll start with the mysterious legend about Pollux...",
  ui_story_5033_50330702_71_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5033_50330702_72_dialog_content = "Was that a gun just now?! It came from outside...",
  ui_story_5033_50330702_73_dialog_content = "If you're unable to provide me with sufficient evidence to prove your innocence... Then I have no choice but to name you the prime suspect.",
  ui_story_5033_50330702_74_dialog_content = "Put down the blade, or I'll make you eat bullets!",
  ui_story_5033_50330702_75_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5033_50330702_76_dialog_content = "Why are you telling me to drop my weapon when you're already shooting at me?!",
  ui_story_5033_50330702_77_dialog_content = "That was a warning shot! Let me repeat myself: drop your weapon.",
  ui_story_5033_50330702_78_dialog_content = "How could you accuse Pollux of being the killer?!",
  ui_story_5033_50330702_79_dialog_content = "Sister Matilda meant the world to us. How dare you even imply that we could kill her!",
  ui_story_5033_50330702_80_dialog_content = "I'm only saying that it's a possibility. After all, everything I've heard so far is your own account. I have no way of knowing the truth behind your relationship with Sister Matilda.",
  ui_story_5033_50330702_81_dialog_content = "Apologies. It may be difficult to accept, but from a rational standpoint, I have no choice but to treat you as a suspect for the time being.",
  ui_story_5033_50330702_82_dialog_content = "The only way to clear your name is to provide me with sufficient evidence of your innocence.",
  ui_story_5033_50330702_83_dialog_content = "What the heck is going on here?! Why are you guys fighting?!",
  ui_story_5033_50330702_84_dialog_content = "PlayerName, Pollux just admitted to being able to use the same assassination technique as the one used by the serial killer.",
  ui_story_5033_50330702_85_dialog_content = "What?!",
  ui_story_5033_50330702_86_dialog_content = "No... It can't be! Pollux would never kill anyone!",
  ui_story_5033_50330702_87_dialog_content = "Enough, all of you!",
  ui_story_5033_50330702_88_dialog_content = "None of you should be drawing your weapons in front of children.",
  ui_story_5033_50330702_89_dialog_content = "Pollux... Are they going to take you away?",
  ui_story_5033_50330702_90_dialog_content = "I-I won't let them take you! I'll protect you!",
  ui_story_5033_50330801_1_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5033_50330801_2_dialog_content = "<color=#e8d9bb>In a Euphorian bar...</color>",
  ui_story_5033_50330801_3_dialog_content = "Did ya hear? Raven's Blood is getting all buddy buddy with a couple o' Umbraton jerks.",
  ui_story_5033_50330801_4_dialog_content = "Wonder what they're up to?",
  ui_story_5033_50330801_5_dialog_content = "Nothing good, I bet. I hear Umbraton's tryin' to sink its stinkin' claws in Euphoria next.",
  ui_story_5033_50330801_6_dialog_content = "Umbraton already uses Euphoria as its own personal dump. They toss all their trash out here.",
  ui_story_5033_50330801_7_dialog_content = "Is that not enough for them?",
  ui_story_5033_50330801_8_dialog_content = "Now they want to take the land from under our feet...",
  ui_story_5033_50330801_9_dialog_content = "The gambling dens and arms factories that were too afraid to do business in Umbraton came here instead.",
  ui_story_5033_50330801_10_dialog_content = "Won't it just be more of the same, then?",
  ui_story_5033_50330801_11_dialog_content = "Like hell. At least before, those businesses belonged to Euphoria.",
  ui_story_5033_50330801_12_dialog_content = "Now, Umbraton wants full control over everything.",
  ui_story_5033_50330801_13_dialog_content = "Well... I say they belonged to Euphoria, but really, they belonged to the \"Boss.\"",
  ui_story_5033_50330801_14_dialog_content = "Our liberation wasn't easy to earn in Euphoria, and I refuse to live under anyone's control ever again like the old days...",
  ui_story_5033_50330801_15_dialog_content = "We may be broke, but at least we don't live in fear for our lives anymore.",
  ui_story_5033_50330801_16_dialog_content = "That's right! Euphoria belongs to each and every gang here! Those are the rules.",
  ui_story_5033_50330801_17_dialog_content = "Make way for our chief!",
  ui_story_5033_50330801_18_dialog_content = "Ah, my back...",
  ui_story_5033_50330801_19_dialog_content = "I heard Raven's Blood beat the hell out of you guys. That true?",
  ui_story_5033_50330801_20_dialog_content = "What kind of stupid question is that?! Just look at us!!",
  ui_story_5033_50330801_21_dialog_content = "They went to the extent of picking a fight with us for those Umbraton creeps. I wonder why?",
  ui_story_5033_50330801_22_dialog_content = "Who knows what kind of schemes they're plotting with those two outsiders...",
  ui_story_5033_50330801_23_dialog_content = "I can answer that. My boys just brought me some interesting info.",
  ui_story_5033_50330801_24_dialog_content = "Umbraton sent those two here on a murder investigation. Apparently, the killer is from Euphoria, so that's what they're here for.",
  ui_story_5033_50330801_25_dialog_content = "My guess is that Raven's Blood is just using this as a chance to suck up to our potentially-new masters.",
  ui_story_5033_50330801_26_dialog_content = "Why would anyone ask Raven's Blood to help with a criminal investigation though?",
  ui_story_5033_50330801_27_dialog_content = "Besides, this whole \"murder investigation\" could just be a lousy excuse for them to show up and make trouble.",
  ui_story_5033_50330801_28_dialog_content = "Say something, will you Gustav? You know just about everything that goes down in Euphoria!",
  ui_story_5033_50330801_29_dialog_content = "What d'you wanna hear me say?",
  ui_story_5033_50330801_30_dialog_content = "What exactly should we do about all this?",
  ui_story_5033_50330801_31_dialog_content = "Saying the word \"exactly\" doesn't necessarily make your question any less vague.",
  ui_story_5033_50330801_32_dialog_content = "Are you asking what your gang should do? Or all of Euphoria?",
  ui_story_5033_50330801_33_dialog_content = "Both, obviously!!!",
  ui_story_5033_50330801_34_dialog_content = "Of course my gang's my top priority, but I'm a Euphorian too.",
  ui_story_5033_50330801_35_dialog_content = "In Euphoria, the only thing that matters is a gang's power.",
  ui_story_5033_50330801_36_dialog_content = "If Raven's Blood could beat all of your men down with just two people, I'm afraid the others already...",
  ui_story_5033_50330801_37_dialog_content = "I need to get to the bottom of this!",
  ui_story_5033_50330801_38_dialog_content = "We weren't grouped together at the time, and none of us had our weapons... Not to mention there were a bunch of Eclipsites added to the mix! That's the only way they were able to win.",
  ui_story_5033_50330801_39_dialog_content = "We'll proceed in accordance with Euphoria's rules.",
  ui_story_5033_50330801_40_dialog_content = "If you and your gang want to earn your reputation back, you need to challenge them to a formal gang fight and win.",
  ui_story_5033_50330801_41_dialog_content = "But if you're too scared...",
  ui_story_5033_50330801_42_dialog_content = "I-I ain't afraid to fight... Just wait until my wounds are healed, and I'll go knock those ravens right out of their tree!",
  ui_story_5033_50330801_43_dialog_content = "No, Boss. We shouldn't have to do anything ourselves.",
  ui_story_5033_50330801_44_dialog_content = "After all, Raven's Blood were the ones who brought those Umbraton outsiders into Euphoria first and caused trouble. They're the ones who broke the rules.",
  ui_story_5033_50330801_45_dialog_content = "That's right, I always knew those Raven's Blood girls were no good.",
  ui_story_5033_50330801_46_dialog_content = "They even screwed with our gang's business a while ago.",
  ui_story_5033_50330801_47_dialog_content = "They're always skulking around their precious church day and night, not letting anyone go near it.",
  ui_story_5033_50330801_48_dialog_content = "Well, duh, that's their turf. Of course, they're not gonna let you just waltz in.",
  ui_story_5033_50330801_49_dialog_content = "A-Anyways... they just rub me the wrong way!",
  ui_story_5033_50330801_50_dialog_content = "Damn right!",
  ui_story_5033_50330801_51_dialog_content = "Gustav, go and tell the other gangs in Euphoria that it's finally time to band together and take out the Raven's Blood, once and for all!",
  ui_story_5033_50330801_52_dialog_content = "Alright, now just calm down, all of you.",
  ui_story_5033_50330801_53_dialog_content = "I know you're all convinced that the only way to save Euphoria is by getting rid of Raven's Blood.",
  ui_story_5033_50330801_54_dialog_content = "But you shouldn't just charge in recklessly.",
  ui_story_5033_50330801_55_dialog_content = "Or have you already forgotten that Raven's Blood has made some new friends? Attacking them now might provoke Umbraton into retaliating.",
  ui_story_5033_50330801_56_dialog_content = "So what?! Euphoria ain't afraid of Umbraton!!",
  ui_story_5033_50330801_57_dialog_content = "It's not about whether you're afraid or not.",
  ui_story_5033_50330801_58_dialog_content = "The fact is, we still don't know exactly what Umbraton is plotting. I say we figure out what they're up to before making our move.",
  ui_story_5033_50331001_1_dialog_content = "There's no need to worry, children. We just had a little misunderstanding, that's all.",
  ui_story_5033_50331001_2_dialog_content = "Put your gun down, Casta. Don't ever fire it in front of the kids again.",
  ui_story_5033_50331001_3_dialog_content = "Sorry, Pollux... I wasn't thinking straight. I didn't think the kids would come running out.",
  ui_story_5033_50331001_4_dialog_content = "Corax, I don't think the serial killer could be someone who is as loved and trusted by these kids as they are.",
  ui_story_5033_50331001_5_dialog_content = "I've already put my knives away... I will let you speak. I'm sorry for jumping the gun.",
  ui_story_5033_50331001_6_dialog_content = "I-Is everything really okay now?",
  ui_story_5033_50331001_7_dialog_content = "Yes, everything's fine now. Now everyone get back in the church before you catch a cold.",
  ui_story_5033_50331001_8_dialog_content = "That's right, it looks like it's going to rain soon... Why don't you head inside first, kids?",
  ui_story_5033_50331001_9_dialog_content = "Latan, bring them all back inside.",
  ui_story_5033_50331001_10_dialog_content = "Okay...",
  ui_story_5033_50331001_11_dialog_content = "Well, I'm all ears. You can begin by explaining why you're capable of using the same high-level assassination technique as the killer.",
  ui_story_5033_50331001_12_dialog_content = "It's true that I'm capable of using that technique, but nowhere near the degree to which you're describing it.",
  ui_story_5033_50331001_13_dialog_content = "In addition, this technique requires the use of a very special type of dagger.",
  ui_story_5033_50331001_14_dialog_content = "I'd already vowed 14 years ago never to use it again.",
  ui_story_5033_50331001_15_dialog_content = "Nekoyashiki and I can both attest to that.",
  ui_story_5033_50331001_16_dialog_content = "Sorry, but your testimonies don't carry weight.",
  ui_story_5033_50331001_17_dialog_content = "I need more if you want me to trust you, Pollux.",
  ui_story_5033_50331001_18_dialog_content = "I can only offer you everything that I know... Whether or not you trust me is your decision.",
  ui_story_5033_50331001_19_dialog_content = "Then tell me, how did you manage to learn this kind of assassination technique?",
  ui_story_5033_50331001_20_dialog_content = "I learned it from Euphoria's former owner. Everyone called him <color=#FFB400>Boss</color>.",
  ui_story_5033_50331001_21_dialog_content = "His <color=#FFB400>organization</color> once held control over all residents and businesses in Euphoria.",
  ui_story_5033_50331001_22_dialog_content = "Back then, everyone lived in fear of the organization's Grim Reaper.",
  ui_story_5033_50331001_23_dialog_content = "I belonged to that organization a long time ago, where I was forced to learn the Grim Reaper's killing technique as well.",
  ui_story_5033_50331001_24_dialog_content = "Who exactly was this \"Boss\" character?",
  ui_story_5033_50331001_25_dialog_content = "Whenever we were in his presence, he always sat in a blood-red chair with his back turned towards us.",
  ui_story_5033_50331001_26_dialog_content = "No one knew his name or even what he looked like.",
  ui_story_5033_50331001_27_dialog_content = "Why would you join an organization like that?",
  ui_story_5033_50331001_28_dialog_content = "When a person is struggling to survive, they don't always think about the consequences of their decisions.",
  ui_story_5033_50331001_29_dialog_content = "So, when someone told me I could have my own bed and wouldn't have to worry about food or clothing ever again...",
  ui_story_5033_50331001_30_dialog_content = "I naturally accepted the offer.",
  ui_story_5033_50331001_31_dialog_content = "It wasn't until later that I found out that he was the \"Boss\" everyone talked about.",
  ui_story_5033_50331001_32_dialog_content = "Then it's safe to assume that the serial killer was part of this organization, just like you, correct?",
  ui_story_5033_50331001_33_dialog_content = "But the organization was completely wiped out ten years ago.",
  ui_story_5033_50331001_34_dialog_content = "I thought I was the only survivor.",
  ui_story_5033_50331001_35_dialog_content = "It's possible that there were more survivors, except you were unaware of them.",
  ui_story_5033_50331001_36_dialog_content = "Now that you've looked through these autopsy reports, does anyone in particular come to mind?",
  ui_story_5033_50331001_37_dialog_content = "There is one person...",
  ui_story_5033_50331001_38_dialog_content = "She would be the only one skilled enough to perform these assassinations. But that person is dead.",
  ui_story_5033_50331001_39_dialog_content = "How are you so sure?",
  ui_story_5033_50331001_40_dialog_content = "Because I was the one who killed her... My best friend.",
  ui_story_5033_50331001_41_dialog_content = "<color=#e8d9bb>14 years ago...</color>",
  ui_story_5033_50331001_42_dialog_content = "Is this... My own bed?",
  ui_story_5033_50331001_43_dialog_content = "Uh...",
  ui_story_5033_50331001_44_dialog_content = "Ahh! Wh-Who are you?! What are you doing, hiding over there?!",
  ui_story_5033_50331001_45_dialog_content = "P-Please don't get the wrong idea! I didn't mean to scare you by being so quiet!",
  ui_story_5033_50331001_46_dialog_content = "It's just... You were stroking your pillow just now, and it was too cute to interrupt...",
  ui_story_5033_50331001_47_dialog_content = "Are you... making fun of me?!",
  ui_story_5033_50331001_48_dialog_content = "... Never mind. Laugh if you want, I don't care.",
  ui_story_5033_50331001_49_dialog_content = "I've only ever seen pillows in shop windows before. They're so soft to touch...",
  ui_story_5033_50331001_50_dialog_content = "Looks like you're my new roommate.",
  ui_story_5033_50331001_51_dialog_content = "My back kinda hurts from standing around so long. Mind if we sit on your bed and chat?",
  ui_story_5033_50331001_52_dialog_content = "Y-Yeah, of course! Here, make yourself comfortable!",
  ui_story_5033_50331001_53_dialog_content = "My name's Antares. What's yours?",
  ui_story_5033_50331001_54_dialog_content = "I... Don't really have my own name. I've been using the name a nun gave me when she found me roaming around Euphoria.",
  ui_story_5033_50331001_55_dialog_content = "What would you be doing in a place like this? You know where we are, don't you?",
  ui_story_5033_50331001_56_dialog_content = "W-Well, someone told me I might get chosen if I signed up for this.",
  ui_story_5033_50331001_57_dialog_content = "And if I did get chosen, I would never have to worry about food or clothes ever again. I would even have my own bed!",
  ui_story_5033_50331001_58_dialog_content = "So I signed up, got selected, and then I met you!",
  ui_story_5033_50331001_59_dialog_content = "So you really have no idea what they do around here, huh...",
  ui_story_5033_50331001_60_dialog_content = "I guess not... What's the matter, Antares? Your hands are so cold.",
  ui_story_5033_50331001_61_dialog_content = "I'll go close the window!",
  ui_story_5033_50331001_62_dialog_content = "I-I'm fine...",
  ui_story_5033_50331001_63_dialog_content = "Okay, but if you're feeling cold, just let me know.",
  ui_story_5033_50331001_64_dialog_content = "So have you been here a long time now? What kind of place is this, anyway?",
  ui_story_5033_50331001_65_dialog_content = "Yeah, I've been living in this room for as long as I can remember. This place...",
  ui_story_5033_50331001_66_dialog_content = "is a private, underground training facility for Euphorian mercenaries.",
  ui_story_5033_50331001_67_dialog_content = "Pollux, I think we need to have a serious talk right now.",
  ui_story_5033_50331001_68_dialog_content = "Uh... I-I know what you're going to say, Antares! I promise I'll pay more attention next time. Really!",
  ui_story_5033_50331001_69_dialog_content = "You say that every time... When are you actually going to keep your promise?!",
  ui_story_5033_50331001_70_dialog_content = "Every time I come back from a mission, you have a bunch of new wounds on your body before your old ones have even finished healing...",
  ui_story_5033_50331001_71_dialog_content = "Do you have any idea how much it hurts to see you like this?",
  ui_story_5033_50331001_72_dialog_content = "My feelings must not matter to you at all.",
  ui_story_5033_50331001_73_dialog_content = "I'm sorry, Antares... I just don't know what's wrong with me.",
  ui_story_5033_50331001_74_dialog_content = "When I first got here, you were already going out on missions. I knew there was a huge gap between our skills.",
  ui_story_5033_50331001_75_dialog_content = "So I studied as hard as I could, day and night. I even forced myself to spar with mercenaries who were far stronger and higher-ranked than me.",
  ui_story_5033_50331001_76_dialog_content = "But to them, I'm nowhere near as good as you. Even the recruits who came a year or two after me show more promise.",
  ui_story_5033_50331001_77_dialog_content = "I want to be a strong mercenary like you, Antares!",
  ui_story_5033_50331001_78_dialog_content = "It's not like that, Pollux. Listen...",
  ui_story_5033_50331001_79_dialog_content = "Everyone knows how good your grades are. They even call us the Gemini twins, don't they?",
  ui_story_5033_50331001_80_dialog_content = "You're already amazing, Pollux. There's no need to push yourself so hard...",
  ui_story_5033_50331001_81_dialog_content = "Then why am I still stuck here, while you and the others go out on missions?",
  ui_story_5033_50331001_82_dialog_content = "I'm sorry, Antares... I know I'm being stubborn and that you're just looking out for me.",
  ui_story_5033_50331001_83_dialog_content = "You don't need to apologize to me, Pollux. I'm not the one you're hurting... It's yourself.",
  ui_story_5033_50331001_84_dialog_content = "If I could do things all over again, I would choose my own life.",
  ui_story_5033_50331001_85_dialog_content = "A life without constant guilt, without constant nightmares plaguing me every night.",
  ui_story_5033_50331001_86_dialog_content = "A life... Without \"missions.\"",
  ui_story_5033_50331001_87_dialog_content = "But Antares, I really wanna go out on one of those missions.",
  ui_story_5033_50331001_88_dialog_content = "I want to fight by your side, so we can have each other's backs all the time.",
  ui_story_5033_50331001_89_dialog_content = "When at last, I was told I could finally go out on a mission...",
  ui_story_5033_50331001_90_dialog_content = "What's with all the secrecy, Pollux?",
  ui_story_5033_50331001_91_dialog_content = "Hey, close your eyes! No peeking, you hear? Shut them!",
  ui_story_5033_50331001_92_dialog_content = "Okay, okay! See? They're closed.",
  ui_story_5033_50331001_93_dialog_content = "Alright! You can open your eyes now!",
  ui_story_5033_50331001_94_dialog_content = "Is this a <color=#FFB400>brooch</color>... For me?",
  ui_story_5033_50331001_94X1_dialog_content = "Yeah, the shop told me it's a hydrangea, and I think it totally fits you.",
  ui_story_5033_50331001_95_dialog_content = "Hehe, I only get a small stipend right now, so this is all I can afford.",
  ui_story_5033_50331001_96_dialog_content = "But once I finish my mission and collect my pay, I'll get you something even nicer! Something I'm sure you'll love!",
  ui_story_5033_50331001_97_dialog_content = "M-Mission...?",
  ui_story_5033_50331001_98_dialog_content = "Yeah! I met Boss a few days ago, and he told me he would have a mission for me really soon!",
  ui_story_5033_50331001_99_dialog_content = "So I got this for you to celebrate my wish coming true, and to thank you for always being there for me.",
  ui_story_5033_50331001_100_dialog_content = "Now, what should I get you next...?",
  ui_story_5033_50331001_101_dialog_content = "...",
  ui_story_5033_50331001_102_dialog_content = "What's the matter, Antares? Don't you like it?",
  ui_story_5033_50331001_103_dialog_content = "No, that's not it. I love how pretty this purple flower looks.",
  ui_story_5033_50331001_104_dialog_content = "Pollux...",
  ui_story_5033_50331001_105_dialog_content = "Yeah?",
  ui_story_5033_50331001_106_dialog_content = "Thank you for being my friend. The time we've spent together has been the happiest time of my life.",
  ui_story_5033_50331001_107_dialog_content = "You wouldn't be Antares if you didn't come up with something cheesy.",
  ui_story_5033_50331001_108_dialog_content = "But same here.",
  ui_story_5033_50331001_109_dialog_content = "Thank you for being my friend, Antares.",
  ui_story_5033_50331001_110_dialog_content = "I could never have expected the mission to turn out like that.",
  ui_story_5033_50331001_111_dialog_content = "Me, in an arena, facing my best friend...",
  ui_story_5033_50331001_112_dialog_content = "W-Why...",
  ui_story_5033_50331001_113_dialog_content = "Why is my opponent you...?",
  ui_story_5033_50331001_114_dialog_content = "One is a killing machine trained with a hands-on approach in the field.",
  ui_story_5033_50331001_115_dialog_content = "The other is a promising up-and-coming talent carefully honed right here in our training camp.",
  ui_story_5033_50331001_116_dialog_content = "This dynamite duo is known as the Gemini twins! But today, only one of them will be walking out of the ring.",
  ui_story_5033_50331001_117_dialog_content = "Has Euphoria ever witnessed—or will Euphoria ever witness—as nail-biting and exciting a match as this?",
  ui_story_5033_50331001_118_dialog_content = "Antares, you...",
  ui_story_5033_50331001_119_dialog_content = "Raise your dagger, and come at me.",
  ui_story_5033_50331001_120_dialog_content = "Haven't you been looking forward to this mission?",
  ui_story_5033_50331001_121_dialog_content = "I know you've been training hard for this.",
  ui_story_5033_50331001_122_dialog_content = "But I...",
  ui_story_5033_50331001_123_dialog_content = "What are you waiting for?",
  ui_story_5033_50331001_124_dialog_content = "If this was a real fight, you'd be dead a dozen times over by now.",
  ui_story_5033_50331001_125_dialog_content = "I just can't raise my hand against you...",
  ui_story_5033_50331001_126_dialog_content = "What if I told you that the only reason you're here in this arena right now is because of me?",
  ui_story_5033_50331001_127_dialog_content = "No... No, that can't be true!",
  ui_story_5033_50331001_128_dialog_content = "Why make us fight each other? Don't you think this is a little strange?",
  ui_story_5033_50331001_129_dialog_content = "Strange? There are things in Euphoria you can't even begin to imagine.",
  ui_story_5033_50331001_130_dialog_content = "I tried... persuading you many times in the past.",
  ui_story_5033_50331001_131_dialog_content = "Just so you're aware, I won't make allowances for you.",
  ui_story_5033_50331001_132_dialog_content = "You'd really lift a hand against me...?",
  ui_story_5033_50331001_133_dialog_content = "Correct. I was raised in the chaos of battle, and the first thing I learned was—",
  ui_story_5033_50331001_134_dialog_content = "Show no mercy to anyone.",
  ui_story_5033_50331001_135_dialog_content = "No... <size=45>I don't want to fight you, Antares!</size>",
  ui_story_5033_50331001_136_dialog_content = "<size=45>Either defend yourself, or DIE!!</size>",
  ui_story_5033_50331001_137_dialog_content = "When I came to...",
  ui_story_5033_50331001_138_dialog_content = "It was too late.",
  ui_story_5033_50331001_139_dialog_content = "Urgh...!",
  ui_story_5033_50331001_140_dialog_content = "I... I... What have I done?",
  ui_story_5033_50331001_141_dialog_content = "Antares... Why didn't you move?!",
  ui_story_5033_50331001_142_dialog_content = "<anim type=Shake>Thank... Thank you... Pollux...</anim>",
  ui_story_5033_50331001_143_dialog_content = "Antares! NO! Don't leave me... Sorry... I'm so sorry...",
  ui_story_5033_50331001_144_dialog_content = "Why... Why didn't you just avoid my attack?",
  ui_story_5033_50331001_145_dialog_content = "<anim type=Shake>This way I... can be free...</anim>",
  ui_story_5033_50331001_146_dialog_content = "<anim type=Shake>Finally free...</anim>",
  ui_story_5033_50331001_147_dialog_content = "It was I who killed Antares... I killed my only friend in the whole world with my own hands.",
  ui_story_5033_50331001_148_dialog_content = "I didn't understand until the dagger in my hand had already penetrated Antares' chest.",
  ui_story_5033_50331001_149_dialog_content = "How terrible that for which I once yearned truly was.",
  ui_story_5033_50331001_150_dialog_content = "This is why you no longer wield daggers...",
  ui_story_5033_50331001_151_dialog_content = "Yes. The day's events keep replaying in my head, so real it's like I'm actually back in the arena.",
  ui_story_5033_50331001_152_dialog_content = "I lost consciousness after the fight and burned with a high fever for over a week.",
  ui_story_5033_50331001_153_dialog_content = "When I finally woke up, I was the only one left in the room.",
  ui_story_5033_50331001_154_dialog_content = "Antares' clothes, notebook... All trace of her had disappeared completely from within those four square walls.",
  ui_story_5033_50331001_155_dialog_content = "It was so clean, so sterile, as if she'd never even existed in this world.",
  ui_story_5033_50331001_156_dialog_content = "Soon after, I too left the room. In the span of less than a month, both its inhabitants were gone.",
  ui_story_5033_50331001_157_dialog_content = "Did you leave that organization?",
  ui_story_5033_50331001_158_dialog_content = "Well, it wasn't so much jumping ship as being pushed.",
  ui_story_5033_50331001_159_dialog_content = "After that fight, I was traumatized and found it hard even to hold a dagger.",
  ui_story_5033_50331001_160_dialog_content = "For a mercenary, losing combat ability means losing all value.",
  ui_story_5033_50331001_161_dialog_content = "So it's only natural I was kicked out of the group, and held captive in the basement.",
  ui_story_5033_50331001_162_dialog_content = "Right up until the Eclipsites came and razed the place to the ground.",
  ui_story_5033_50331001_163_dialog_content = "Do you have any other info you can provide me?",
  ui_story_5033_50331001_164_dialog_content = "No, I'm sorry. That's all I know...",
  ui_story_5033_50331001_165_dialog_content = "I promise you, though—I'll help you get to the bottom of this.",
  ui_story_5033_50331001_166_dialog_content = "<color=#e8d9bb>*Footsteps*</color>",
  ui_story_5033_50331001_167_dialog_content = "Hold up! I sense a lot of people heading this way!",
  ui_story_5033_50331001_168_dialog_content = "Who?",
  ui_story_5033_50331001_169_dialog_content = "I don't know, but I think they're trying to... surround the church?!",
  ui_story_5033_50331101_1_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5033_50331101_2_dialog_content = "Get a move on, guys! Hurry up!",
  ui_story_5033_50331101_3_dialog_content = "Get your weapons ready, prepare to engage. Raven's Blood aren't your average ruffians.",
  ui_story_5033_50331101_4_dialog_content = "Ready!",
  ui_story_5033_50331101_5_dialog_content = "Keep on the down-low once we get there. Wait for my signal, got it?",
  ui_story_5033_50331101_6_dialog_content = "Roger!",
  ui_story_5033_50331101_7_dialog_content = "Have all our men arrived?",
  ui_story_5033_50331101_8_dialog_content = "Everyone is here, boss! Raven's Blood is done for this time!",
  ui_story_5033_50331101_9_dialog_content = "Haha, excellent! I've waited a long time for this day.",
  ui_story_5033_50331101_10_dialog_content = "Hey, hang on a minute... Didn't Gustav tell us not to be rash?",
  ui_story_5033_50331101_11_dialog_content = "<size=45>What do you know?!</size>",
  ui_story_5033_50331101_12_dialog_content = "This is a perfect opportunity to find proof of collusion between Raven's Blood and Umbraton.",
  ui_story_5033_50331101_13_dialog_content = "What'll we do if we let them get away, hmm?",
  ui_story_5033_50331101_14_dialog_content = "No, I've gotta report this to Gustav.",
  ui_story_5033_50331101_15_dialog_content = "When did you become his lapdog?",
  ui_story_5033_50331101_16_dialog_content = "Fine then, get out of here. Don't get in my way!",
  ui_story_5033_50331101_17_dialog_content = "Whoever they are, they're definitely heading this way.",
  ui_story_5033_50331101_18_dialog_content = "Who dares look for trouble with Raven's Blood?",
  ui_story_5033_50331101_19_dialog_content = "I'm afraid it's not so simple this time.",
  ui_story_5033_50331101_20_dialog_content = "No one would have so rashly approached the church before.",
  ui_story_5033_50331101_21_dialog_content = "It's a large group this time. I'm worried they've banded together to stir things up for us.",
  ui_story_5033_50331101_22_dialog_content = "Why now?",
  ui_story_5033_50331101_23_dialog_content = "Seems they really have a thing against Umbraton folks coming to Euphoria.",
  ui_story_5033_50331101_24_dialog_content = "This is because we came here?",
  ui_story_5033_50331101_25_dialog_content = "I'm sorry, Corax.",
  ui_story_5033_50331101_26_dialog_content = "Maybe our way of doing things irritated the local gangs.",
  ui_story_5033_50331101_27_dialog_content = "I'm afraid we'll need to take care of this local gang quarrel first.",
  ui_story_5033_50331101_28_dialog_content = "They're just cowards, bullying the weak but fearing the strong. Do they really think they can beat us even by banding together?",
  ui_story_5033_50331101_29_dialog_content = "Let them come, no matter how many!",
  ui_story_5033_50331101_30_dialog_content = "Keep calm. We don't benefit from making matters worse.",
  ui_story_5033_50331101_31_dialog_content = "Casta, Corax—take the children to Nekoyashiki for shelter.",
  ui_story_5033_50331101_32_dialog_content = "They're after Raven's Blood and the church. I'll try to stall them here.",
  ui_story_5033_50331101_33_dialog_content = "Okay. I'll keep the children safe.",
  ui_story_5033_50331101_34_dialog_content = "What about you? No one can handle that many alone, not even you.",
  ui_story_5033_50331101_35_dialog_content = "I'll do my best to buy you time. Now go, take the children and get out of here.",
  ui_story_5033_50331101_36_dialog_content = "... Understood. You'd better hold on till I get back!",
  ui_story_5033_50331101_37_dialog_content = "I'll help. A few of the kids are injured, so we need to take care when moving them.",
  ui_story_5033_50331101_38_dialog_content = "PlayerName.",
  ui_story_5033_50331101_39_dialog_content = "Huh? I'm here!",
  ui_story_5033_50331101_40_dialog_content = "While I may not know much about you, I reckon you can find a safe route to get everyone out of here.",
  ui_story_5033_50331101_41_dialog_content = "Can I leave it to you to lead the way?",
  ui_story_5033_50331101_42_dialog_content = "No problem!",
  ui_story_5033_50331101_43_dialog_content = "Nekoyashiki is usually at his cabin. Do you remember where it is?",
  ui_story_5033_50331101_44_option_content = "Yes",
  ui_story_5033_50331101_45_dialog_content = "Nekoyashiki lives in a cabin covered in scar-shaped graffiti.",
  ui_story_5033_50331101_46_dialog_content = "Cross the alley south of the church, go another couple of blocks, and then into a narrow alley.",
  ui_story_5033_50331101_47_dialog_content = "There should be around five or six turns...",
  ui_story_5033_50331101_48_dialog_content = "You'll need to make six turns.",
  ui_story_5033_50331101_49_dialog_content = "Alright, I've got it. I remember the way now.",
  ui_story_5033_50331101_50_dialog_content = "Okay. Ask Casta if you have any further questions. But I imagine she and Corax will need to handle the fighting.",
  ui_story_5033_50331101_51_dialog_content = "If necessary, you can also ask Latan. She may be young, but she's dependable.",
  ui_story_5033_50331101_52_option_content = "No",
  ui_story_5033_50331101_53_dialog_content = "It's that small cabin you've been to before. The one with the scar-shaped graffiti outside.",
  ui_story_5033_50331101_54_dialog_content = "When you leave, first cross the alley south of the church, then go another couple of blocks.",
  ui_story_5033_50331101_55_dialog_content = "If anyone is on the streets, go a little further and look for an alley with bear stickers along the wall.",
  ui_story_5033_50331101_56_dialog_content = "The kids stuck those there. They'll recognize them, as well as Casta.",
  ui_story_5033_50331101_57_dialog_content = "Casta and Corax will need to handle any fighting, so it'll be up to you to keep going with the children.",
  ui_story_5033_50331101_58_dialog_content = "When you get there, tell Nekoyashiki everything. He'll be able to take you somewhere safe. Have you got all that?",
  ui_story_5033_50331101_59_dialog_content = "Got it.",
  ui_story_5033_50331101_60_dialog_content = "Excellent. You're a good kid.",
  ui_story_5033_50331101_61_option_content = "I'm not a kid.",
  ui_story_5033_50331101_62_dialog_content = "I'll make sure to accomplish the task you've given me without a hitch.",
  ui_story_5033_50331101_63_dialog_content = "I can also help Casta and Corax fight, so no harm will come to the children. Don't worry.",
  ui_story_5033_50331101_64_dialog_content = "That's wonderful. I see my faith in you was not misplaced...",
  ui_story_5033_50331101_65_dialog_content = "You are much more mature than I thought. When the dust settles from all of this, I'd love to hear your story.",
  ui_story_5033_50331101_66_dialog_content = "Okay, let's do that.",
  ui_story_5033_50331101_67_option_content = "I'll be a good kid.",
  ui_story_5033_50331101_68_dialog_content = "Those are good kids too. I'm sure they'll cooperate.",
  ui_story_5033_50331101_69_dialog_content = "There's no need to worry. We'll come straight back, once we've got them somewhere safe.",
  ui_story_5033_50331101_70_dialog_content = "Alright. Hearing that puts me more at ease.",
  ui_story_5033_50331101_71_dialog_content = "You'd better hold on till we get back to help, Pollux!",
  ui_story_5033_50331101_72_dialog_content = "I know. I'll do my best. Thank you.",
  ui_story_5033_50331101_73_dialog_content = "Casta and the children are coming. You have to go.",
  ui_story_5033_50331101_74_dialog_content = "Pollux, Casta said we need to go somewhere safe. What about you? You're not coming with us?",
  ui_story_5033_50331101_75_dialog_content = "Pollux...! Pollux... Come with us!",
  ui_story_5033_50331101_76_dialog_content = "Everyone, stop bothering Pollux. We promised to follow the plan.",
  ui_story_5033_50331101_77_dialog_content = "But...",
  ui_story_5033_50331101_78_dialog_content = "Don't worry about me, kids.",
  ui_story_5033_50331101_79_dialog_content = "I need to stay here for a little bit, as there's something I need to take care of.",
  ui_story_5033_50331101_80_dialog_content = "You guys need to go somewhere safe now. Try to get far away from here.",
  ui_story_5033_50331101_81_dialog_content = "B-But there are loads of Eclipsites outside the church. If you don't come with us...",
  ui_story_5033_50331101_82_dialog_content = "Casta and Dr. Corax will look after you, don't worry.",
  ui_story_5033_50331101_83_dialog_content = "PlayerName and Nekoyashiki will be there too.",
  ui_story_5033_50331101_84_dialog_content = "When can we come back to the here?",
  ui_story_5033_50331101_85_dialog_content = "It's alright even if we can't. We'll find another shelter.",
  ui_story_5033_50331101_86_dialog_content = "The most important thing is that everybody is safe and happy together.",
  ui_story_5033_50331101_87_dialog_content = "But, but you... You'll still be with us, right?",
  ui_story_5033_50331101_88_dialog_content = "Yes, of course!",
  ui_story_5033_50331101_89_dialog_content = "I'll come to find you, just soon as I take care of this.",
  ui_story_5033_50331101_90_dialog_content = "Off you go now, kids.",
  ui_story_5033_50331202_1_dialog_content = "Get out here, Raven's Blood!",
  ui_story_5033_50331202_2_dialog_content = "Get out here and die!",
  ui_story_5033_50331202_3_dialog_content = "Don't think you can just walk all over Euphoria. Get out here NOW!",
  ui_story_5033_50331202_4_dialog_content = "Listen up, you lot in the church, especially those two from Umbraton!",
  ui_story_5033_50331202_5_dialog_content = "I don't care why you're here, but in Euphoria, you play by Euphoria's rules.",
  ui_story_5033_50331202_6_dialog_content = "By colluding with Raven's Blood, you've made an enemy of yourself to all of Euphoria.",
  ui_story_5033_50331202_7_dialog_content = "If there's anything you want to discuss, you can do it in the church.",
  ui_story_5033_50331202_8_dialog_content = "We'll welcome everybody, and I'm sure that you'll be satisfied with your reception, be it via gun or blade.",
  ui_story_5033_50331202_9_dialog_content = "Hey boss, that's Pollux's voice!",
  ui_story_5033_50331202_10_dialog_content = "What are they doing in there?!",
  ui_story_5033_50331202_11_dialog_content = "I... I don't know...",
  ui_story_5033_50331202_12_dialog_content = "What do we do now?",
  ui_story_5033_50331202_13_dialog_content = "How about... Boss, you go in first?",
  ui_story_5033_50331202_14_dialog_content = "Are you stupid, blockhead?!",
  ui_story_5033_50331202_15_dialog_content = "I definitely can't just go in there alone! It has to be a trap.",
  ui_story_5033_50331202_16_dialog_content = "Boss is right! If we're gonna go in, we should all rush in together.",
  ui_story_5033_50331202_17_dialog_content = "Rush into what, numbskull?! Call someone to bring the explosives!",
  ui_story_5033_50331202_18_dialog_content = "O-Oh right, of course.",
  ui_story_5033_50331202_19_dialog_content = "The others are all just waiting here. Have them surround the place so at the very least, no one's getting away.",
  ui_story_5033_50331202_20_dialog_content = "Good idea!",
  ui_story_5033_50331202_21_dialog_content = "How come there's still no news from Gustav? What's taking so long...",
  ui_story_5033_50331202_22_dialog_content = "Meow...",
  ui_story_5033_50331202_23_dialog_content = "That's the signal! Finally...",
  ui_story_5033_50331202_24_dialog_content = "Hey... You got it?",
  ui_story_5033_50331202_25_dialog_content = "Oh dearie, are you waiting for this little scrap of paper?",
  ui_story_5033_50331202_26_dialog_content = "Who... Who are you? How long have you been behind me?!",
  ui_story_5033_50331202_27_dialog_content = "Since you lot got here.",
  ui_story_5033_50331202_28_dialog_content = "A n-nun?! Crap...",
  ui_story_5033_50331202_29_dialog_content = "That's right. You can call me Sister Anne, or <color=#FFB400>Antares</color>.",
  ui_story_5033_50331202_30_dialog_content = "But then again... You won't have a chance to tell anyone.",
  ui_story_5033_50331202_31_dialog_content = "No! Please don't kill me... I-I just run errands... I don't know anything.",
  ui_story_5033_50331202_32_dialog_content = "I could consider sparing you, I suppose. But maybe you can tell me who Gustav is?",
  ui_story_5033_50331202_33_dialog_content = "I'm guessing... he must be the one who gave you this piece of paper.",
  ui_story_5033_50331202_34_dialog_content = "Well, this was unexpectedly easy.",
  ui_story_5033_50331202_35_dialog_content = "Tell me, is this some sort of trap to lure me in?",
  ui_story_5033_50331202_36_dialog_content = "W-What are you talking about...? I have no idea what you're saying!",
  ui_story_5033_50331202_37_dialog_content = "Or wait, no. Maybe the situation was so volatile that he had no time to cover his tracks...",
  ui_story_5033_50331202_38_dialog_content = "What are you talking about?! Are you some kinda lunatic?",
  ui_story_5033_50331202_39_dialog_content = "Don't play dumb with me! I knew you recognized me the very first second you saw me.",
  ui_story_5033_50331202_40_dialog_content = "And you also know what I'm here to do. Or rather, what I might be here to do.",
  ui_story_5033_50331202_41_dialog_content = "People do not lie, when staring death in the face.",
  ui_story_5033_50331202_42_dialog_content = "Urgh...",
  ui_story_5033_50331202_43_dialog_content = "Antares... I will tell you nothing.",
  ui_story_5033_50331202_44_dialog_content = "Oh, there's no need. Not anymore.",
  ui_story_5033_50331202_45_dialog_content = "<color=#e8d9bb>Whoosh—!</color>",
  ui_story_5033_50331202_46_dialog_content = "Urgh... You...",
  ui_story_5033_50331202_47_dialog_content = "So... This is how it feels... to be killed by the Grim Reaper...",
  ui_story_5033_50331202_48_dialog_content = "In return for you providing me with this clue, I will do my best to make sure you don't suffer unduly.",
  ui_story_5033_50331202_49_dialog_content = "You have my thanks.",
  ui_story_5033_50331202_50_dialog_content = "And now... Finally, I can go see Pollux.",
  ui_story_5033_50331202_51_dialog_content = "Boss! Hey, boss! We got the explosives!",
  ui_story_5033_50331202_52_dialog_content = "It may not be a lot, but it's more than enough to turn that church into glass.",
  ui_story_5033_50331202_53_dialog_content = "Great! Well done.",
  ui_story_5033_50331202_54_dialog_content = "Lay them out around the church.",
  ui_story_5033_50331202_55_dialog_content = "Be careful, especially of getting fired at from the church.",
  ui_story_5033_50331202_56_dialog_content = "No problem!",
  ui_story_5033_50331202_57_dialog_content = "Excuse me, pardon me, I need to get to the front.",
  ui_story_5033_50331202_58_dialog_content = "Where did the nun come from? Out of the way, unless you wanna die—",
  ui_story_5033_50331202_59_dialog_content = "<color=#e8d9bb>Whoosh—!</color>",
  ui_story_5033_50331202_60_dialog_content = "<size=45>Ahhhh!! Someone just got killed!!!</size>",
  ui_story_5033_50331202_61_dialog_content = "What?! What's going on back there?",
  ui_story_5033_50331202_62_dialog_content = "Don't worry, nothing happened... People die in gang wars, there's nothing extraordinary about it.",
  ui_story_5033_50331202_63_dialog_content = "Where did you come from?!",
  ui_story_5033_50331202_64_dialog_content = "<color=#e8d9bb>Whoosh—!</color>",
  ui_story_5033_50331202_65_dialog_content = "Argh—! My hand... My hand!",
  ui_story_5033_50331202_66_dialog_content = "Boss! This nun, she's got a knife...!",
  ui_story_5033_50331202_67_dialog_content = "I KNOW! She's the one who cut me! Go after her already, what are you doing?!",
  ui_story_5033_50331202_68_dialog_content = "I advise you not to use explosives to try and destroy the church, or you'll face heaven's wrath.",
  ui_story_5033_50331202_69_dialog_content = "<color=#e8d9bb>Whoosh—!</color>",
  ui_story_5033_50331202_70_dialog_content = "<color=#e8d9bb>Boom—!</color>",
  ui_story_5033_50331202_71_dialog_content = "Explosions? Quick, spread out!",
  ui_story_5033_50331202_72_dialog_content = "That nun sliced open the explosive package. She's crazy!",
  ui_story_5033_50331202_73_dialog_content = "Look! She's still alive... How'd she do it?",
  ui_story_5033_50331202_74_dialog_content = "If you could all be silent for a minute, please. I'm here because I've got business with the church. Once I'm finished, I'll leave everyone be.",
  ui_story_5033_50331202_75_dialog_content = "I'd advise against any rash actions before then.",
  ui_story_5033_50331202_76_dialog_content = "Unless you fancy a meeting with the <color=#FFB400>Grim Reaper</color>...",
  ui_story_5033_50331301_1_dialog_content = "W-What now... Should we listen to the nun?",
  ui_story_5033_50331301_2_dialog_content = "Didn't you see those people just get murdered?",
  ui_story_5033_50331301_3_dialog_content = "You can if you want... I'm in no rush.",
  ui_story_5033_50331301_4_dialog_content = "S-She mentioned the Reaper. Does that mean those legends are really true?",
  ui_story_5033_50331301_5_dialog_content = "Shh... If ithey are true, that's one name we must never mention.",
  ui_story_5033_50331301_6_dialog_content = "Thank you for your cooperation.",
  ui_story_5033_50331301_7_dialog_content = "<color=#e8d9bb>Inside the church</color>",
  ui_story_5033_50331301_8_dialog_content = "... What exactly is going on out there?",
  ui_story_5033_50331301_9_dialog_content = "<color=#e8d9bb>Da, da...</color>",
  ui_story_5033_50331301_10_dialog_content = "Hello...",
  ui_story_5033_50331301_11_dialog_content = "The perimeter is closely guarded... How did you get in here?",
  ui_story_5033_50331301_12_dialog_content = "I had a word with the people outside, and they agreed to let me through.",
  ui_story_5033_50331301_13_dialog_content = "I don't care who you are, or why you're here.",
  ui_story_5033_50331301_14_dialog_content = "But please, leave... There is no god of light here, Sister.",
  ui_story_5033_50331301_15_dialog_content = "... Do you not recognize me? Pollux.",
  ui_story_5033_50331301_16_dialog_content = "<size=45>You...!</size>",
  ui_story_5033_50331301_17_dialog_content = "It's been a long time.",
  ui_story_5033_50331301_18_dialog_content = "<color=#FFB400>Antares</color>, you're... No... How is this possible?",
  ui_story_5033_50331301_19_dialog_content = "I'm sorry, Pollux. This is the only way that I could meet you again.",
  ui_story_5033_50331301_20_dialog_content = "To be honest, I thought you would have forgotten me.",
  ui_story_5033_50331301_21_dialog_content = "How could I possibly forget?! I was the one responsible back then...",
  ui_story_5033_50331301_22_dialog_content = "Don't give me that guilty look, Pollux. I beg you.",
  ui_story_5033_50331301_23_dialog_content = "I kept playing it out in my head: what I should say to you if we ever met again, how I should face you.",
  ui_story_5033_50331301_24_dialog_content = "But now that you're here, standing in front of me, I can't even remember a single word.",
  ui_story_5033_50331301_25_dialog_content = "What are you trying to say...?",
  ui_story_5033_50331301_26_dialog_content = "Your eyes are still the same as they were all those years ago. They haven't changed.",
  ui_story_5033_50331301_27_dialog_content = "As bright as the stars.",
  ui_story_5033_50331301_28_dialog_content = "Anne... You're behind everything? But why?",
  ui_story_5033_50331301_29_dialog_content = "But how could this be? How did you survive?",
  ui_story_5033_50331301_30_dialog_content = "And why are you... dressed like a nun?",
  ui_story_5033_50331301_31_dialog_content = "Don't worry, Pollux, I'll tell you. I'll tell you everything.",
  ui_story_5033_50331301_32_dialog_content = "I'll give you the short version now... We don't have a lot of time.",
  ui_story_5033_50331301_33_dialog_content = "<color=#e8d9bb>14 years ago...</color>",
  ui_story_5033_50331301_34_dialog_content = "Yes, just here. Now to throw it in the river.",
  ui_story_5033_50331301_35_dialog_content = "Such a pity! As one of the Gemini, she just died like this.",
  ui_story_5033_50331301_36_dialog_content = "The boss didn't think that she would make that choice either...",
  ui_story_5033_50331301_37_dialog_content = "<color=#e8d9bb>Splash—</color>",
  ui_story_5033_50331301_38_dialog_content = "Oh, heavens! Look! In the river...",
  ui_story_5033_50331301_39_dialog_content = "Help me... There's a child here!",
  ui_story_5033_50331301_40_dialog_content = "Get the fire going, quickly! She's still alive! Someone call the doctor!",
  ui_story_5033_50331301_41_dialog_content = "Ow... Hurts...",
  ui_story_5033_50331301_42_dialog_content = "I'm... still alive?",
  ui_story_5033_50331301_43_dialog_content = "Who's that outside the door?",
  ui_story_5033_50331301_44_dialog_content = "It's simply monstrous. Who could possibly do this to a child?",
  ui_story_5033_50331301_45_dialog_content = "She sure is resilient to survive even an injury like that.",
  ui_story_5033_50331301_46_dialog_content = "There's more to this. Take her to the abbey in Umbraton. I'd rather not get into any more trouble...",
  ui_story_5033_50331301_47_dialog_content = "<color=#e8d9bb>Bang, bang, bang!</color>",
  ui_story_5033_50331301_48_dialog_content = "Here's today's paper, Anne.",
  ui_story_5033_50331301_49_dialog_content = "There's a letter as well... Though you don't have anyone called <color=#FFB400>Antares</color> here, do you?",
  ui_story_5033_50331301_50_dialog_content = "What?",
  ui_story_5033_50331301_51_dialog_content = "... No. No one here by that name.",
  ui_story_5033_50331301_52_dialog_content = "Perhaps it's the wrong name. Could you figure out who it's for?",
  ui_story_5033_50331301_53_dialog_content = "To Antares.",
  ui_story_5033_50331301_54_dialog_content = "I am a devout disciple of the god of light. I wish to repent on behalf of someone who committed an unforgivable sin.",
  ui_story_5033_50331301_55_dialog_content = "She faked her own death and deceived her family, all in the interest of gaining some false freedom.",
  ui_story_5033_50331301_56_dialog_content = "She takes advantage of friendships, letting those who love her bear life's burden on her behalf and sink into a sea of misery.",
  ui_story_5033_50331301_57_dialog_content = "She must repent until the next confession letter arrives.",
  ui_story_5033_50331301_58_dialog_content = "Who sent this...?",
  ui_story_5033_50331301_59_dialog_content = "You alright, Anne? You've gone pale.",
  ui_story_5033_50331301_60_dialog_content = "Let me keep this letter here for now.",
  ui_story_5033_50331301_61_dialog_content = "Maybe someone called Antares would... come to claim it.",
  ui_story_5033_50331301_62_dialog_content = "So for all these years, you've been living as a nun?",
  ui_story_5033_50331301_63_dialog_content = "That is correct.",
  ui_story_5033_50331301_64_dialog_content = "I have no idea how whoever sent the letter knew my real identity...",
  ui_story_5033_50331301_65_dialog_content = "But regardless, \"he\" had me firmly under his control. I dared not disobey any order.",
  ui_story_5033_50331301_66_dialog_content = "But you don't even fear death! How can anyone control you? Do ghosts have weaknesses, then?",
  ui_story_5033_50331301_67_dialog_content = "Yes... My only weakness was my only friend.",
  ui_story_5033_50331301_68_dialog_content = "You're saying it's because of me?",
  ui_story_5033_50331301_69_dialog_content = "Yes. He said that the incident almost destroyed you, but that Gemini must continue...",
  ui_story_5033_50331301_70_dialog_content = "\"Pollux is worthless if she can no longer wield a knife.\"",
  ui_story_5033_50331301_71_dialog_content = "If I don't fulfill my orders, you'll be...",
  ui_story_5033_50331301_72_dialog_content = "I always thought that the organization did not pursue my failure because the Eclipsites invaded, and they had no time to spare...",
  ui_story_5033_50331301_73_dialog_content = "But the organization will not let us go that easily.",
  ui_story_5033_50331301_74_dialog_content = "Even if all of Euphoria was destroyed, there would still be those in the organization who would continue to manipulate us.",
  ui_story_5033_50331301_75_dialog_content = "So you really did do all those things, Anne?",
  ui_story_5033_50331301_76_dialog_content = "I had no choice, Pollux.",
  ui_story_5033_50331301_77_dialog_content = "You not only survived that fight, but you even managed to get away from that place.",
  ui_story_5033_50331301_78_dialog_content = "I want to protect your freedom.",
  ui_story_5033_50331301_79_dialog_content = "Even though you haven't left Euphoria, you have someone to protect, to rely on, do you not?",
  ui_story_5033_50331301_80_dialog_content = "Are you talking about the children?",
  ui_story_5033_50331301_81_dialog_content = "And that young woman with the gun. She seems pretty dependable.",
  ui_story_5033_50331301_82_dialog_content = "With people like that on your side, you have nothing to fear.",
  ui_story_5033_50331301_83_dialog_content = "Whereas I'm nothing but a long-gone... vile undead.",
  ui_story_5033_50331301_84_dialog_content = "Did you kill Sister Matilda too?!",
  ui_story_5033_50331301_85_dialog_content = "...",
  ui_story_5033_50331301_86_dialog_content = "Answer me, Anne!",
  ui_story_5033_50331301_87_dialog_content = "Yes.",
  ui_story_5033_50331301_88_dialog_content = "Why?",
  ui_story_5033_50331301_89_dialog_content = "Killing her was just one order of many. I don't even know why the organization targeted her.",
  ui_story_5033_50331301_90_dialog_content = "I'm sorry, Pollux.",
  ui_story_5033_50331301_91_dialog_content = "You know how important she was to me.",
  ui_story_5033_50331301_92_dialog_content = "I had no choice...",
  ui_story_5033_50331301_93_dialog_content = "You came unarmed.",
  ui_story_5033_50331301_94_dialog_content = "What?",
  ui_story_5033_50331301_95_dialog_content = "Your weapon, Antares. You come before me, tell me all this, yet you're unarmed...",
  ui_story_5033_50331301_96_dialog_content = "Are you gambling I won't raise my hand against you?",
  ui_story_5033_50331301_97_dialog_content = "It feels like we've been here before... Although, Pollux, I AM armed.",
  ui_story_5033_50331301_98_dialog_content = "Because my final mission... is to <color=#FFB400>kill you</color>.",
  ui_story_5033_50331301_99_dialog_content = "Then what are you waiting for?",
  ui_story_5033_50331301_100_dialog_content = "You know me, Pollux. You know I could never do that.",
  ui_story_5033_50331301_101_dialog_content = "I didn't come here just to tell you these old stories...",
  ui_story_5033_50331301_102_dialog_content = "I'm going to take care of that scum who's been using me for so many years, and remove the most dangerous threat to you in the process.",
  ui_story_5033_50331301_103_dialog_content = "Do you expect me to be grateful?",
  ui_story_5033_50331301_104_dialog_content = "Not in the slightest. I came only to see you one last time, before we say goodbye once more.",
  ui_story_5033_50331301_105_dialog_content = "My dearest Pollux... I hope that when this is all over, you know what needs to be done.",
  ui_story_5033_50331301_106_dialog_content = "Er...",
  ui_story_5033_50331301_107_dialog_content = "You really are selfish.",
  ui_story_5033_50331301_108_dialog_content = "Worming your way into my friendship and my knife into your body... Even \"dead,\" you still somehow managed to control my fate...",
  ui_story_5033_50331301_109_dialog_content = "And now you stand before me so grandiose, your words arrogant.",
  ui_story_5033_50331301_110_dialog_content = "<color=#e8d9bb>Bang—!</color>",
  ui_story_5033_50331301_111_dialog_content = "Looks like time's up.",
  ui_story_5033_50331301_112_dialog_content = "People... No, Eclipsites, entering from the rear.",
  ui_story_5033_50331301_113_dialog_content = "You're sharp now, Pollux, very sharp. Almost like a totally different person to back then.",
  ui_story_5033_50331301_114_dialog_content = "Long hair suits you too. But what happened to your eyes?",
  ui_story_5033_50331301_115_dialog_content = "... I have nothing I wish to share with you.",
  ui_story_5033_50331301_116_dialog_content = "But I do...",
  ui_story_5033_50331301_117_dialog_content = "And share it with you I shall, as soon as I'm finished with the first part of my atonement.",
  ui_story_5033_50331302_1_dialog_content = "Latan, Schewe...",
  ui_story_5033_50331302_2_dialog_content = "Good, we've got everyone.",
  ui_story_5033_50331302_3_dialog_content = "Everyone needs to stay here, and not go running off. Understood?",
  ui_story_5033_50331302_4_dialog_content = "I can help! Pollux taught me how to fight!",
  ui_story_5033_50331302_5_dialog_content = "Me too!",
  ui_story_5033_50331302_6_dialog_content = "Settle down. It's not...",
  ui_story_5033_50331302_7_dialog_content = "As it happens, I need some trained guards right here. Heaven knows if that gang of hoodlums will turn up.",
  ui_story_5033_50331302_8_dialog_content = "If only you guys could stay here and keep an eye on the entrances and exits, that would be a massive help.",
  ui_story_5033_50331302_9_dialog_content = "Awesome! I'm gonna assemble a special task force right away!!",
  ui_story_5033_50331302_10_dialog_content = "A few more boards to nail over the windows would be wonderful too.",
  ui_story_5033_50331302_11_dialog_content = "Roger. Let's go, Latan!",
  ui_story_5033_50331302_12_dialog_content = "Copy that!",
  ui_story_5033_50331302_13_dialog_content = "You sure it's okay for the kids to stay here?",
  ui_story_5033_50331302_14_dialog_content = "It's too dangerous to send them anywhere else now, anyway.",
  ui_story_5033_50331302_15_dialog_content = "I've never had this many people here all at once, though, and I don't know how long our provisions will last.",
  ui_story_5033_50331302_16_dialog_content = "Don't worry. This matter shouldn't take long.",
  ui_story_5033_50331302_17_dialog_content = "Gustav. You're here.",
  ui_story_5033_50331302_18_dialog_content = "Think of something, quickly, before it all kicks off at the church. You know everything about Euphoria, don't you?",
  ui_story_5033_50331302_19_dialog_content = "From what I hear, the situation is critical.",
  ui_story_5033_50331302_20_dialog_content = "Many of those surrounding the church are from one gang or another. All I need to do is get in touch with their leaders, and I should be able to sort this out.",
  ui_story_5033_50331302_21_dialog_content = "But the key question is what to do about ordinary civilians.",
  ui_story_5033_50331302_22_dialog_content = "Everyone now knows that Pollux is sheltering Umbraton people in the church. I'm afraid that will take more than a few nice words to sort out.",
  ui_story_5033_50331302_23_dialog_content = "...",
  ui_story_5033_50331302_24_dialog_content = "You must be that Umbraton lad, right?",
  ui_story_5033_50331302_25_dialog_content = "I guess Taki never mentioned us to you?",
  ui_story_5033_50331302_26_dialog_content = "He told me that you were coming, but never mentioned the massive headache you'd bring with you.",
  ui_story_5033_50331302_27_dialog_content = "Now all of Euphoria think that the Shadowlord sent you lot here to destroy the place.",
  ui_story_5033_50331302_28_dialog_content = "But we haven't done anything!",
  ui_story_5033_50331302_29_dialog_content = "Hmph! It's a bit late for you to say that now.",
  ui_story_5033_50331302_30_dialog_content = "Investigating is investigating, but did you really have to provoke the locals and get involved with the Raven's Blood?",
  ui_story_5033_50331302_31_dialog_content = "Do you have any idea just how antagonistic Raven's Blood usually is?",
  ui_story_5033_50331302_32_dialog_content = "Gang status has always been defined by strength in Euphoria. We did nothing against the norm.",
  ui_story_5033_50331302_33_dialog_content = "I warned you long ago not to offend too many people, or you'll earn yourself enemies bearing grudges. But did you listen?",
  ui_story_5033_50331302_34_dialog_content = "And look what's happened! Now all the gangs have banded together to wipe you guys out, and I can't stop them.",
  ui_story_5033_50331302_35_dialog_content = "Pollux is quite the clever one, somehow sneaking you a lot out of there. Speaking of which, where is she?",
  ui_story_5033_50331302_36_dialog_content = "She stayed behind in the church to buy us some time. In fact, we have to go back for her right now!",
  ui_story_5033_50331302_37_dialog_content = "Let's go! They may even be fighting already!",
  ui_story_5033_50331302_38_dialog_content = "Calm yourself, Casta. There's something I need to tell you first...",
  ui_story_5033_50331302_39_dialog_content = "A very dangerous individual is here in Euphoria.",
  ui_story_5033_50331302_40_dialog_content = "I suspect she's the one you two came here to look for.",
  ui_story_5033_50331302_41_dialog_content = "You mean those cases...?",
  ui_story_5033_50331302_42_dialog_content = "Did there happen to be a nun, among your companions?",
  ui_story_5033_50331302_43_dialog_content = "Well, yes, but she took her leave a while back.",
  ui_story_5033_50331302_44_dialog_content = "Don't tell me...",
  ui_story_5033_50331302_45_dialog_content = "She killed one of my lookouts, over at the church. She's there right now.",
  ui_story_5033_50331302_46_dialog_content = "What?!",
  ui_story_5033_50331302_47_dialog_content = "Are you telling me that creep, the one who killed Matilda, is at the church right now?!",
  ui_story_5033_50331302_48_dialog_content = "Yes. It's got all the same hallmarks as the Umbraton case. It has to be her.",
  ui_story_5033_50331302_49_dialog_content = "Wait a sec, how do you know all of this?",
  ui_story_5033_50331302_50_dialog_content = "Intelligence is my bread and butter, lad.",
  ui_story_5033_50331302_51_dialog_content = "That's not all I know, either. I also know a little secret that I'm sure Pollux would be very interested in...",
  ui_story_5033_50331302_52_dialog_content = "That \"nun\" is no servant of the god of light.",
  ui_story_5033_50331302_53_dialog_content = "She and Pollux used to be called Gemini as members of the organization, and her name is <color=#FFB400>Antares</color>.",
  ui_story_5033_50331302_54_dialog_content = "What did you say?!",
  ui_story_5033_50331302_55_dialog_content = "Hold on! Isn't the person you are talking about dead?",
  ui_story_5033_50331302_56_dialog_content = "That's right! This is impossible. Pollux has clearly...",
  ui_story_5033_50331302_57_dialog_content = "I was just skeptical as you when this information first reached my ears. But I assure you, it is true.",
  ui_story_5033_50331302_58_dialog_content = "Not only did she survive, but she's been gathering her strength for years. And now, she's decided to take her revenge on Euphoria.",
  ui_story_5033_50331302_59_dialog_content = "What are we waiting for? Pollux is bound to be in trouble!",
  ui_story_5033_50331302_60_dialog_content = "Yeah... If she can kill people without blinking, I can't think what else she might be capable of...",
  ui_story_5033_50331302_61_dialog_content = "We can't allow her to continue stirring up trouble.",
  ui_story_5033_50331302_62_dialog_content = "Are you certain of this, Gustav?",
  ui_story_5033_50331302_63_dialog_content = "Listen, lad, I've told you where to find the person you seek. Whether or not you can catch her, is up to you.",
  ui_story_5033_50331302_64_dialog_content = "That bastard...",
  ui_story_5033_50331302_65_dialog_content = "Why don't you go with them, Gustav? You may need to get a grip on the situation as it's hard for them to fight with Antares...",
  ui_story_5033_50331302_66_dialog_content = "Hahaha, you don't need to worry about me getting a grip on the situation. Leave it to me.",
  ui_story_5033_50331302_67_dialog_content = "You just focus on finding the murderer and revealing the truth to everyone",
  ui_story_5033_50331302_68_dialog_content = "I'll try to help assuage the anger that Euphoria feels towards you...",
  ui_story_5033_50331401_1_dialog_content = "<color=#e8d9bb>*Rumbles...*</color>",
  ui_story_5033_50331401_2_dialog_content = "Was that an explosion? Or thunder?",
  ui_story_5033_50331401_3_dialog_content = "Pick up the pace, Caelestite. How are you slower than these old bones?",
  ui_story_5033_50331401_4_dialog_content = "I'm so sorry...",
  ui_story_5033_50331401_5_dialog_content = "I need to talk to you, Casta.",
  ui_story_5033_50331401_6_dialog_content = "I know what you want to say.",
  ui_story_5033_50331401_7_dialog_content = "She has to die.",
  ui_story_5033_50331401_8_dialog_content = "You...",
  ui_story_5033_50331401_9_dialog_content = "Casta, I know that you and Pollux are furious about Matilda.",
  ui_story_5033_50331401_10_dialog_content = "But I don't think this is such a simple situation. Have you ever thought about why she is doing all this?",
  ui_story_5033_50331401_11_dialog_content = "Because she wants revenge on Pollux, and all of Euphoria for her \"death.\"",
  ui_story_5033_50331401_12_dialog_content = "That's possible. But why now, after so many years?",
  ui_story_5033_50331401_13_dialog_content = "I can't say.",
  ui_story_5033_50331401_14_dialog_content = "Why commit so many high-profile crimes and only then go looking for Pollux?",
  ui_story_5033_50331401_15_dialog_content = "I don't know.",
  ui_story_5033_50331401_16_dialog_content = "And why...",
  ui_story_5033_50331401_17_dialog_content = "<size=45>I don't know, and I don't want to know!</size>",
  ui_story_5033_50331401_18_dialog_content = "Pollux had killed her once, so she killed Sister Matilda, who had saved Pollux.",
  ui_story_5033_50331401_19_dialog_content = "Brings all the suspicion onto Pollux and then comes back to Euphoria while you're following leads.",
  ui_story_5033_50331401_20_dialog_content = "Is it difficult to understand that this is all to get revenge on Pollux?",
  ui_story_5033_50331401_21_dialog_content = "Calm down first, and think what Pollux would do!",
  ui_story_5033_50331401_22_dialog_content = "Pollux wouldn't cover Antares!",
  ui_story_5033_50331401_23_dialog_content = "She'd do exactly what I would—cut her to pieces!",
  ui_story_5033_50331401_24_dialog_content = "Casta!",
  ui_story_5033_50331401_25_dialog_content = "Hey, don't eat that! Spit it out...",
  ui_story_5033_50331401_26_dialog_content = "<color=#e8d9bb>Ding-dong, Ding-dong—</color>",
  ui_story_5033_50331401_27_dialog_content = "Listen, you're not to eat this, understood? Now run along and play somewhere else.",
  ui_story_5033_50331401_28_dialog_content = "Phew... Finally got the little guys settled.",
  ui_story_5033_50331401_29_dialog_content = "<color=#e8d9bb>Knock, knock, knock!</color>",
  ui_story_5033_50331401_30_dialog_content = "Who is it?",
  ui_story_5033_50331401_31_dialog_content = "Open the door, quickly! I'm Eho, Umbraton Courier Union special agent!",
  ui_story_5033_50331401_32_dialog_content = "You scared me half to death! What are you doing here? Have you got my package?",
  ui_story_5033_50331401_33_dialog_content = "Um, super-expedited-rush delivery from Umbraton!",
  ui_story_5033_50331401_34_dialog_content = "Keep it down, would you?! Give it here.",
  ui_story_5033_50331401_35_dialog_content = "<color=#e8d9bb>*Paper unfolding*</color>",
  ui_story_5033_50331401_36_dialog_content = "\"This is Taki. I cannot contact Corax, so I'm trying my luck with you.\"",
  ui_story_5033_50331401_37_dialog_content = "\"A victim survived the serial killer, and he's awake. You have to tell Corax right away...\"",
  ui_story_5033_50331401_38_dialog_content = "\"The suspect is a nun, with gray hair and eyes. Pictures are below...\"",
  ui_story_5033_50331401_39_dialog_content = "\"But she's not the mastermind! There's still someone behind her pulling strings!\"",
  ui_story_5033_50331401_40_dialog_content = "What?",
  ui_story_5033_50331401_41_dialog_content = "<size=42>\"It's <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_42_dialog_content = "<size=42>\"Behind the scenes, it's all <color=#FFB400>Gustav</color>!\"</size>",
  ui_story_5033_50331401_43_dialog_content = "Atonement? Share? What exactly are you doing here...?",
  ui_story_5033_50331401_44_dialog_content = "I'm only here because I wanted to tell you that I found out who's pulling the strings behind all this.",
  ui_story_5033_50331401_45_dialog_content = "Wait for me to finish him and I can give you your life back.",
  ui_story_5033_50331401_46_dialog_content = "I owe this to you.",
  ui_story_5033_50331401_47_dialog_content = "I don't need it! I'm gonna hand you over to Umbraton.",
  ui_story_5033_50331401_48_dialog_content = "I'm afraid that won't do... I don't want to die at anyone's hand but yours.",
  ui_story_5033_50331401_49_dialog_content = "Are you crazy?!",
  ui_story_5033_50331401_50_dialog_content = "Why, yes! I've been crazy for a long time.",
  ui_story_5033_50331401_51_dialog_content = "Ever since I was born a child of Euphoria... Ever since I joined that organization...",
  ui_story_5033_50331401_52_dialog_content = "As far as I'm concerned, killing is as natural as breathing.",
  ui_story_5033_50331401_53_dialog_content = "I had never been truly awake.",
  ui_story_5033_50331401_54_dialog_content = "Until I found my first friend... You were like my guiding star, showing me the way...",
  ui_story_5033_50331401_55_dialog_content = "Shut it! The second you killed Sister Matilda, we lost any chance of being friends.",
  ui_story_5033_50331401_56_dialog_content = "No... The second I raised my knife to you, you were not my friend.",
  ui_story_5033_50331401_57_dialog_content = "No, Pollux, that was the fault of the organization! Gustav is to blame for everything...",
  ui_story_5033_50331401_58_dialog_content = "Everything will be over, so long as they are gone.",
  ui_story_5033_50331401_59_dialog_content = "<size=45>Gustav?!</size>",
  ui_story_5033_50331401_60_dialog_content = "Yes. As I said, I finally discovered who's pulling the strings behind the scenes.",
  ui_story_5033_50331401_61_dialog_content = "Gustav... He was part of the organization and was once the Boss' right-hand man.",
  ui_story_5033_50331401_62_dialog_content = "He's really a member?",
  ui_story_5033_50331401_63_dialog_content = "Have you got any proof?",
  ui_story_5033_50331401_64_dialog_content = "I regret to say that I do not.",
  ui_story_5033_50331401_65_dialog_content = "It's all testimony heard from the mouths of dying men.",
  ui_story_5033_50331401_66_dialog_content = "<color=#e8d9bb>Crash—</color>",
  ui_story_5033_50331401_67_dialog_content = "<size=45>You really are here, Antares!!</size>",
  ui_story_5033_50331401_68_dialog_content = "Uh...",
  ui_story_5033_50331401_69_dialog_content = "Pollux, are you okay?!",
  ui_story_5033_50331401_70_dialog_content = "I'm fine. What about the children? Did you get them safe?",
  ui_story_5033_50331401_71_dialog_content = "This woman is no nun! She murdered Sister Matilda!",
  ui_story_5033_50331401_72_dialog_content = "If you don't avenge her, I will!",
  ui_story_5033_50331401_73_dialog_content = "*Coughs*",
  ui_story_5033_50331401_74_dialog_content = "<size=45>You killed Matilda...!!</size>",
  ui_story_5033_50331401_75_dialog_content = "Casta, you...",
  ui_story_5033_50331401_76_dialog_content = "It's okay, Pollux. She's really a very promising child...",
  ui_story_5033_50331401_77_dialog_content = "<size=45>Where's your weapon?! Draw it now!</size>",
  ui_story_5033_50331401_78_dialog_content = "<size=45>I'm gonna make you pay... for Matilda!</size>",
  ui_story_5033_50331401_79_dialog_content = "Did you... did you see that? It was so fast, it just smashed straight through the wall!",
  ui_story_5033_50331401_80_dialog_content = "Look! Gustav's here!",
  ui_story_5033_50331401_81_dialog_content = "Sorry I'm late, everybody.",
  ui_story_5033_50331401_82_dialog_content = "Gustav, sir! Tell us what to do, please! Pollux has those Umbraton scum...",
  ui_story_5033_50331401_83_dialog_content = "Everyone, just calm down. I'll explain everything to you in just a little while.",
  ui_story_5033_50331401_84_dialog_content = "But before then, let these guys through.",
  ui_story_5033_50331401_85_dialog_content = "...",
  ui_story_5033_50331401_86_dialog_content = "Huh? HUH?!",
  ui_story_5033_50331401_87_dialog_content = "What are you doing here? When did you show up?",
  ui_story_5033_50331401_88_dialog_content = "We have to get to the church, PlayerName! Casta's losing control!",
  ui_story_5033_50331401_89_dialog_content = "<color=#e8d9bb>Bang, Bang!</color>",
  ui_story_5033_50331401_90_dialog_content = "Casta... That is your name, right?",
  ui_story_5033_50331401_91_dialog_content = "<size=45>Fight back! Who do you think you're looking down on?! Counterattack!</size>",
  ui_story_5033_50331401_92_dialog_content = "I still need time to wrap things up, so I'm afraid I cannot perish here. But I will never raise my hand against you...",
  ui_story_5033_50331401_93_dialog_content = "Seeing as you're important to Pollux...",
  ui_story_5033_50331401_94_dialog_content = "...",
  ui_story_5033_50331401_95_dialog_content = "You do NOT get to speak that name, murderer!",
  ui_story_5033_50331401_96_dialog_content = "STOP, Casta!",
  ui_story_5033_50331401_97_dialog_content = "<size=45>Get out of here!</size>",
  ui_story_5033_50331401_98_dialog_content = "I won't let you sabotage my mission... This is the Shadowlord's Highest Decree!",
  ui_story_5033_50331401_99_dialog_content = "She must be brought back alive!",
  ui_story_5033_50331401_100_dialog_content = "<size=45>I said GET OUT OF HERE!!</size>",
  ui_story_5033_50331401_101_dialog_content = "Help me get her under control, PlayerName!",
  ui_story_5033_50331402_1_dialog_content = "<color=#e8d9bb>Whizz! Thump!</color>",
  ui_story_5033_50331402_2_dialog_content = "You... Scum...",
  ui_story_5033_50331402_3_dialog_content = "I'm sorry. I had to fight seriously to stop you.",
  ui_story_5033_50331402_4_dialog_content = "Murderer! Over here! The murderer is over here!",
  ui_story_5033_50331402_5_dialog_content = "That's enough, Casta.",
  ui_story_5033_50331402_6_dialog_content = "Calmed down?",
  ui_story_5033_50331402_7_dialog_content = "Pollux, she killed Matilda...",
  ui_story_5033_50331402_8_dialog_content = "I know.",
  ui_story_5033_50331402_9_dialog_content = "She killed Matilda...",
  ui_story_5033_50331402_10_dialog_content = "And I will avenge her, just not today.",
  ui_story_5033_50331402_11_dialog_content = "Yes, I will atone... Once all this is over.",
  ui_story_5033_50331402_12_dialog_content = "If anyone is going to take Anne's life, it will be me. Do you understand?",
  ui_story_5033_50331402_13_dialog_content = "We have an understanding, she and I.",
  ui_story_5033_50331402_14_dialog_content = "Pollux...",
  ui_story_5033_50331402_15_dialog_content = "Anne, no, Antares.",
  ui_story_5033_50331402_16_dialog_content = "We meet again, PlayerName, Corax.",
  ui_story_5033_50331402_17_dialog_content = "All of those things were your doing, Antares?",
  ui_story_5033_50331402_18_dialog_content = "You're responsible for Sister Matilda's death?",
  ui_story_5033_50331402_19_dialog_content = "Seems like you've got it all figured out.",
  ui_story_5033_50331402_20_dialog_content = "That's right, I'm the one you're looking for.",
  ui_story_5033_50331402_21_dialog_content = "Hate to break it to you, but I'm not really a nun either. My apologies for deceiving you.",
  ui_story_5033_50331402_22_dialog_content = "Why... Why did you kill those people? And why did you come here?",
  ui_story_5033_50331402_23_dialog_content = "<size=42>What?! Really?!</size>",
  ui_story_5033_50331402_24_dialog_content = "Why are those people making a ruckus again? Wasn't Gustav meant to be in control?",
  ui_story_5033_50331402_25_dialog_content = "Hang on, have you seen him?",
  ui_story_5033_50331402_26_dialog_content = "Yeah, he came with us.",
  ui_story_5033_50331402_27_dialog_content = "So where is he now?",
  ui_story_5033_50331402_28_dialog_content = "I don't know. He didn't come in with us.",
  ui_story_5033_50331402_29_dialog_content = "He's dangerous! He's the mastermind behind all of this!",
  ui_story_5033_50331402_30_dialog_content = "What? Mastermind?",
  ui_story_5033_50331402_31_dialog_content = "I can explain, Pollux.",
  ui_story_5033_50331402_32_dialog_content = "What you're saying is for real, Gustav?",
  ui_story_5033_50331402_33_dialog_content = "That's right. She's Pollux's closest friend... Antares.",
  ui_story_5033_50331402_34_dialog_content = "Must be horrible, associating with someone like that... Why would she do this, anyway?",
  ui_story_5033_50331402_35_dialog_content = "Why deliberately stir up trouble with Umbraton?!",
  ui_story_5033_50331402_36_dialog_content = "She must be using it as a pretext to take over the profit chains of Euphoria and Umbraton.",
  ui_story_5033_50331402_37_dialog_content = "Including those Umbraton investigators, they're probably just making a show of it.",
  ui_story_5033_50331402_38_dialog_content = "I wouldn't be surprised if everything in Euphoria is already priced and up for grabs.",
  ui_story_5033_50331402_39_dialog_content = "But how come they're fighting here? Is it some kind of internal strife?",
  ui_story_5033_50331402_40_dialog_content = "Excuse me, everyone. I'm sorry but I must have a word with Mr. Gustav.",
  ui_story_5033_50331402_41_dialog_content = "So?",
  ui_story_5033_50331402_42_dialog_content = "Neither Pollux nor Casta has been able to take care of Antares.",
  ui_story_5033_50331402_43_dialog_content = "Are they unable to? Or just delayed?",
  ui_story_5033_50331402_44_dialog_content = "I'm sorry, I cannot say for sure.",
  ui_story_5033_50331402_45_dialog_content = "Impossible... That level of hate and animosity... How could it be like... Are you sure of this?",
  ui_story_5033_50331402_46_dialog_content = "At the very least, Antares is still alive, and...",
  ui_story_5033_50331402_47_dialog_content = "Go on.",
  ui_story_5033_50331402_48_dialog_content = "She seems to have told them everything.",
  ui_story_5033_50331402_49_dialog_content = "Seems things can't get much worse...",
  ui_story_5033_50331402_50_dialog_content = "So what is our next move?",
  ui_story_5033_50331402_51_dialog_content = "Next move...",
  ui_story_5033_50331402_52_dialog_content = "<color=#e8d9bb>*Rumble—*</color>",
  ui_story_5033_50331402_53_dialog_content = "I only know what our last move will be.",
  ui_story_5033_50331402_54_dialog_content = "Tell everyone it's time to do this.",
  ui_story_5033_50331402_55_dialog_content = "If we do not deal with Raven's Blood right here, right now, then Euphoria will never see a day of peace.",
  ui_story_5033_50331501_1_dialog_content = "Pollux! Come out here! You traitor to Euphoria!",
  ui_story_5033_50331501_2_dialog_content = "Pollux! POLLUX!",
  ui_story_5033_50331501_3_dialog_content = "Po...",
  ui_story_5033_50331501_4_dialog_content = "Wow! She... She really came out...",
  ui_story_5033_50331501_5_dialog_content = "Who's calling me?",
  ui_story_5033_50331501_6_dialog_content = "...",
  ui_story_5033_50331501_7_dialog_content = "What, you finally dare show your face?",
  ui_story_5033_50331501_8_dialog_content = "You're looking well, Gustav. I suppose your daily gin and tonics are to thank.",
  ui_story_5033_50331501_9_dialog_content = "Not really. They're just to numb me, as this Euphoria offers ample disappointments already, no?",
  ui_story_5033_50331501_10_dialog_content = "You didn't run. I rather admire that.",
  ui_story_5033_50331501_11_dialog_content = "And why would I run? I'm here to take care of everything. After all, Euphoria needs someone who can take charge.",
  ui_story_5033_50331501_12_dialog_content = "<color=#e8d9bb>Da, da—</color>",
  ui_story_5033_50331501_13_dialog_content = "Hey, it's the nun?!",
  ui_story_5033_50331501_14_dialog_content = "G-Get back, Gustav says she is a maniac...",
  ui_story_5033_50331501_15_dialog_content = "Everyone, allow me to introduce you to someone.",
  ui_story_5033_50331501_16_dialog_content = "Serial killer of Umbraton, sinner of Euphoria, and former organization member, Gemini—Antares.",
  ui_story_5033_50331501_17_dialog_content = "...",
  ui_story_5033_50331501_18_dialog_content = "Wh-What? Readily confessed?",
  ui_story_5033_50331501_19_dialog_content = "That's Pollux for you, behaving admirably even in such a hopeless situation.",
  ui_story_5033_50331501_20_dialog_content = "What about you? As the mastermind behind all this, it'll be easier if you just confess it as well.",
  ui_story_5033_50331501_21_dialog_content = "Seems like you have the story all written, Gustav.",
  ui_story_5033_50331501_22_dialog_content = "Such a shame then that my prisoner here has a different confession. Would you like to hear?",
  ui_story_5033_50331501_23_dialog_content = "Honorable people of Euphoria! Do you wish to know the truth?",
  ui_story_5033_50331501_24_dialog_content = "This gentleman before you, Gustav, is not just the know-all of Euphoria...",
  ui_story_5033_50331501_25_dialog_content = "He is also a former high-ranking official in the organization.",
  ui_story_5033_50331501_26_dialog_content = "Organization? Does that mean the... organization that the Boss managed over a decade ago?",
  ui_story_5033_50331501_27_dialog_content = "Wasn't that a group for raising assassins? Gustav's just a normal intelligence agent, right?",
  ui_story_5033_50331501_28_dialog_content = "The organization fell apart twelve years ago, thanks to the Eclipsite invasion. But to Gustav here, this was a golden opportunity.",
  ui_story_5033_50331501_29_dialog_content = "Using his Intelligence House identity, he began courting and winning over the gangs, and re-establishing order, in an attempt to gradually take over Euphoria.",
  ui_story_5033_50331501_30_dialog_content = "But more importantly, he also had his hands on a lethal weapon...",
  ui_story_5033_50331501_31_dialog_content = "<color=#FFB400>Antares</color>.",
  ui_story_5033_50331501_32_dialog_content = "What? The nun works for Gustav?",
  ui_story_5033_50331501_33_dialog_content = "For the past several years, Antares has been executing his orders, taking out anyone who still had control over Euphoria's profit chains.",
  ui_story_5033_50331501_34_dialog_content = "Umbraton's anger needed a scapegoat, so his final order was to have Anne come back here, to kill me...",
  ui_story_5033_50331501_35_dialog_content = "Or rather, have us kill each other.",
  ui_story_5033_50331501_36_dialog_content = "Hmm... I can kinda see how that makes sense.",
  ui_story_5033_50331501_37_dialog_content = "No, no! We only have her word for it!",
  ui_story_5033_50331501_38_dialog_content = "But Gustav's the same, no? We shouldn't blindly believe him either, just because he runs the Intelligence House...",
  ui_story_5033_50331501_39_dialog_content = "Drat... Have we really all been played?",
  ui_story_5033_50331501_40_dialog_content = "<size=45>Pollux! Enough!</size>",
  ui_story_5033_50331501_41_dialog_content = "These good people are not fools! They won't be deceived by your lies.",
  ui_story_5033_50331501_42_dialog_content = "You just want to throw me under the bus, and make me take the blame for masterminding all this.",
  ui_story_5033_50331501_43_dialog_content = "You know fully what you've done, and you'll pay for it, even without hard proof!",
  ui_story_5033_50331501_44_dialog_content = "Listen to what you're saying, Sister. I feel embarrassed for you.",
  ui_story_5033_50331501_45_dialog_content = "If your back's against the wall and you ultimately mean to kill me, an old man, then come at me!",
  ui_story_5033_50331501_46_dialog_content = "But I will not run if you can produce even a shred of proof.",
  ui_story_5033_50331501_47_dialog_content = "<size=45>I have proof!</size>",
  ui_story_5033_50331501_48_dialog_content = "I have proof! Right here!",
  ui_story_5033_50331501_49_dialog_content = "Nekoyashiki?!",
  ui_story_5033_50331501_50_dialog_content = "...?!",
  ui_story_5033_50331501_51_dialog_content = "Step aside! All of you, out of my way!",
  ui_story_5033_50331501_52_dialog_content = "You want proof, Gustav? I've got your proof right here!",
  ui_story_5033_50331501_53_dialog_content = "This is just in from Umbraton, the testimony of a survivor!",
  ui_story_5033_50331501_54_dialog_content = "A... Survivor?!",
  ui_story_5033_50331501_55_dialog_content = "...",
  ui_story_5033_50331501_56_dialog_content = "The killer was a nun—her! And the one who arranged it all, planned it all—",
  ui_story_5033_50331501_57_dialog_content = "<size=45>Was none other than you, Gustav!</size>",
  ui_story_5033_50331501_58_dialog_content = "No way... Impossible... There's no way anyone could survive that!",
  ui_story_5033_50331501_59_dialog_content = "This is fake evidence!",
  ui_story_5033_50331501_60_dialog_content = "This is false information! You're all ganging up to beat me, aren't you?!",
  ui_story_5033_50331501_61_dialog_content = "\"Jimmy Odenkirk, 47 years old, woke from a grave coma...\"",
  ui_story_5033_50331501_62_dialog_content = "\"... According to his description, the suspect was dressed as a nun, with gray hair...\"",
  ui_story_5033_50331501_63_dialog_content = "Enough...",
  ui_story_5033_50331501_64_dialog_content = "\"I was invited there that day by Gustav of Euphoria... We walked into a trap, and none of my men made it out...\"",
  ui_story_5033_50331501_65_dialog_content = "ENOUGH!! I don't need to listen to this slanderous nonsense!!",
  ui_story_5033_50331501_66_dialog_content = "If you still don't admit it, then let's make our cases to the Shadowlord!",
  ui_story_5033_50331501_67_dialog_content = "Let's see what excuses you pair of villains come up with then!",
  ui_story_5033_50331501_68_dialog_content = "I don't have time to indulge your nonsense! Don't just stand there, grab Nekoyashiki and the other traitors!",
  ui_story_5033_50331501_69_dialog_content = "Uhh...",
  ui_story_5033_50331501_70_dialog_content = "Did you hear what I said?!",
  ui_story_5033_50331501_71_dialog_content = "What you're saying is for real, Nekoyashiki?",
  ui_story_5033_50331501_72_dialog_content = "Maybe it's better to wait and see, not be so quick to jump to conclusions... Things are too fluid...",
  ui_story_5033_50331501_73_dialog_content = "Quick, look at Gustav's hideous expression...",
  ui_story_5033_50331501_74_dialog_content = "What is the meaning of this...",
  ui_story_5033_50331501_75_dialog_content = "You useless bunch of good-for-nothings! Have you forgotten who your boss is?!",
  ui_story_5033_50331501_76_dialog_content = "Forgotten the damage Umbraton inflicted on this place?!",
  ui_story_5033_50331501_77_dialog_content = "What's this guy saying? There's no way he's the boss of us!",
  ui_story_5033_50331501_78_dialog_content = "Oi, Gustav! You'd better give us a good explanation! What is going on?",
  ui_story_5033_50331501_79_dialog_content = "And all of your little minions too, are you all in it together?",
  ui_story_5033_50331501_80_dialog_content = "No-No! None of my business... I've got nothing to do with him!",
  ui_story_5033_50331501_81_dialog_content = "Hehe... Hahaha!",
  ui_story_5033_50331501_82_dialog_content = "Very well. You've brought this on yourselves.",
  ui_story_5033_50331501_83_dialog_content = "You've forced me to do this!",
  ui_story_5033_50331501_84_dialog_content = "<color=#e8d9bb>Clang... Clink...</color>",
  ui_story_5033_50331501_85_dialog_content = "Huh? Is that Darkflow...?",
  ui_story_5033_50331501_86_dialog_content = "<anim type=Shake><size=45>Graaagh!</size></anim>",
  ui_story_5033_50331501_87_dialog_content = "Oh no! Eclipsites!",
  ui_story_5033_50331501_88_dialog_content = "Go! Run amok as you will... Call your buddies and make some mischief!",
  ui_story_5033_50331501_89_dialog_content = "<anim type=Shake><size=45>Graaagh—!</size></anim>",
  ui_story_5033_50331501_90_dialog_content = "Eclipsites! Eclipsites everywhere!",
  ui_story_5033_50331501_91_dialog_content = "Curses! How did they manage to surround us? There's no way out!",
  ui_story_5033_50331501_92_dialog_content = "You... Vermin! You let the Eclipsites out? They're just going to attract more!",
  ui_story_5033_50331501_93_dialog_content = "D-Don't come any closer! Uraaaagh!!",
  ui_story_5033_50331501_94_dialog_content = "Gustav! Save us!",
  ui_story_5033_50331501_95_dialog_content = "I'm dreadfully sorry, everyone. Just let Euphoria...",
  ui_story_5033_50331501_96_dialog_content = "Be cleansed.",
  ui_story_5033_50331502_1_dialog_content = "Argh! Help! Save me!!",
  ui_story_5033_50331502_2_dialog_content = "My legs! I can't move!",
  ui_story_5033_50331502_3_dialog_content = "Stop yelling. It's just a flesh wound.",
  ui_story_5033_50331502_4_dialog_content = "There aren't any Eclipsites over here. Just go find your companion.",
  ui_story_5033_50331502_5_dialog_content = "Okay, okay... Thanks...",
  ui_story_5033_50331502_6_dialog_content = "If you want to thank anyone, thank Pollux. You almost burned the church down, and yet she's still willing to go to the trouble to save you.",
  ui_story_5033_50331502_7_dialog_content = "Corax! On your left!",
  ui_story_5033_50331502_8_dialog_content = "Damn! How do they keep coming?!",
  ui_story_5033_50331502_9_dialog_content = "I don't know. Maybe some local Eclipsites got lured over too?",
  ui_story_5033_50331502_10_dialog_content = "What about Antares? Have you seen her?",
  ui_story_5033_50331502_11_dialog_content = "Let me look for her with my psychic ability! It's total chaos around here!",
  ui_story_5033_50331502_12_dialog_content = "Hey! Have you seen Pollux?",
  ui_story_5033_50331502_13_dialog_content = "No... We're also looking...",
  ui_story_5033_50331502_14_dialog_content = "I just saw her on the other side of the church! Over there!",
  ui_story_5033_50331502_15_dialog_content = "What about Gustav? He couldn't have escaped, could he?",
  ui_story_5033_50331502_16_dialog_content = "Hey, Gustav! Wait up!",
  ui_story_5033_50331502_17_dialog_content = "Move! Get out of my way...",
  ui_story_5033_50331502_18_dialog_content = "<anim type=Shake><size=45>Graaaugh...!</size></anim>",
  ui_story_5033_50331502_19_dialog_content = "Urgh!",
  ui_story_5033_50331502_20_dialog_content = "Antares.",
  ui_story_5033_50331502_21_dialog_content = "Did you let these Eclipsites out, Gustav?",
  ui_story_5033_50331502_22_dialog_content = "You want everyone to die with you?",
  ui_story_5033_50331502_23_dialog_content = "What, are you telling me you pity these guys?",
  ui_story_5033_50331502_24_dialog_content = "Pity? Sorry, but I couldn't care less about their lives.",
  ui_story_5033_50331502_25_dialog_content = "You're truly merciless, Antares. And truly worthy of being one of the Gemini...",
  ui_story_5033_50331502_26_dialog_content = "But I'm particularly puzzled by your actions just now.",
  ui_story_5033_50331502_27_dialog_content = "Do you really still hold out hope for redemption?",
  ui_story_5033_50331502_28_dialog_content = "You cannot possibly think you can be forgiven for publicly naming me and preaching whatever you call justice?",
  ui_story_5033_50331502_29_dialog_content = "... Oh no. Of course not.",
  ui_story_5033_50331502_30_dialog_content = "You're going to pay for this! And you alone!",
  ui_story_5033_50331502_31_dialog_content = "EVERYTHING I've done has been for Euphoria... You don't understand, cannot comprehend!",
  ui_story_5033_50331502_32_dialog_content = "All you have are those tedious and trifling friendships and bonds! You cannot see what I see!",
  ui_story_5033_50331502_33_dialog_content = "Euphoria has been a total mess for twelve years, Antares!",
  ui_story_5033_50331502_34_dialog_content = "Those Umbraton guys don't care if we live or die, while the locals don't even have the courage or strength to rebuild!",
  ui_story_5033_50331502_35_dialog_content = "There is only me! You know, I am the only one who can step up!",
  ui_story_5033_50331502_36_dialog_content = "To restore a diseased limb, one must excise the rotten flesh and pick out the maggots...",
  ui_story_5033_50331502_37_dialog_content = "And you, Antares, are my scalpel. An excellent tool for excising...",
  ui_story_5033_50331502_38_dialog_content = "After today, Euphoria can likewise be reborn.",
  ui_story_5033_50331502_39_dialog_content = "It's just that neither of us can see it.",
  ui_story_5033_50331502_40_dialog_content = "...",
  ui_story_5033_50331502_41_dialog_content = "<color=#e8d9bb>Clink—</color>",
  ui_story_5033_50331502_42_dialog_content = "Put down your weapon, Gustav. The way things are, you haven't got a chance.",
  ui_story_5033_50331502_43_dialog_content = "Here you are at last, Pollux. This is truly a... fortunate development.",
  ui_story_5033_50331502_44_dialog_content = "It's about time you emerged from your cozy little church, onto the corpse-strewn streets.",
  ui_story_5033_50331502_45_dialog_content = "What are you trying to say?",
  ui_story_5033_50331502_46_dialog_content = "Hahahah...",
  ui_story_5033_50331502_47_dialog_content = "Don't sell this place out, Pollux, don't sell it out.",
  ui_story_5033_50331502_48_dialog_content = "If you really want to...",
  ui_story_5033_50331502_49_dialog_content = "At least get a good price for it.",
  ui_story_5033_50331502_50_dialog_content = "What are you planning, Gustav?!",
  ui_story_5033_50331502_51_dialog_content = "I don't need your help... I can end this myself!",
  ui_story_5033_50331502_52_dialog_content = "I will not die in disgrace like the Boss... I refuse...",
  ui_story_5033_50331502_53_dialog_content = "Urgh!",
  ui_story_5033_50331502_54_dialog_content = "He killed himself.",
  ui_story_5033_50331502_55_dialog_content = "I'd had other plans for him. He got off lightly.",
  ui_story_5033_50331502_56_dialog_content = "Guess I'll have to rain check on that. Save them for <color=#FFB400>others</color>.",
  ui_story_5033_50331502_57_dialog_content = "Others?",
  ui_story_5033_50331502_58_dialog_content = "Pollux, you see those people down there, holding torches and carrying molotovs?",
  ui_story_5033_50331502_59_dialog_content = "I cannot see their faces clearly. To me, they all look the same: hideous, foolish, and hopeless.",
  ui_story_5033_50331502_60_dialog_content = "Anne, it's over. It's finished. You just need to come back to Umbraton and face your fate, then...",
  ui_story_5033_50331502_61_dialog_content = "One thing Gustav said made sense.",
  ui_story_5033_50331502_62_dialog_content = "We're all festering parts of Euphoria, dirty wounds that will never fully heal.",
  ui_story_5033_50331502_63_dialog_content = "Only by removing these rotten parts can it ever really be reborn.",
  ui_story_5033_50331502_64_dialog_content = "What do you want to do?",
  ui_story_5033_50331502_65_dialog_content = "Fulfill my mission as the Grim Reaper.",
  ui_story_5033_50331502_66_dialog_content = "Oh no, then we... Save us! Run!",
  ui_story_5033_50331502_67_dialog_content = "Antares!",
  ui_story_5033_50331502_68_dialog_content = "Your heart is just as soft as ever, Pollux. That's why I say you haven't changed, even after all these years.",
  ui_story_5033_50331502_69_dialog_content = "But a grave illness needs potent medicine.",
  ui_story_5033_50331502_70_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5033_50331502_71_dialog_content = "What's that flying right for us?! Take cover—!",
  ui_story_5033_50331502_72_dialog_content = "<color=#e8d9bb>Wham!</color>",
  ui_story_5033_50331502_73_dialog_content = "Crazy woman... How can you involve innocent civilians?!",
  ui_story_5033_50331502_74_dialog_content = "Casta! Help! Stop this nun, quickly!",
  ui_story_5033_50331502_75_dialog_content = "Pollux! Do something!",
  ui_story_5033_50331502_76_dialog_content = "I...",
  ui_story_5033_50331502_77_dialog_content = "Anne, I know what you're doing. But not this... There's no need for this.",
  ui_story_5033_50331502_78_dialog_content = "We had a deal.",
  ui_story_5033_50331502_79_dialog_content = "You also heard the ironclad evidence that gentleman publicly produced just now...",
  ui_story_5033_50331502_80_dialog_content = "Even if I had no interest in cleaning up Euphoria, I still couldn't let these witnesses live.",
  ui_story_5033_50331502_81_dialog_content = "Shut up, Anne... Just stop...",
  ui_story_5033_50331502_82_dialog_content = "And I'll start with the person closest to me.",
  ui_story_5033_50331502_83_dialog_content = "Argh! Back! Get back!",
  ui_story_5033_50331502_84_dialog_content = "You're also the only one who can stop me.",
  ui_story_5033_50331502_85_dialog_content = "Are you ready?",
  ui_story_5033_50331502_86_dialog_content = "Do you really have to do this?!",
  ui_story_5033_50331502_87_dialog_content = "<size=30>I won't let you take me away, Pollux. I wish to stay in Euphoria, albeit in my own way.</size>",
  ui_story_5033_50331502_88_dialog_content = "<size=30>In the only way left to me, to atone for my sins.</size>",
  ui_story_5033_50331502_89_dialog_content = "...",
  ui_story_5033_50331502_90_dialog_content = "That's enough.",
  ui_story_5033_50331502_91_dialog_content = "I don't have anywhere near as grand ideals, Anne.",
  ui_story_5033_50331502_92_dialog_content = "This is just for Matilda.",
  ui_story_5033_50331502_93_dialog_content = "Of course, this too is for Matilda.",
  ui_story_5033_50331502_94_dialog_content = "Beat her, Pollux! For Euphoria!",
  ui_story_5033_50331502_95_dialog_content = "For Euphoria! Euphoria!",
  ui_story_5033_50331502_96_dialog_content = "Let's get started. I hope you've still got it.",
  ui_story_5033_50331502_97_dialog_content = "Don't you worry, I remember the essentials. Those I'll never forget...",
  ui_story_5033_50331502_98_dialog_content = "I still have one final question, Anne.",
  ui_story_5033_50331502_99_dialog_content = "Heh. Ask.",
  ui_story_5033_50331502_100_dialog_content = "If you had a second chance, would you still do that?",
  ui_story_5033_50331502_101_dialog_content = "Do you mean with Gustav...",
  ui_story_5033_50331502_102_dialog_content = "No. I mean that time, 14 years ago...",
  ui_story_5033_50331502_103_dialog_content = "Would you still get stabbed by me?",
  ui_story_5033_50331502_104_dialog_content = "Yes. If I had a second chance, I would run at you just the same.",
  ui_story_5033_50331502_105_dialog_content = "And then I'd hold you tight, and bid you farewell.",
  ui_story_5033_50331502_106_dialog_content = "Just like right now...",
  ui_story_5033_50331502_107_dialog_content = "<color=#e8d9bb>*Stab—*</color>",
  ui_story_5033_50331502_108_dialog_content = "...",
  ui_story_5033_50331502_109_dialog_content = "Your eyes are much more resolute than they were back then.",
  ui_story_5033_50331502_110_dialog_content = "You've changed, Pollux. It's good to see.",
  ui_story_5033_50331502_111_dialog_content = "And... You actually kept... that dagger...",
  ui_story_5033_50331502_112_dialog_content = "Not anymore. I'm going to bury it after today.",
  ui_story_5033_50331502_113_dialog_content = "Goodbye, my Pollux.",
  ui_story_5033_50331502_114_dialog_content = "Farewell... Antares, full of sin.",
  ui_story_5033_50331502_115_dialog_content = "Now, finally, I am the same as you.",
  ui_story_5033_50331502_116_dialog_content = "Po—",
  ui_story_5033_50331502_117_dialog_content = "?!",
  ui_story_5033_50331502_118_dialog_content = "This... Antares, and Gustav?!",
  ui_story_5033_50331502_119_dialog_content = "...",
  ui_story_5033_50331502_120_dialog_content = "Pollux! Are you alright?",
  ui_story_5033_50331502_121_dialog_content = "...",
  ui_story_5033_50331502_122_dialog_content = "Corax, can you help me check?",
  ui_story_5033_50331502_123_dialog_content = "Gustav is dead. Let me check on Anne...",
  ui_story_5033_50331502_124_dialog_content = "No need.",
  ui_story_5033_50331502_125_dialog_content = "What?",
  ui_story_5033_50331502_126_dialog_content = "There's no need, doctor.",
  ui_story_5033_50331502_127_dialog_content = "Your mission... <color=#FFB400>has failed</color>.",
  ui_story_5033_50331502_128_dialog_content = "<color=#e8d9bb>*Rumble*</color>",
  ui_story_5033_50331601_1_dialog_content = "<color=#e8d9bb>Several hours later</color>",
  ui_story_5033_50331601_2_dialog_content = "... So, it really was Gustav pulling the strings.",
  ui_story_5033_50331601_3_dialog_content = "I've been saying for ages that he was using everyone, but no one listened. Hmph.",
  ui_story_5033_50331601_4_dialog_content = "It seems that the murderous nun is dead. Taken out by Pollux herself.",
  ui_story_5033_50331601_5_dialog_content = "I expected nothing less from Pollux... We're lucky to have her...",
  ui_story_5033_50331601_6_dialog_content = "I heard they grew up together. I guess it was something she couldn't overlook?",
  ui_story_5033_50331601_7_dialog_content = "No gossiping behind people's backs.",
  ui_story_5033_50331601_8_dialog_content = "If you really don't have anything else to do, then you can help me repair the walls and windows of the church. The children still need somewhere to live.",
  ui_story_5033_50331601_9_dialog_content = "You're old enough to take on some of the responsibility.",
  ui_story_5033_50331601_10_dialog_content = "Yeah, yeah...",
  ui_story_5033_50331601_11_dialog_content = "Nekoyashiki, for the time being, everyone has returned to the church.",
  ui_story_5033_50331601_12_dialog_content = "Well done, Latan.",
  ui_story_5033_50331601_13_dialog_content = "So, uh, what of Pollux? We're all really worried...",
  ui_story_5033_50331601_14_dialog_content = "She... She's tying up a few loose ends with Casta.",
  ui_story_5033_50331601_15_dialog_content = "They're just up in those hills behind us, and should be back soon. You go on inside, it's still raining.",
  ui_story_5033_50331601_16_dialog_content = "The rain stopped ages ago, Nekoyashiki.",
  ui_story_5033_50331601_17_dialog_content = "\"... Her difficult path has come to an end, and yet a new journey awaits.\"",
  ui_story_5033_50331601_18_dialog_content = "\"She shall return to the land, and merge with the lakes...\"",
  ui_story_5033_50331601_19_dialog_content = "\"And finally, return to stardust.\"",
  ui_story_5033_50331601_20_dialog_content = "...",
  ui_story_5033_50331601_21_dialog_content = "The sky's clearing, Pollux.",
  ui_story_5033_50331601_22_dialog_content = "Ah, it's so bright. Has the sun always been this dazzling...?",
  ui_story_5033_50331601_23_dialog_content = "Do you see that the mist is gone as well? So this is what Euphoria is really like.",
  ui_story_5033_50331601_24_dialog_content = "Thank you, PlayerName, for offering to read Anne's eulogy.",
  ui_story_5033_50331601_25_dialog_content = "I'm ashamed to admit that I can't even do this, despite living in the church for so many years.",
  ui_story_5033_50331601_26_dialog_content = "Oh, maybe you just can't find a way to express yourself.",
  ui_story_5033_50331601_27_dialog_content = "Perhaps the ordinary eulogy, given to so many people every day, isn't suitable for Antares.",
  ui_story_5033_50331601_28_dialog_content = "Anyway, I'm sorry for your loss.",
  ui_story_5033_50331601_29_dialog_content = "I'm not grieving. On the contrary, I'm quite relieved.",
  ui_story_5033_50331601_30_dialog_content = "It's like waking up from a chaotic dream, having seen people you'll never see again.",
  ui_story_5033_50331601_31_dialog_content = "But now I have woken from the dream, the sky is bright, and I must continue to walk my own path.",
  ui_story_5033_50331601_32_dialog_content = "So what's next?",
  ui_story_5033_50331601_33_dialog_content = "I think I'll stay here for a while.",
  ui_story_5033_50331601_34_dialog_content = "Not just because of the kids in the church, but also because it's rare to see Euphoria so clearly.",
  ui_story_5033_50331601_35_dialog_content = "This is probably what Antares wished to see too.",
  ui_story_5033_50331601_36_dialog_content = "Perhaps. Or perhaps she wanted to atone for her sins by my hand.",
  ui_story_5033_50331601_37_dialog_content = "She was a really tricky one.",
  ui_story_5033_50331601_38_dialog_content = "If she had really died fourteen years ago, and not been used by anyone...",
  ui_story_5033_50331601_39_dialog_content = "Or if we hadn't been made to kill each other, and Gemini had continued...",
  ui_story_5033_50331601_40_dialog_content = "Or what if we had never even known each other?",
  ui_story_5033_50331601_41_dialog_content = "Antares and Pollux, just two total strangers, going about their lives.",
  ui_story_5033_50331601_42_dialog_content = "Would the story be any different?",
  ui_story_5033_50331601_43_dialog_content = "What would be Euphoria's new destiny?",
  ui_story_5033_50331601_44_dialog_content = "Come on, Pollux. It's not like you to be so nostalgic.",
  ui_story_5033_50331601_45_dialog_content = "You're right. I'm ready to say goodbye to the past.",
  ui_story_5033_50331601_46_dialog_content = "That knife, and the hydrangea brooch...",
  ui_story_5033_50331601_47_dialog_content = "Let them rest in peace along with Antares.",
  ui_story_5033_50331601_48_dialog_content = "That reminds me, we haven't paid our respects to Matilda this year.",
  ui_story_5033_50331601_49_dialog_content = "Oh, that's right. Let me get everything taken care of around here, then we should find a time to visit Umbraton.",
  ui_story_5033_50331601_50_dialog_content = "Alright, I won't disturb you any further. Goodbye, Pollux, Casta.",
  ui_story_5033_50331601_51_dialog_content = "Are you off to the airship Shuttle Hub by yourself?",
  ui_story_5033_50331601_52_dialog_content = "With everyone running around like headless chickens, the road might be even rougher.",
  ui_story_5033_50331601_53_dialog_content = "But Corax went back to Umbraton alone again, said something about making a report...",
  ui_story_5033_50331601_54_dialog_content = "I'll go with you.",
  ui_story_5033_50331601_55_dialog_content = "Yeah, let Casta go along.",
  ui_story_5033_50331601_56_dialog_content = "I still have some... other matters to attend to. You guys go ahead.",
  ui_story_5033_50331601_57_dialog_content = "I believe we'll meet again, PlayerName. Just wait for Euphoria to become a true wonderland.",
  ui_story_5033_50331601_58_dialog_content = "Of course, Pollux. I look forward to that day.",
  ui_story_5033_50331601_59_dialog_content = "<color=#e8d9bb>Umbraton, two days later</color>",
  ui_story_5033_50331601_60_dialog_content = "Read all about it! Criminal in Umbraton serial killings dead during capture!",
  ui_story_5033_50331601_61_dialog_content = "Care for a paper, Mr. Corax?",
  ui_story_5033_50331601_62_dialog_content = "How did you recognize me...?",
  ui_story_5033_50331601_63_dialog_content = "Get away from me, go on.",
  ui_story_5033_50331601_64_dialog_content = "Alright, no need to be so mean. Read all about it!",
  ui_story_5033_50331601_65_dialog_content = "...",
  ui_story_5033_50331601_66_dialog_content = "You're late.",
  ui_story_5033_50331601_67_dialog_content = "Casta's not a great airship pilot.",
  ui_story_5033_50331601_67X1_dialog_content = "Follow me.",
  ui_story_5033_50331601_68_dialog_content = "<color=#e8d9bb>*Page turning*</color>",
  ui_story_5033_50331601_69_dialog_content = "What's this...?",
  ui_story_5033_50331601_70_dialog_content = "Case closed. Shadowlord has viewed the file, and the matter is settled roughly as described.",
  ui_story_5033_50331601_71_dialog_content = "Good. Thank you, Corax.",
  ui_story_5033_50331601_72_dialog_content = "You really should be thanking me!",
  ui_story_5033_50331601_73_dialog_content = "I was clearly there on a mission but didn't manage to bring back either of the two suspects, sorry, two criminals.",
  ui_story_5033_50331601_74_dialog_content = "Haha, that really is unlucky.",
  ui_story_5033_50331601_75_dialog_content = "I...",
  ui_story_5033_50331601_76_dialog_content = "Let's leave that for now. Keep going, you'll find another document.",
  ui_story_5033_50331601_77_dialog_content = "It's Shadowlord's plan to rebuild Euphoria with you. See if there are any issues.",
  ui_story_5033_50331601_78_dialog_content = "With Gustav dead, it must be crazy over there.",
  ui_story_5033_50331601_79_dialog_content = "There are a lot of Umbraton gangs who depend on Euphoria for a living. We'll have to come up with some new ideas.",
  ui_story_5033_50331601_80_dialog_content = "Shadowlord doesn't want to tread the same old path. Otherwise, there's no difference with those wretches. You understand?",
  ui_story_5033_50331601_81_dialog_content = "I agree. That's what I was thinking too.",
  ui_story_5033_50331601_82_dialog_content = "The rotting flesh has already been excised. It's time to start again.",
  ui_story_5033_50331601_83_dialog_content = "That's a good analogy. Euphoria was the gravely ill patient who finally had its necrotic parts removed...",
  ui_story_5033_50331601_84_dialog_content = "It's time for a new treatment that will lead to healthy tissue.",
  ui_story_5033_50331601_85_dialog_content = "Yes, and the new treatment is Umbraton's reconstruction plan.",
  ui_story_5033_50331601_86_dialog_content = "Those children can finally grow up as Euphoria's healthy tissue.",
  ui_story_5033_50331601_87_dialog_content = "What else is in the plan, Corax? Aside from industrial restructuring?",
  ui_story_5033_50331601_88_dialog_content = "Anything like social welfare?",
  ui_story_5033_50331601_89_dialog_content = "Are you thinking of an orphanage?",
  ui_story_5033_50331601_90_dialog_content = "Relax! Feel free to mention anything you like. I don't think Shadowlord will reject these suggestions.",
  ui_story_5033_50331601_91_dialog_content = "After all, he's a big fan of taking in children... Ahem.",
  ui_story_5033_50331601_92_dialog_content = "Seems like I have something in common with him after all—we're both optimistic pessimists.",
  ui_story_5033_50331601_93_dialog_content = "I think I get that.",
  ui_story_5033_50331601_94_dialog_content = "You can both believe that the world is beyond help yet still have hope for the next generation.",
  ui_story_5033_50331601_95_dialog_content = "Kids' eyes don't lie, Corax. Just go to an orphanage or school, and you can see for yourself.",
  ui_story_5033_50331601_96_dialog_content = "Those are the only pure, good places left.",
  ui_story_5033_50331601_97_dialog_content = "I believe we have to rely on those children if Euphoria is ever to be sunny again.",
  ui_story_5033_50331601_98_dialog_content = "Just like Matilda believed in us, all those years ago.",
  ui_story_5033_50331601_99_dialog_content = "...",
  ui_story_5033_50331601_100_dialog_content = "That's enough chat. We'll look at the plans again and get back to you.",
  ui_story_5033_50331601_101_dialog_content = "If there's nothing else, I'll take my leave.",
  ui_story_5033_50331601_102_dialog_content = "Let me see you at the Shuttle Hub.",
  ui_story_5033_50331601_103_dialog_content = "No need, but thank you. I want to visit the cemetery.",
  ui_story_5033_50331601_104_dialog_content = "To pay your respects to Matilda? I think I'd like that too, is that ok?",
  ui_story_5033_50331601_105_dialog_content = "Of course. Thank you, Corax.",
  ui_story_5033_50331601_106_dialog_content = "C'mon, what's with all the \"thank you\" today? I'm not used to you being so formal.",
  ui_story_5033_50331601_107_dialog_content = "<color=#e8d9bb>Colossus, Bridge</color>",
  ui_story_5033_50331601_108_dialog_content = "Right size for curtains. Could be a skirt, with a few more meters.",
  ui_story_5033_50331601_109_dialog_content = "*Sigh*",
  ui_story_5033_50331601_110_dialog_content = "Dining table, floor lamp, carpet... Is there any chromatic aberration with the carpet?",
  ui_story_5033_50331601_111_dialog_content = "*Sigh*",
  ui_story_5033_50331601_112_dialog_content = "Shelf, check... Where's the cartoon chopping board? Ah, here it is.",
  ui_story_5033_50331601_113_dialog_content = "*Sigh...*",
  ui_story_5033_50331601_114_dialog_content = "Are you alright, PlayerName? Is all of this tiring you out?",
  ui_story_5033_50331601_115_dialog_content = "I'm just feeling a little down, Vice.",
  ui_story_5033_50331601_116_dialog_content = "What happened these past couple of days seems like a dream.",
  ui_story_5033_50331601_117_dialog_content = "Why are you always going on these bizarre adventures when I'm away, hmm?",
  ui_story_5033_50331601_118_dialog_content = "What's the story this time?",
  ui_story_5033_50331601_119_dialog_content = "Let me organize my thoughts. I don't even know where to begin.",
  ui_story_5033_50331601_120_dialog_content = "Alright. Anyway, what's up with this... \"Healthy Hydrangea\"?",
  ui_story_5033_50331601_121_dialog_content = "An impulse purchase, and one I immediately regretted. It attracts loads of bugs.",
  ui_story_5033_50331601_122_dialog_content = "Still, leave it there. I like looking at it.",
  ui_story_5033_50331601_123_dialog_content = "Oh, you. You look like you have the world on your shoulders.",
  ui_story_5033_50331601_124_dialog_content = "You've gotta tell me what happened this time.",
  ui_story_5033_50331601_125_dialog_content = "Fine. Have you heard of Euphoria?",
  ui_story_5033_50331601_126_dialog_content = "Hmm... Rings a bell.",
  ui_story_5033_50331601_127_dialog_content = "Well, it all starts with this place called Euphoria..."
}
